t[682]={{tags="spawn",text="Many tigers are found around coordinates 46,15.",v=44},{tags="spawn",text="Tigers are plentiful around 29,10 on the western plateau near the troll ruins, where they share spawn points with panthers.",v=18},{tags="spawn",text="Tigers spawn east of the river, north of Venture Co. Base Camp.",v=1}}
