t[1061]={{tags="spawn",text="He has a long respawn timer, so expect a long wait between kills.",v=68},{tags="danger",text="Bodyguards stand around him, and up to five mobs can be pulled together.",v=68},{tags="spawn",text="He has been found at 23,8.",v=23}}
