t[1831]={{tags="danger spawn",text="These NPCs usually spawn in a pack with invokers, knights, or medics; a safer one to pull is near the tent between Felstone Field and Dalson's Tears.",v=6}}
t[1837]={{tags="inside route",text="He is inside a house similar to the Darkshire mayor's house in Hearthglen; clear the mobs outside to reach him.",v=20},{tags="danger",text="Two Scarlet Paladins stand in the back of the room; avoid aggroing them when fighting the Scarlet Judge.",v=1}}
t[1842]={{tags="floor inside danger",text="He is high up inside Mardenholde Keep, guarded by four level 58 elite guards, with two more roving the corridors.",v=2}}
t[1844]={{tags="spawn patrol",text="He wanders among the tents in the Scarlet lumberjack camp west of the lumber mill, often standing near the dreamfoil in the camp center.",v=3},{tags="inside spawn",text="He sometimes spawns inside the lumber mill building, standing near the front by the giant saw.",v=3},{tags="spawn",text="He is a random rare spawn, not an elite, so he does not always appear at the camp.",v=1}}
t[1854]={{tags="hidden",text="Found in the level 50-52 graveyard near Chillwind Point, in the south-eastern corner by Uther's statue.",v=2}}
t[1855]={{tags="danger route",text="Avoid the cave at 16,30 in the Eastern Plaguelands; it has spiders and an elite mob. Go up the river path instead.",v=11},{tags="route inside",text="Tirion is at a house on the river in the Eastern Plaguelands near 7.5,43.7; stay close to the east side of the river to find him.",v=5},{tags="route",text="A path at 13.5,71.9 follows the river to him without needing to swim.",v=2}}
