t[1961]={{tags="spawn",text="Mangeclaw respawns at the exact same spot, 78,37, every five minutes.",v=49},{tags="route inside",text="Reach him at North Gate Outpost: go through the first tunnel, take the left path, and run past the snow leopards to a small circular clearing.",v=9}}
t[1963]={{tags="inside",text="Find her inside the Stoutlager Inn in Thelsamar, standing behind the tavern counter.",v=20}}
t[1971]={{tags="inside route",text="Ivar is inside the barn by the patch; the barn entrance is at 51,14.",v=32}}
