t[2044]={{tags="access",text="The Forlorn Spirit only appears after a quest triggers it.",v=51}}
t[2050]={{tags="route inside",text="From the west banker, take the west stairs and walk straight toward the cooks; he is the one on the far right of the center area.",v=1}}
