t[2078]={{tags="access route",text="He appears only after you find and kill Ursal the Mauler, then return to Dolanaar; he is at 55,57.",v=11},{tags="inside route",text="He is inside a building just north of the inn in Dolanaar.",v=1}}
t[2086]={{tags="inside",text="Valstag stands inside the Keep of Menethil Harbor, right at the entrance near the first fork in the road.",v=6}}
t[2089]={{tags="spawn",text="Respawn is very slow, so kill each one as soon as it appears and expect long waits between kills.",v=35},{tags="spawn",text="Crocolisks also spawn on the east coast of Menethil Bay around 17,59.",v=35},{tags="spawn",text="Crocolisks spawn in the lake east of Menethil Harbour, in the eastern half of the lake, around 17,61.",v=24}}
t[2090]={{tags="floor inside",text="Look on top of the orc scouting tower or bunker in the Wetlands camp near Dun Algaz; he stands there at 48,74.",v=16},{tags="spawn",text="After he is killed, he takes about 5-6 hours to respawn.",v=16},{tags="danger route",text="You must fight your way through the camp to reach the tower; once up top, he can be killed without extra aggro.",v=13}}
t[2091]={{tags="danger",text="Orc guards stand around his camp next to him; clear the ones closest to him before engaging.",v=17},{tags="route",text="Take the back entrance: pass the normal entrance on the road and follow the path to reach Nek'rosh more easily.",v=3}}
