t[2104]={{tags="floor inside route",text="Captain Stoutfist is on the third floor of the keep in Menethil Harbor: go through the dining hall, up the back stairs, then up the ramp to a large hall, and he stands at its far end.",v=31}}
t[2107]={{tags="floor inside",text="He is upstairs in the house in the middle of the area.",v=1}}
t[2108]={{tags="danger",text="He is flanked by two guards when he spawns, so send your pet at him directly and deal with the guards afterward.",v=9},{tags="route",text="Enter the Angerfang Encampment, take the first right and go up the hill to the red tent at the top, just before the drop into the excavation site; he spawns there at about 42,45.",v=6}}
t[2120]={{tags="inside",text="Archmage Ataeric is inside the Town Hall.",v=4},{tags="danger",text="Two Dalaran Conjurors with Voidwalkers and a Dalaran Protector guard him, and he attacks when you enter the room.",v=4}}
