t[2542]={{tags="floor inside",text="She stands on the staircase leading to the second floor of the Booty Bay Inn, one floor up from the innkeeper.",v=106}}
t[2545]={{tags="route",text="Leave Booty Bay through the entrance and turn left or west at the T in the road; Duncan is in a camp on the coast around 27,69.",v=18},{tags="spawn",text="If Duncan is not at the camp, wait for him to respawn.",v=7},{tags="danger",text="Duncan stands in a Bloodsail camp with campfire and crates, surrounded by several pirate mobs who may aggro if you pull him from land.",v=3}}
t[2548]={{tags="spawn",text="Captain Keelhaul respawns 7 minutes after he dies, so wait that long before expecting him to return.",v=9}}
t[2551]={{tags="inside route",text="Brutus is on the anchored boat at 32,88, not on land; he drives the ship.",v=39}}
t[2557]={{tags="danger route",text="Kill the axe throwers and witch doctors blocking the cave entrance; a fireplace a few turns in has many mobs, so keep to the right wall.",v=27},{tags="inside route",text="Shadow hunters are inside a cave deep south of the lake, at 68,74.",v=20}}
t[2563]={{tags="spawn",text="Plains Creepers respawn randomly in the same spots as raptors; killing a raptor there may bring a spider back within about a minute.",v=1}}
t[2564]={{tags="inside",text="They are underground inside the cave.",v=16}}
t[2570]={{tags="route inside",text="Reach the ogre area through a hole southeast of the tower, found by following the outside of Stromgarde's west wall around the keep.",v=9}}
t[2586]={{tags="hidden",text="Syndicate Highwaymen are always stealthed and hard to see; find them on the road leading toward the farm.",v=7}}
t[2597]={{tags="floor inside danger route",text="He is at the top of Stormgarde castle, in the room with Otto and 4-5 elite guards.",v=5},{tags="danger",text="Otto and elite guards, including Prowlers, stand in the throne room with him.",v=5},{tags="spawn",text="He spawns roughly every 5-7 minutes after being killed, not every 10 minutes.",v=1}}
t[2605]={{tags="spawn",text="He spawns roughly every 36 to 48 hours.",v=1},{tags="inside route",text="Enter the cave at 68,75 to reach him.",v=1}}
end)()
