t[3058]={{tags="patrol hidden",text="He walks clockwise along his route and is hard to find, so follow his loop.",v=81},{tags="spawn",text="He respawns about one minute after death at this spot, which is his main spawn point.",v=34},{tags="danger",text="If you attack him while kodo families are nearby, they join the fight and gang up on you.",v=1}}
t[3059]={{tags="inside",text="Harutt is at one end of a large tipi in Camp Narache, so look inside the tipi at its far end.",v=1}}
t[3060]={{tags="inside",text="Gart Mistrunner stands inside a small tipi in the Tauren starter encampment of Camp Narache.",v=1}}
t[3061]={{tags="inside",text="Lanka stands at one end of a large tipi in the Tauren starter encampment of Camp Narache; look inside the tipi.",v=1}}
t[3062]={{tags="inside",text="Meela Dawnstrider stands inside a small tipi in the Tauren starter encampment of Camp Narache, beside Gart Mistrunner.",v=2}}
t[3068]={{tags="patrol",text="Roams the area south of Thunder Bluff, not far from the path; one sighting was at 41,43.",v=16},{tags="patrol",text="Found just west and slightly north of the Venture Co. water well.",v=9},{tags="spawn patrol",text="Sightings cluster on the road near 37-39,44 in Mulgore; it has been seen spawning slightly northwest of 38,44.",v=6}}
t[3085]={{tags="inside hidden",text="In the kitchen area of the Lakeshire inn, to the left of the door; not visible from the main room.",v=7}}
t[3094]={{tags="access hidden",text="These units are invisible, not stealthed. You need Detect Invisibility or Greater Detect Invisibility to see them; Lesser Detect Invisibility does not work.",v=174},{tags="spawn",text="They respawn fairly quickly after being killed.",v=20},{tags="inside",text="They are inside the houses south of Raven Hill Cemetery, and more than one can be in the same house.",v=2}}
t[3107]={{tags="patrol",text="Surf Crawlers roam mostly in the waters between the islands, all over the Echo Isles; one was seen at 62,75.",v=23}}
t[3121]={{tags="route",text="Reach the tigers from Theramore by running north along the coast past the turtles and between the murloc isles.",v=21},{tags="route",text="Ride the Ratchet boat toward Booty Bay and jump off as soon as you near the Echo Isle tiger island.",v=5}}
t[3133]={{tags="hidden",text="Look right behind the broken cart with the rake, just outside the quest start, to find him.",v=1}}
t[3147]={{tags="floor inside",text="Furl is at the top of the guard tower northwest of Razor Hill, so climb to the top floor.",v=12}}
t[3159]={{tags="inside",text="He is at the very back of the cave in the Valley of Trials, near where you would hearth.",v=1}}
t[3169]={{tags="access",text="Players report he no longer offers the Defensive Stance quest after about level 31, so it may be unobtainable from him.",v=7}}
t[3170]={{tags="inside",text="He is inside the lookout hut.",v=3}}
t[3175]={{tags="inside",text="Krunn is inside the small building just north of the Inn.",v=4}}
t[3183]={{tags="spawn",text="Yarrog respawns every 90 to 120 seconds at the spot 42.7, 53.0.",v=1}}
t[3190]={{tags="hidden",text="Rhinag hides in the tall pointed rocks just west of Rocktust Farm, outside Orgrimmar's main gate.",v=1}}
t[3192]={{tags="floor inside",text="He is on the upper floor of the little castle, inside the keep.",v=6},{tags="floor route",text="He is at the top of the keep on the ramp side; battle up through the keep and take the ramp.",v=1},{tags="danger",text="Three more Marines stand with him at the top of the keep on the ramp side.",v=1}}
t[3199]={{tags="inside route",text="The cave entrance is on top of the ravine's east edge, not at the harpy spot, and is a rock-covered opening at about 52,29.",v=27},{tags="inside danger",text="The cultists are inside the cave, past low-level mobs (about level 9-11) at the entrance.",v=1}}
t[3203]={{tags="danger",text="He stands at 42,26 surrounded by several Burning Blades and an imp.",v=13},{tags="route",text="Walk north from 39,31 to about 40,24, then nearly U-turn into Thunder Ridge, where a group of mobs waits.",v=10},{tags="route",text="Or walk northwest to Tor'kren Farm at 43,28 and drop down into Thunder Ridge at 40,26.",v=10}}
t[3204]={{tags="spawn inside",text="One of Gazz'uz's spawn points is right beside the chest that holds the tablet inside Skull Rock.",v=49},{tags="inside hidden",text="Gazz'uz is in the back of the Skull Rock cave in northeast Durotar.",v=7}}
t[3208]={{tags="access",text="Margoz is only reachable after completing the Dark Storms quest, which gives you the quest to find him.",v=13}}
t[3216]={{tags="inside hidden",text="He is in a small hut in the Cleft of Shadow, directly in front of the RFC entrance next to the mushroom vendor. He is hard to find at first.",v=20}}
