t[6026]={{tags="route",text="He stands on the docks in Shadowprey Village at 22,74, not where the map shows him.",v=10}}
t[6030]={{tags="inside hidden",text="He stands inside the tower, in the right-hand corner as you enter; he is easy to walk past.",v=5}}
t[6034]={{tags="floor inside",text="Lotherias is on Craftsman's Terrace in Darnassus, upstairs in the leatherworking building.",v=8}}
t[6068]={{tags="spawn patrol",text="Warug's Bodyguard wanders with the centaur group near the big bonfire on the hill north/northeast of the camp, around 74,67.",v=1},{tags="danger",text="Attacking one bodyguard makes the others join the fight; the whole camp is yellow and killing one changes faction reputation.",v=1},{tags="patrol danger",text="A group wandering the camp with dogs sometimes comes up the hill.",v=1}}
