t[6072]={{tags="spawn floor",text="He has multiple spawn points, mostly on the lowest level of the den but sometimes in a higher cave.",v=89},{tags="route inside floor",text="Enter the den through the hut at 78,82 near the Grom monument path, then follow the winding path down, keeping right at each bridge intersection to reach the small room at the bottom.",v=54},{tags="patrol danger",text="Legion Hound packs patrol the den and can wander into his room while you fight him.",v=37}}
t[6089]={{tags="inside",text="He stands in front of the bar inside the Pig and Whistle Tavern, in the northeast corner of Old Town.",v=3}}
t[6093]={{tags="spawn",text="Dead-Tooth Jack has a very short respawn time, so be ready to catch him again quickly.",v=12}}
t[6094]={{tags="inside hidden",text="She is in the building north of the Inn, with the Priest trainer.",v=1}}
t[6109]={{tags="patrol",text="He wanders around Azshara rather than staying in one place, so his position changes between spawns.",v=53},{tags="interact danger",text="Talking to him makes him hostile and he attacks, so avoid his dialogue options.",v=20},{tags="spawn",text="He spawns only in Azshara, never in Trisifal Glades.",v=6}}
t[6113]={{tags="route",text="Vejrek stands alone outside a small hut in the hills south of the Frostmane cave and encampment, not inside the cave; a brown minimap patch south of the hold marks him.",v=8}}
t[6121]={{tags="floor inside route",text="Remen Marcot is in the basement of the Lion's Pride Inn in Goldshire; take the stairs behind the butcher's table in the back room.",v=32}}
t[6124]={{tags="inside",text="Captain Beld is located at 76,62 inside the Ironband compound.",v=4}}
t[6125]={{tags="spawn",text="Haldarr Satyrs spawn rarely and at random types; kill the Felsworn, Trickster and Satyr mobs at the Haldarr Encampment until one appears.",v=19}}
t[6128]={{tags="route",text="Go up the mountain to find him; an entrance to his location is at 49,59.",v=10}}
t[6133]={{tags="patrol",text="She wanders around the sunken boat near coordinates 32,44.",v=28}}
t[6140]={{tags="patrol",text="She wanders between a rock at 56,44, a spot at 59,40, an underwater spot at 59,47, and an island spot at 58,41, roaming roughly 56,50 to 59,41.",v=17},{tags="patrol",text="She is found on the island that contains Scalebeard's Cave.",v=4},{tags="patrol hidden",text="She wanders underwater and looks like a green three-headed hydra; she is sometimes stationary on a small island above water.",v=1}}
t[6146]={{tags="spawn",text="Cliff Breakers share spawns with other giants, so if none are appearing, killing Thunderers and Walkers may bring them.",v=4}}
t[6167]={{tags="spawn",text="Search the southern Charred Vale near the road to Desolace, east of the southern exit, around 32,74 and 32,72.",v=13},{tags="spawn",text="She is rare and respawns after an unpredictable wait, from about 5 minutes to over an hour.",v=13}}
t[6170]={{tags="spawn inside",text="Gutspill spawns plenty when camped at the cave but has been reported to respawn quickly, dying three times in five minutes.",v=19}}
t[6172]={{tags="access",text="Kill the wizard from Virgil's Heroes before resurrecting Henze Faulk, or he dies again.",v=1}}
t[6174]={{tags="route",text="Go past the main Stormwind gates, beyond Tria's Cheese, to the Apothecary; she stands right under the city direction signpost near 57,61.",v=11}}
t[6175]={{tags="patrol",text="He roams around Ironforge near the Inn, so look for him there rather than at a fixed spot.",v=5}}
t[6176]={{tags="inside route",text="Bath'rah is inside a hut at Chillwind Point. Reach it by following the river north from Tarren Mill in Hillsbrad and staying on the east bank.",v=7}}
