t[10806]={{tags="spawn route",text="Ursius spawns after you kill yeti on the hill near 59,33; kill the yeti and check for him after each kill, since it may take a few.",v=21},{tags="spawn patrol",text="Ursius wanders around the base of the mountain north of Everlook at about 63,25-63,26 and respawns roughly 10 minutes after he leaves.",v=18},{tags="patrol",text="Ursius walks slowly back and forth along a fixed path over the small mountain west of the twin mountains north of Everlook, past Moon Horror Den, and turns around halfway up the hills east of it.",v=2}}
t[10807]={{tags="spawn",text="She spawns at 58,62 and respawns about 7 minutes after being killed.",v=44},{tags="patrol route",text="She walks a route from her spawn north through the western part of the zone, past the blue dragonkin, and turns back near 54,45; she also passes through the Cobalt dragon area around 57,53.",v=44}}
t[10822]={{tags="floor spawn",text="Find him atop the temple in Zul'Mashar at 72,14, on the top floor.",v=12},{tags="spawn",text="He also spawns in the huts or lookout posts along the main road to Zul'Mashar at 65,22, outside the city.",v=10}}
t[10823]={{tags="danger",text="Two guards stand next to him in the courtyard, and attacking him makes them aggro the whole courtyard.",v=10}}
