t[10837]={{tags="access interact",text="A box on the ground next to Derrington becomes lootable only during the unlisted quest, and it contains the fire bottle you need.",v=3},{tags="spawn",text="Derrington disappears from the Bulwark after you complete the unlisted quest; he no longer appears there.",v=1}}
t[10838]={{tags="route",text="Commander Ashlam Valorfist is at 42,84 in Western Plaguelands.",v=8},{tags="route",text="Reach him by taking the road east through Strahnbrad, then north from South Shore and right at the Crossing.",v=1}}
