t[10857]={{tags="access",text="Major mana potions are sold here only after you reach Revered with the Argent Dawn.",v=1}}
t[10877]={{tags="patrol route",text="He walks counter-clockwise around the outer circle of town and sometimes into the inner part of Ironforge; run clockwise around the outside to find him.",v=17}}
t[10878]={{tags="patrol",text="Herald Moonstalker wanders around Darnassus rather than standing still, so she may need to be searched for.",v=1}}
t[10880]={{tags="patrol",text="Warcaller Gorlach patrols a loop around the city, so search the circuit; reports conflict on whether he walks clockwise or counter-clockwise.",v=7}}
t[10881]={{tags="patrol",text="He walks around the lake rather than standing still, so look for him on his patrol path.",v=1}}
t[10882]={{tags="",text="Tamed Arikara appears in a puff of smoke when summoned; this is a cosmetic effect only.",v=46},{tags="spawn route",text="Spawn point is on a rise near the Sacred Fire at Dark Cloud Pinnacle, around 31, 36; the Taurean totem pole is nearby.",v=5},{tags="route access",text="The ramp entrance to the rope bridges is at 31.3, 36.9, east of the path and west of the big needle with a camp on top.",v=2}}
t[10896]={{tags="route",text="Climb the cliff side at 31,36 and cross the bridges between the mountain tops to reach him.",v=61},{tags="route",text="He is reached from the top of the Darkcloud Pinnacle.",v=9},{tags="spawn",text="He respawns roughly every 7 minutes.",v=8}}
t[10916]={{tags="spawn route",text="At least one Winterfall Runner spawns in Felpaw Village in Felwood, so continue into Felwood rather than waiting on the Winterfall road.",v=50},{tags="patrol route",text="Runners walk the road between Timbermaw Hold and Winterfall Village, so search along that path.",v=36},{tags="spawn patrol",text="Runners despawn once they reach their destination, so search along their path before they arrive.",v=36}}
t[10917]={{tags="spawn access",text="Aurius only appears during the Baron fight after you start the Medallion of Faith quest. He arrives on a timer and dies in that fight, scripted.",v=27},{tags="interact",text="Talk to Aurius after Baron is dead to choose the quest reward, since he is not usable before that.",v=27}}
