t[10922]={{tags="access",text="Greta Mosshoof is only usable as the turn-in for Blood of Morphaz, which is picked up from Ogtinc in Azshara after earlier priest quests.",v=1}}
t[10927]={{tags="inside",text="Marlene is a ghost inside a run-down house in Sorrow Hill; the house is at the spot given.",v=18}}
t[10929]={{tags="inside route interact",text="Haleh is reached by running through the Mazthoril cave and stepping on the blue rune in the back chamber, which teleports you up to her.",v=29},{tags="hidden patrol danger",text="The blue rune in the cave is hidden in the snow and is patrolled by the flying elite dragon Scryer near the back of the room.",v=29},{tags="route hidden",text="Haleh sits on a snowy mountain; climb the path behind the big tree south of the cave mouth and jump the gaps (mount or sprint helps) to reach her.",v=23}}
