t[10977]={{tags="hidden",text="Quixxil stands just off the path near palm trees southwest of Spraggle Frock, at about 43,9 in Un'Goro Crater.",v=65},{tags="hidden",text="Quixxil is dressed in green and hides under bushes or foliage, so look closely or use /target quixxil to find him.",v=25},{tags="route",text="From Marshal's Refuge cave mouth, face Un'Goro with the Kodo on your left and walk just left of the palm tree to pass over him.",v=25}}
t[10978]={{tags="hidden route",text="Stands by the first tree on the left as you walk into Marshall's Refuge in UC; she is easy to run straight past.",v=5}}
t[10992]={{tags="interact",text="Walk a pet up next to the cage so the pet enters it; this unlocks the cage without the key.",v=5},{tags="spawn",text="It may play dead for hours before respawning; it respawned about 3 minutes after one player's report, just north of the camp white thingamajig.",v=4},{tags="access interact",text="The panther is in a cage that opens with the quest key.",v=3}}
