t[11023]={{tags="spawn",text="Weldon respawns about 30 minutes after being killed; if he is missing from Chillwind Camp, the Horde has likely just killed him.",v=5},{tags="danger",text="Weldon is an elite who hits very hard, about 1k per hit on cloth wearers, so he can kill weak characters quickly at the camp.",v=3}}
