t[12250]={{tags="floor inside",text="Zaeldarr is at the bottom of the crypt in The Undercroft, downstairs inside the crypt.",v=19},{tags="route",text="The crypt lies almost directly south of The Marris Stead.",v=19},{tags="danger",text="Three level 55 guards stand with him in the room at the bottom; pull them away from him first.",v=19}}
t[12261]={{tags="spawn",text="Walking on the graves in Zul'Mashar spawns Infected Mossflayers; avoid the graves to prevent them.",v=26}}
t[12277]={{tags="spawn",text="Her respawn is extremely slow, so if someone else kills her just before you arrive, expect a long wait.",v=12}}
t[12319]={{tags="access",text="Only appears after the horde druid class quest \"The Principal Source\" spawns it.",v=34}}
t[12336]={{tags="inside floor route",text="He is underground: enter the cathedral, go into the second of the two rooms on the right, and take the down stairway.",v=29}}
t[12337]={{tags="patrol route",text="Walks the road between Tyr's Hand and Stratholme and back, passing through Corin's Crossing in Eastern Plaguelands.",v=18},{tags="danger",text="Four elite bodyguards travel with her and will all come to the aid of any bodyguard attacked.",v=18},{tags="spawn",text="Despawns at Tyr's Hand and reappears at Stratholme, so search the zone for her again.",v=6}}
t[12339]={{tags="inside patrol danger",text="She pops inside Tyr's Hand and patrols toward Stratholme, escorted by 9-10 level 58-60 non-elite Scarlet Guards.",v=47},{tags="spawn access",text="She only appears after you accept the quest from Nathanos Blightcaller; if you leave and return, she will not be on the road.",v=5}}
t[12369]={{tags="access interact spawn",text="Put the gem in the statue at 28,6 and click the statue to make him spawn.",v=4},{tags="spawn danger",text="After placing the gem, move away right away; he spawns but stays still unless you are close.",v=1}}
t[12377]={{tags="floor inside",text="Found in the cellar out front of Kharazan, which is below ground level inside the area.",v=6}}
t[12378]={{tags="inside",text="Found in the Master's Cellar, under or outside Karazhan; the comment is unclear on which.",v=3}}
t[12379]={{tags="inside floor",text="The Unliving Caretaker is found in the cellar out front of Kharazan.",v=4},{tags="inside route",text="Enter the delapidated house in the center of the town and take the stairway down to The Master's Cellar.",v=3}}
t[12384]={{tags="access floor inside",text="Complete the quest Augustus gives before he will offer his wares; the quest's ledger is in the top back room of the nearby inn.",v=50},{tags="inside",text="Augustus is in the cottage in Terrordale proper that also holds Egan, not in the Terrorweb tunnel.",v=3}}
t[12423]={{tags="route",text="Walk east from the Goldshire inn and follow the south side of the lake; Roberts is visible just before a tree.",v=8}}
t[12427]={{tags="floor",text="He stands on top of the cliff between the path south of Kharanros and the grizzled den, not down inside the den.",v=19},{tags="spawn",text="He runs off and disappears when healed, then respawns quite quickly.",v=19}}
t[12428]={{tags="interact",text="Cast Fortitude and Renew on him; he needs these buffs for his quest.",v=6},{tags="danger",text="Rothide gnolls and graverobbers stand right near him on the north side of the cemetery.",v=6}}
t[12429]={{tags="route hidden",text="Head south from the moonwell and graveyard area, past the pub and cooking trainer, toward the lake; she stands just over a small drop-off crest.",v=3}}
t[12430]={{tags="hidden",text="Grunt Kor'ja is hidden behind some rocks, kneeling with an axe, on the right side of the road by the stone pillars south of Razor Hill.",v=26}}
t[12431]={{tags="spawn",text="Gorefang respawns within about 3 hours at most at 46,26 in Silverpine Forest.",v=13},{tags="spawn",text="He can be found lurking southeast of the spider mines at 49,18.",v=3},{tags="spawn",text="A less common spawn point is just north of the Dead Field.",v=3}}
t[12433]={{tags="inside",text="Found in the Skittering Dark Cave in Silverpine Forest, often at the back of the cave.",v=8},{tags="spawn",text="She can also be met outside the cave during the Skittering quest.",v=8},{tags="danger",text="Other spiders often surround her at the back of the cave, so she can be hard to reach.",v=3}}
t[12474]={{tags="patrol danger",text="Dragonkin mobs of this group walk in patrols of three and cannot be pulled individually.",v=37}}
t[12477]={{tags="patrol",text="Expect them to walk in packs of three rather than alone.",v=3}}
t[12579]={{tags="spawn",text="Her exact spawn point is 30,62 in the Charred Vale.",v=10},{tags="danger",text="She is a level 26 elite with blue wings that stand out among the harpies.",v=10},{tags="danger",text="Her harpy friends stay near her; pull and kill them separately before engaging her.",v=2}}
t[12580]={{tags="access spawn",text="Speak to Squire Rowe at the Stormwind entrance facing Goldshire; he rides off and brings Reginald Windsor back to you.",v=12}}
t[12676]={{tags="patrol",text="Sharptalon patrols back and forth between the road south of the bridge northwest of Splintertree and the area between Warsong Lumber Camp and the small Forsaken camp.",v=52},{tags="spawn",text="After being killed, Sharptalon takes roughly 15 to 20 minutes to respawn.",v=52},{tags="spawn",text="Sharptalon spawns at about 78, 66.",v=36}}
t[12677]={{tags="spawn",text="Shadumbra spawns near the treehouse and stump at about 62,50, on the north side of Raynewood Retreat.",v=46},{tags="patrol route",text="Shadumbra roams the trail west of Raynewood Retreat, down to the foot of the open meadow near 52,54.",v=46}}
t[12678]={{tags="patrol spawn",text="He is found around 41,65 and wanders between the area north of Talondeep Path and the area north of Silverwing Refugee. Waiting about a minute on the hill at 40.9,65.5 has brought him in.",v=35},{tags="access",text="The paw only drops after The Ashenvale Hunt (quest 6383) is completed, which requires turning it in to Senani Thunderheart in Splintertree Post.",v=29},{tags="spawn",text="He spawns near 44,69 and can take 5 or more minutes to respawn after being killed.",v=24}}
t[12717]={{tags="spawn",text="If Muglash is missing, someone is escorting him; wait about 10 minutes for him to respawn.",v=31}}
t[12724]={{tags="floor",text="She stands on top of the crates next to the flight point.",v=7}}
t[12740]={{tags="access",text="Faustron only links to other flight points after you discover Bloodvenom Post in Felwood; talk to Brakkar there to get that flight path.",v=3}}
t[12759]={{tags="spawn",text="Tideress respawns about 10 minutes after she dies.",v=19},{tags="spawn patrol",text="Tideress spawns on an island in a lake to the south and patrols around that island.",v=9}}
t[12801]={{tags="spawn",text="Respawns about 50 to 60 minutes after being killed.",v=1}}
t[12802]={{tags="route",text="Reach it through the pass into the Enterior on the east side of the isle, near a small island; the spot is close to 34,80.",v=5}}
t[12803]={{tags="danger",text="He is a level 62 elite whose 30-yard AoE hits everyone nearby, so stay outside that radius.",v=22},{tags="spawn",text="He respawns 15 to 30 minutes after being killed; reported respawn times vary.",v=13}}
t[12856]={{tags="hidden",text="They are stealthed and invisible, found just outside town near the trees; walk around close to them to draw them out.",v=11}}
t[12858]={{tags="spawn",text="He may be absent while another player is on the quest; he stands across the road from the spot, with other NPCs sitting on the ground.",v=13},{tags="spawn",text="Torek respawns about 5-7 minutes after someone completes or fails the quest, so wait for him to return.",v=10}}
t[12862]={{tags="patrol inside",text="Walks up and down the ramp inside the lone tower south of Splintertree Post.",v=3},{tags="spawn",text="Can be found at the Ashenvale spot 71,68.",v=1}}
t[12863]={{tags="route",text="He stands beside the flight master at Zoram'gar Outpost in the southern part of the village, at coordinates 12,34.",v=15}}
t[12864]={{tags="spawn",text="Her spawn point is at 94,47, in case Alliance players have already killed her.",v=29},{tags="patrol route",text="The Warsong Outrider patrols the road between the river before Satyrnaar and the border, moving slowly.",v=7}}
t[12865]={{tags="route",text="Enter Razorfen Downs from the main entrance; he is in the first tent right as you walk into the thistled area.",v=50},{tags="route danger",text="Take the right fork at the first split; he stands between two tents with about eight other mobs.",v=50},{tags="route",text="Past the second spot, follow the path to the next fork and go left; he is at the dead end against the wall.",v=50}}
t[12866]={{tags="route",text="Myriam stands on a hill just outside the skull-mouth entrance to the instance, at about 49,94; she is not inside.",v=41}}
t[12899]={{tags="access",text="Axtroz only appears after you have killed Somnus, Chronalis, and Scryer, as part of the Test of Skulls quest.",v=35},{tags="danger",text="The dragonkin around Grim Batol are elites, so expect elite mobs in that area.",v=9},{tags="spawn",text="Axtroz was seen at 83,48 in the Wetlands.",v=4}}
t[12900]={{tags="spawn",text="Somnus respawns about 5 minutes after death, around coordinates 80,70.",v=6}}
t[12919]={{tags="route",text="He stands on a small island southwest of Theramore at about 58.6, 60.0 in Dustwallow Marsh; swim there from Theramore.",v=68},{tags="access",text="He only gives his quest at exactly 225 base fishing skill (gear bonuses do not count) and level 40 or higher.",v=32},{tags="danger",text="Level 40-45 mobs roam the area around his island.",v=8}}
t[12920]={{tags="access",text="He only offers the Triage quest once you have 225 First Aid skill, which a quest in Orgrimmar can give you.",v=109},{tags="inside",text="Doctor Gregory Victor is inside the building to the left just past the entrance of Hammerfall in Arathi Highlands, at 73,36.",v=14},{tags="access",text="If another player is on his quest, he may offer no quest; wait for them to finish and the offer will appear.",v=9}}
t[12939]={{tags="access",text="To get the Triage quest for Artisan First Aid, you need 225 First Aid and at least level 35.",v=51},{tags="inside",text="He is inside the Foothold Citadel in Dustwallow Marsh, not at the other locations where he is sometimes shown.",v=7},{tags="access",text="Training options only appear once your First Aid skill is high enough, so you need at least that skill to see them.",v=1}}
t[12944]={{tags="access route",text="Reaching him requires the Shadowforge Key from the Dark Iron Legacy quest, obtained in ghost form, to pass the Shadowforge Gates.",v=7},{tags="patrol route",text="A fire elemental patrol walks the path to the bar; wait for it to pass before going up the slope to the Shadowforge lock.",v=7},{tags="danger",text="Two groups of mobs, including fire elementals, sit between the Shadowforge lock and the bar and aggro easily.",v=7}}
t[12997]={{tags="inside",text="Monty stands inside the Ironforge side of the Deeprun Tram, on the middle platform near a wall.",v=55}}
t[13018]={{tags="inside",text="Nipsy stands inside the Stormwind Tram station, on the Stormwind side of the tram.",v=39},{tags="spawn",text="Nipsy respawns within about 3 seconds after he is killed.",v=1}}
t[13019]={{tags="inside floor route",text="Enter the Thunderaxe Fortress gate and go left into the first tower; he is inside at the top floor, near 54,30.",v=21},{tags="spawn",text="He respawns about every 6.5 minutes after being killed.",v=13}}
t[13020]={{tags="inside",text="He is found inside Blackwing Lair, the second boss there after Razorgore.",v=18},{tags="interact",text="He is asleep before the fight; talk to him to start it, which triggers a brief cutscene.",v=18}}
t[13084]={{tags="inside",text="She is inside the Timberline Arms building in Ironforge.",v=3}}
t[13136]={{tags="spawn",text="Hive'Ashi Drones appear after you kill an Undead Ghost such as a Tormented Druid or Tortured Sentinel, but not every time.",v=18}}
t[13153]={{tags="inside route",text="Go up through the base, turning left where the path splits mid-building, then up between the two towers and keep bearing left; he is in the back by the red Horde flag.",v=30}}
t[13154]={{tags="floor inside",text="Commander Louis Philips is on the top floor of the tower at Tower Point in Alterac Valley, at about 50,65.",v=32},{tags="patrol",text="He stays stationary on top of the tower and does not wander, despite what the quest text says.",v=18}}
t[13179]={{tags="floor inside",text="Wing Commander Guse is inside Icewing Bunker on the top floor.",v=14}}
t[13180]={{tags="inside route",text="Jeztor is held prisoner inside the little structure at the Alliance lumber mill, just north of Stormpike Graveyard, northeast of Icewing Bunker, around 54,27.",v=120},{tags="spawn",text="He is held prisoner at the start of each battleground match, so he may not be present at other times.",v=1}}
t[13181]={{tags="spawn inside",text="At the start of each match he is held prisoner in the Dun Baldar North Bunker.",v=21},{tags="access spawn",text="He appears in your base only after the Horde takes Dun Baldar North Bunker, unless Alliance kills him while he runs from the bunker.",v=6}}
t[13220]={{tags="route",text="He stands at 81,18, at the first wide spot in the road after leaving Un'Goro.",v=17}}
t[13236]={{tags="inside route",text="Look in a little cave on the left after entering the Frostwolf Keep compound; he is inside.",v=18},{tags="spawn",text="He is not always present at the cave spot.",v=18},{tags="spawn",text="Respawn time is roughly an hour.",v=1}}
t[13278]={{tags="hidden route",text="He stands in the water on a small southeastern island in Azshara's Bay of Storms, near 79,73; swim around to find him, as it can take a while.",v=47},{tags="route",text="Reaching the island may mean jumping off a cliff into the water, so aim carefully; fly to Azshara and go down the cliffs from there.",v=47},{tags="access interact",text="Aqual Quintessence requires honored standing with Hydraxian Waterlords first; talk to him to receive it.",v=6}}
t[13319]={{tags="danger",text="Commander Duffy, a level 61 elite, stands right next to the flag at Stormpike Graveyard.",v=9}}
t[13320]={{tags="inside access",text="Found at Icewing Bunker in the middle of Alterac Valley; he is only there while you are in that battleground.",v=23},{tags="patrol",text="He roams rather than staying put; one player found him southeast of the SH bunker.",v=5}}
t[13433]={{tags="spawn",text="He only appears during the Feast of Winter Veil, roughly December 15 to January 2.",v=28}}
t[13435]={{tags="spawn access",text="He only appears during the Feast of Winter Veil event, so he is not present at other times.",v=16}}
t[13437]={{tags="inside",text="Wing Commander Ichman is inside the Horde base in one of the Frostwolf Towers; comments disagree on which tower, so check both.",v=6}}
t[13438]={{tags="floor inside",text="Wing Commander Slidore lies on the floor inside Tower Point Tower; go in to find him.",v=62},{tags="interact patrol",text="After you talk to Slidore he runs back to the Alliance base; keep him alive until he arrives.",v=62},{tags="access",text="Take the Tower Point tower first to rescue Slidore; he is not available before that.",v=8}}
t[13439]={{tags="inside",text="Between Frostwolf Graveyard and Frostwolf Towers, he is in one of the small huts.",v=123},{tags="inside",text="In the Horde base, he is in the second tent on the right just past the entrance (around 51,80 or 51,81).",v=44},{tags="spawn",text="After the Horde base returns to base, he moves to a spot behind the supply tent by the griffons.",v=44}}
t[13442]={{tags="route",text="Find her in the grove behind the north bunker of Dun Baldar, reached by the path between the bunker and the fort, near 44,12.",v=15},{tags="spawn",text="She appears only after the Horde invades the Dun Baldar base; she is absent before that.",v=5}}
t[13444]={{tags="danger",text="Guards standing near the tree are level 65 and kill low-level players within seconds; avoid them.",v=1}}
t[13445]={{tags="spawn",text="He appears only during the winter holiday, roughly December 15 to December 29, so visit during that window.",v=18},{tags="inside",text="He stands near the bank in Ironforge or Orgrimmar; in Orgrimmar he is inside, under the big Christmas tree.",v=18}}
t[13602]={{tags="spawn",text="He spawns at random points along the inner west edge of the Alterac Mountains, from Growless Cave up the ledge toward the snowy wall, at spots such as 31,65, 28,53, 31,64, 34,68 and 39,63.",v=7},{tags="spawn",text="The yetis in the area are placeholders, so he can spawn wherever they stand; kill nearby yetis to watch for him.",v=7},{tags="spawn",text="He alternates between northern and southern spawn areas, so if he is taken in the south, look in the north next.",v=4}}
t[13656]={{tags="route",text="Reach the hut from the NE Desolace roads: go southwest of the slanted-H crossroads toward the cliffs, or head directly south off the Stonetalon road.",v=14},{tags="inside",text="Willow is inside Kormek's Hut in Desolace, at about 62,39.",v=5}}
t[13697]={{tags="inside route",text="She is inside the cave area leading into Maraudon, in the orange section outside the instance. Follow the orange crystals down that path; she stands on the left side of the hall.",v=64}}
t[13698]={{tags="access",text="He will only talk to you after you have killed the princess, and only if your reputation is at least neutral.",v=3},{tags="floor route",text="He is located just above the gryphon landing pad.",v=3}}
t[13699]={{tags="hidden",text="She sits under a tree with sisters on the small hill south of Shadowprey and has no minimap dot, so look for her there.",v=26},{tags="access",text="Only Horde can get her quest; Alliance players get the same quest from Nijel's Point instead.",v=16},{tags="access",text="Turning in requires not being at war with Cenarion Circle; uncheck the at-war flag in the reputation window first.",v=15}}
t[13716]={{tags="spawn access inside",text="He is a spirit that spawns after you kill Celebras the Cursed, an elite at the end of the orange side of Maraudon.",v=14},{tags="route inside",text="Drop down from the orange side of Maraudon to reach him.",v=2},{tags="route inside",text="On the purple side inside Maraudon, pass boss Sathyr, go down the waterfall, then go left to find him.",v=2}}
t[13717]={{tags="patrol route",text="Expect him to patrol the hills between about 43,85 and 50,86; he walks via 48,87 and pauses at each end.",v=93},{tags="spawn",text="He may despawn for a while and reappear near 43,85, so search there if he is missing.",v=2}}
t[13718]={{tags="route inside",text="He is found under the first bridge once you open the door to Maraudon.",v=17},{tags="spawn route",text="He spawns at four points by the Maraudon entrance from Desolace and respawns immediately after death.",v=3}}
t[13776]={{tags="inside",text="Find him inside the cave at 65,55.",v=15}}
t[13816]={{tags="inside",text="Find her inside the North Building.",v=7}}
t[13840]={{tags="route",text="He is not inside the Alterac Valley battleground but in Alterac Mountains; stand in front of the AV portal cave facing it and he is to the left.",v=3}}
t[13841]={{tags="inside route",text="He stands outside in front of the cave entrance to Alterac Valley, not inside the battleground instance.",v=7},{tags="route",text="Reach him by traveling to Western Plaguelands, then running south into Alterac Mountains.",v=7}}
t[13843]={{tags="access",text="Level 51 or higher is needed before he sends you to Alterac Valley for a quest.",v=1}}
t[13896]={{tags="inside patrol",text="He spawns in his cave and then wanders out into the sea for a while before returning.",v=1},{tags="spawn",text="After he is killed, he takes longer than an hour to respawn.",v=1}}
t[14123]={{tags="spawn",text="Steeljaw Snappers spawn along the beach, including the ones in the water; check both the north and south parts of the beach.",v=4}}
t[14221]={{tags="spawn route",text="Look for him spawning often in Strahnbad, usually near the central well or beside the shed behind town at 58,41, or near 62,43.",v=35},{tags="patrol",text="He roams around the farm near Strahnbad, so search the farm area.",v=1}}
t[14224]={{tags="spawn",text="Yellow non-hostile racecar-like mob; it appears as a neutral mob, not hostile, at Camp Cagg in the Badlands.",v=1},{tags="patrol spawn",text="Rare spawn near the Badlands, sometimes wandering near the Greater Rock Elementals in the southwest.",v=1}}
t[14225]={{tags="spawn",text="Prince Kellen is a rare spawn, not elite; he respawns roughly every 8-12 hours and is usually found around 4:30-5:00 AM.",v=11},{tags="hidden",text="He is a retextured rogue, dark blue over light blue, so he can be mistaken for an ordinary mob and missed.",v=5}}
t[14229]={{tags="spawn",text="He is a rare mob that spawns infrequently, so expect a long search while swimming around the yellow marks.",v=18},{tags="spawn",text="Look for him in the water around 42,11 and 42,10, where players killed him.",v=6},{tags="spawn",text="Look for him in the water around 35,5 and 35,4, where players found him.",v=5}}
t[14233]={{tags="spawn",text="Ripscale spawns right by Deadmire, next to Tabetha's place near Quagmire.",v=9}}
t[14266]={{tags="inside spawn",text="Shanda sits inside her cave in Loch Modan and is still there when you check it.",v=16},{tags="spawn patrol",text="Shanda is a semi-rare spawn with a slow respawn of about 4-6 hours and roams a small area around her spawn point.",v=8},{tags="route",text="There is no real path to her cave; you must navigate over the hills to reach it.",v=1}}
t[14269]={{tags="floor",text="He walks along the lake bottom, so he is found underwater on the floor of the lake; stay in the water with him.",v=9},{tags="route",text="Look for him in the lake below the waterfall and under the bridge to Stonewatch Keep, where he sits in the water.",v=1},{tags="route",text="He can be found between the lake and the blocked passage, near the lakeside pile of rocks.",v=1}}
t[14270]={{tags="spawn",text="Respawns every 2-3 hours, much sooner than most rares.",v=26},{tags="patrol",text="Swims underwater and wanders; he was seen near 52,55 in Lake Everstill.",v=13},{tags="patrol spawn",text="Swims along the lake bottom in the northeast, eastern half of Lake Everstill; he stands out as a purple murloc.",v=7}}
t[14271]={{tags="patrol hidden",text="Ribchaser patrols around the camps; wait on a high rise and single him out when he passes.",v=12},{tags="patrol",text="Found right off the road at Three Corners; /target him to check whether he is up.",v=12},{tags="spawn",text="He spawns in the Redridge Mountains near 30,78, at the fork in the road on the way up to Lakeshire.",v=1}}
t[14272]={{tags="route",text="Found north of Lakeshire, just off the path to the left before the Blackrock Champions area, right before the mountains.",v=8}}
t[14276]={{tags="patrol",text="He wanders along the shore of Southshore with his murloc companions.",v=18}}
t[14277]={{tags="patrol",text="She walks a long path along the coast, from the bottom of the map up to the top.",v=1},{tags="patrol",text="She has been met on the Eastern Strand outside Southshore.",v=1}}
t[14279]={{tags="",text="Found in the fields between Southshore and its mine, just west of Southshore, at about 35,59.",v=7},{tags="patrol",text="Sightings are spread across several spots in the area, so he appears to wander between them.",v=1}}
t[14325]={{tags="interact access",text="Wearing the Gordok Ogre Suit lets you talk to him; after the conversation he runs off, letting you pass.",v=31},{tags="danger",text="Two Gordok Reavers, level 61 elites, join him partway through the fight.",v=23},{tags="spawn",text="After the Ogre King is dead, Kromcrush and his guards can no longer be killed.",v=5}}
t[14338]={{tags="interact floor",text="Do not kill Knot Thimblejack; instead open the box one floor above him.",v=8},{tags="spawn",text="The box spawns after you kill some ogres.",v=8},{tags="interact",text="Do not free Knot if doing the Gordok Tribute run, because he will run off.",v=1}}
t[14339]={{tags="patrol",text="Death Howl roams the southern area of Felwood.",v=19},{tags="hidden",text="He looks light green in Felwood because of the mist, but he is actually white.",v=16},{tags="patrol",text="Look a little south of the broken shrine near the Felwood entrance to find him.",v=13}}
t[14340]={{tags="spawn",text="Found in Jadefire Glen, near the southwestern Jadefire spawns in Felwood.",v=5},{tags="spawn",text="Seen at 41,81 in southern Felwood.",v=4},{tags="spawn",text="He is a rare spawn that appears suddenly with no warning; a silver dragon around his portrait marks him as rare.",v=4}}
t[14344]={{tags="spawn",text="He spawns northwest or west of Emerald Sanctuary in Felwood, near the lake and the bridge north of it.",v=11},{tags="inside spawn hidden",text="He spawns inside a large tree west of Emerald Sanctuary and can hide behind it.",v=4},{tags="interact patrol",text="He can be targeted from outside while inside the large tree, and he walks out around the tree.",v=1}}
t[14345]={{tags="route hidden",text="Reach Bloodvenom Falls, go along the lake's eastern side to a waterfall, follow it back to a second waterfall, and find him in the small pool behind it.",v=9},{tags="danger",text="He is a rare elite spawn, so expect to face an elite fight when you find him.",v=4}}
t[14347]={{tags="access",text="Bring one half of the Bindings of the Windseeker to him to start his quest chain.",v=3},{tags="access",text="He is meant to be found by players doing the Rumblers and Stormers quest for the Hydraxian Waterlords.",v=3}}
t[14358]={{tags="inside",text="He is found inside Dire Maul, in its western wing.",v=25}}
t[14368]={{tags="inside",text="Lydros is inside the DM North library, at a shelf about 2 o'clock from the door, next to a cadaver.",v=45},{tags="route",text="Reach him via the DM North ramp: jump the left ledge to the grass, pass the ogre campfire at max range, take the mini ramp to the door, then follow the tunnel in.",v=45},{tags="danger",text="Ogres at the campfire on the route aggro if you pass too close; stay at max range.",v=45}}
t[14381]={{tags="inside route",text="Javon is in the library in Dire Maul North. Go down into the courtyard, face west, and go through the door into the long hallway that leads to the library.",v=47},{tags="access",text="You need the Crescent Key to get into the library.",v=7}}
t[14382]={{tags="inside route",text="He is inside the Library of DM North: walk in, go down the ramp on the left, pass the fire with the seated guards, then take the door down a ramp and follow the corridor to its end.",v=36},{tags="access",text="The door leading to him needs a Crescent Key, or a rogue's lockpicking.",v=36}}
t[14383]={{tags="inside route",text="He is inside the library in Deeprun Mine north, off the first lowered courtyard you reach, near Guard Mol'dar.",v=24}}
t[14387]={{tags="inside route",text="Find him at the bottom of the Blackrock Mountain spiral, past the door toward BRD, standing by the window and crystal that lead to Molten Core.",v=21},{tags="access",text="He is only reachable after the Molten Core attunement run through Blackrock Depths; talk to him afterward to zone into Molten Core.",v=15},{tags="route",text="Going along the stone chain outside BRD, turn right at the 5 steps near 48,66; he stands in front of you there.",v=10}}
t[14394]={{tags="spawn",text="After he is killed he respawns about 7 minutes later.",v=4}}
t[14425]={{tags="patrol route",text="Gnawbone wanders along the channel that follows the main road, so search there to find him.",v=7}}
t[14430]={{tags="spawn",text="Duskstalker spawn points reported near 52,77, 60,76 and 60.86,75.15; he has been found at each of these spots.",v=8}}
t[14431]={{tags="patrol",text="Fury Shelda somewhat roams around the area rather than staying in one spot.",v=9},{tags="danger",text="Other harpies in the area are nearby and get pulled in when attacking her.",v=9}}
t[14433]={{tags="route hidden",text="Sludginn is an elite rare on the hills above the murloc camp south of Menethil Harbor, past the wrecked ship, following the water around to the next land and up the mountain on the left.",v=8},{tags="hidden route",text="Climb higher up the hills behind the little murloc town to find him; he sits well above the camp.",v=3},{tags="route",text="He is elevated in the hills and only needs a bit more climbing from the murloc camp to reach him.",v=1}}
t[14435]={{tags="access spawn",text="Prince Thunderaan cannot be found in the world; he appears only when Highlord Demitrian in Silithus summons him after the quest chain's items are turned in.",v=13}}
t[14436]={{tags="route",text="From the Blackrock Mountain south entrance, follow the path west to the Altar of Storms; he is in the caged camp next to it.",v=3}}
t[14454]={{tags="spawn",text="Spawns in northwest Silithus during elemental invasions, which occur about every few days; an emote announces him across the zone.",v=18},{tags="patrol",text="He patrols with four Whirling Invader adds while the other invaders hang around.",v=18},{tags="spawn",text="Killing him ends the invasion and despawns the Whirling Invaders around him.",v=16}}
t[14455]={{tags="spawn",text="Whirling Invaders only appear during the Windreaver invasion and vanish when the Windreaver is killed.",v=10},{tags="access spawn",text="The invasion only starts after the Silithus gates open; once they close, no more Whirling Invaders spawn.",v=5}}
t[14457]={{tags="spawn access",text="She appears only during the Elementals Invade zone event in Winterspring, at Kel'Theril on the ice lake; a broadcast announces her spawn.",v=17},{tags="spawn",text="She respawns about every two days after she dies.",v=17},{tags="danger",text="She keeps four to six non-elite guards with her, and they all aggro together when one is attacked.",v=14}}
t[14460]={{tags="spawn access",text="Blazing Invaders appear only during the periodic Elemental Invasion event in Un'Goro and stay until their leader, Burning Charr, is killed.",v=37},{tags="spawn",text="The invaders spawn along with the named mob Baron Char, who yells in chat when he appears.",v=15},{tags="spawn danger",text="Invaders spawn from a glowing orb at the south end of Fire Plume Ridge, where an elite boss stands with three or four of them.",v=3}}
t[14461]={{tags="patrol route",text="He patrols counterclockwise around the base of Fire Plume Ridge in Un'Goro Crater.",v=42},{tags="danger patrol",text="He is accompanied by several elemental bodyguards that stay with him while he patrols.",v=42},{tags="spawn",text="Extra fire elementals keep spawning until he is killed, and killing him ends the elemental invasion.",v=42}}
t[14463]={{tags="danger",text="He is in the Tainted Scar of Blasted Lands, where level 60-61 elites roam around him.",v=34},{tags="route",text="Follow the road south in the Tainted Scar, then bear right when you reach the elites to find him.",v=34},{tags="route danger",text="Approach along the right side of the mountain; mobs will aggro, so keep riding past him to shake them off.",v=18}}
t[14464]={{tags="spawn",text="He spawns only during the Elemental Invasion event in Azshara; watch for portals around the invaders.",v=31},{tags="danger",text="Three or four elite elementals guard him and stay with him.",v=11},{tags="spawn",text="He is found in the northeast part of Azshara.",v=2}}
t[14467]={{tags="",text="Kroshius is at about 46, 35.",v=29},{tags="spawn access",text="Kroshius only appears when summoned, and if he is not killed in time he vanishes and must be summoned again.",v=1}}
t[14472]={{tags="spawn",text="Spawns around 54,34 in Silithus; several players have spotted him at that spot.",v=9},{tags="danger",text="He is a level 57 elite, so approach that spot carefully.",v=9},{tags="spawn",text="Has also been seen between the dragon bones and the Hive Regal.",v=6}}
t[14475]={{tags="inside route",text="Rex Ashil is in Hive'Ashi, in the eastern-most hole of the hive.",v=1},{tags="hidden inside",text="Rex Ashil looks like a regular hive bug and is found in hive tunnels; distract him to reveal him as a named bug in the combat log.",v=1},{tags="danger",text="Rex Ashil is an elite bug in the hive.",v=1}}
t[14478]={{tags="patrol",text="He patrols around a large hill, following the path shown on the map.",v=5},{tags="spawn",text="He is a rare spawn, and one player farmed for hours without him respawning.",v=4},{tags="patrol",text="He wanders among the rock elementals in Silithus.",v=1}}
t[14479]={{tags="spawn patrol",text="Found by a targeting macro or at the Twilight's Hammer camps; he spawns at one of three camps, not roaming between them.",v=6},{tags="patrol",text="He wanders in a large predetermined circle around the Twilight's Hammer camp he spawns at.",v=5},{tags="spawn",text="He spawns again at another camp 5-10 minutes after dying at one; killing him at one camp usually means he moves to another.",v=4}}
t[14481]={{tags="spawn",text="He only appears in Stormwind during Children's Week and is not there at other times.",v=24}}
t[14487]={{tags="",text="Look for him at coordinates 34,23; he has been found there.",v=5},{tags="spawn",text="He is a rare spawn and is not always present, so he may not be there when you arrive.",v=3}}
t[14488]={{tags="patrol",text="Roloch patrols between the Mizjah Ruins and the road heading north.",v=3}}
t[14492]={{tags="patrol",text="The goblin wanders around the area rather than standing still.",v=3},{tags="danger",text="The area is swarming with stealthed level 43 Elder Shadowmaw Panthers, so expect danger nearby.",v=3}}
t[14494]={{tags="spawn",text="Eris respawns about 10-15 minutes after you fail the quest.",v=8},{tags="access",text="Eris can only be seen with the Eye of Divinity equipped, not the Eye of Shadow.",v=2},{tags="inside route",text="Go west of the Stratholme entrance through a cave; Eris stands on a rock nearby.",v=2}}
t[14508]={{tags="spawn",text="Short John Mithril spawns in a chest every 3 hours counting from midnight, at 3am, 6am, 9am, noon, 3pm, 6pm, and 9pm.",v=58}}
t[14522]={{tags="inside route",text="Ur'dan stands at the very end of Shadow Hold in Jaedenar, next to Lord Banehollow.",v=14},{tags="danger",text="Lord Banehollow stands right beside Ur'dan, and area-of-effect attacks will aggro Banehollow.",v=14},{tags="spawn",text="Ur'dan respawns about every 15 minutes.",v=3}}
t[14523]={{tags="inside route",text="Find Ulathek in a small room past a little bridge, down the ramp heading north-east after the sacrifice room with the Remains of Trey Lightforge.",v=6},{tags="danger",text="The NPCs in his room attack you once you have spoken to Ulathek, especially if you used the Shadowy potion.",v=4}}
t[14524]={{tags="route spawn",text="Stand on the little hill on the island in the middle of the green sludge in Irontree Woods, Felwood; Vartrus appears there.",v=32},{tags="route",text="Irontree Woods in Felwood; Vartrus is on the island's hill at about 48,24.",v=3}}
t[14525]={{tags="access",text="You can only talk to Stoma after obtaining the leaf from the chest behind Majordomo in Molten Core and the leaf from Onyxia.",v=9}}
t[14526]={{tags="access",text="Hastat is not visible until you carry the Ancient Petrified Leaf, which drops from the chest after Majordomo in Molten Core.",v=14},{tags="access",text="Hastat only becomes visible after Majordomo Executus is killed in Molten Core, so you must have finished Molten Core first.",v=1},{tags="route hidden",text="The Petrified Ancients are in the water on the island in the middle of the green lake; climb to the highest point of the little pile to spawn them.",v=1}}
t[14527]={{tags="access interact",text="She only becomes visible to hunters who are on the demon quest, and she must be fought without a pet.",v=77},{tags="patrol route",text="Simone patrols a C-shaped path: she starts south of the tent above the elite kodos, heads south and west, then loops north and back to spawn.",v=18},{tags="hidden access",text="She only shows up on Track Demons, which makes her visible on the minimap.",v=18}}
t[14529]={{tags="access",text="He only appears once a hunter is on the epic bow quest, since he is the demon for that quest.",v=86},{tags="patrol route",text="He wanders the Burning Steppes road near 27,52, walking past the elite dragonkin.",v=28},{tags="spawn",text="He despawns 15 minutes after you talk to him or if another player tags him, and respawns 15 minutes later.",v=3}}
t[14531]={{tags="patrol",text="Artorius patrols the rim of the area north-east of Winterspring on a circuit taking about 18 minutes.",v=20},{tags="danger",text="He is a level 60 elite in demon form and hits hard, so do not aggro him accidentally.",v=20},{tags="spawn",text="If another player interferes with him or attacks him, he despawns and must respawn before the quest can be done.",v=17}}
t[14536]={{tags="access",text="Only a hunter on the epic quest can make him transform into Solenar the Slayer; the quest starts with the Ancient Petrified Leaf from Majordomo's chest in Molten Core.",v=48},{tags="spawn",text="Other players who touch or get close to Solenar make him despawn; he respawns about 7 hours later.",v=34},{tags="patrol",text="He patrols anywhere in the southwest corner of Silithus, left of the AQ gates.",v=10}}
t[14564]={{tags="access interact",text="Use the Exorcism Censer on the green smoky circles to summon this spirit; it does not appear otherwise.",v=10}}
t[14566]={{tags="access",text="Bring the Manna-Enriched Horse Feed to the quest, or the Ancient Equine Spirit cannot be used.",v=1},{tags="patrol",text="The spirit moves from its starting spot after some time and stands next to the first mana pylon.",v=1}}
t[14567]={{tags="access",text="He only gives quests or talks once you are level 50 with 265 Blacksmithing; he stands in front of the forge in Gadgetzan, Tanaris.",v=43},{tags="access",text="Finish the earlier Blacksmithing quest chain from Galvan the Ancient in Tanaris first; the chain begins with Hank the Hammer.",v=1}}
t[14621]={{tags="inside route danger",text="Enter the cave at 49,45; Overseer Maltorius is an elite with two elite guards nearby.",v=13},{tags="spawn",text="His respawn time is long after he dies.",v=2}}
t[14624]={{tags="access",text="Complete the quest 'What the flux?' before turning in the required items to gain faction with him.",v=35},{tags="hidden",text="He stands under a tent cloth and is hard to see; he is the NPC closest to the Alliance flight point.",v=3},{tags="route",text="Follow the cobblestone path lined with torches in the hills above Thorium Point to reach him.",v=3}}
t[14637]={{tags="access",text="Zorbin only opens his shop to you after you complete the quests Zapped Giants and Fuel for the Zapping.",v=58}}
t[14661]={{tags="patrol",text="Stinglasher has been found outside the cave near the tree at the cave mouth, around 75,60 to 76,63.",v=32},{tags="patrol spawn",text="Stinglasher spawns and patrols between the two hives around the Writhing Deep; he does not stay at the cave mouth.",v=13},{tags="patrol spawn",text="He can appear on the right-hand entrance of the two hive entrances, and may spawn on top of you while you fight nearby silithid.",v=1}}
t[14722]={{tags="floor inside",text="Find Clavicus Knavingham on the second floor of Duncan's Textiles in the Mage Quarter, at about 44,74.",v=22},{tags="route",text="From the Trade District, cross the bridge into the Mage Quarter, go through the archway, turn left; Duncan's Textiles is on the right.",v=22}}
t[14723]={{tags="spawn",text="Reports from 2020 say she may have despawned and could not be found at her usual spot.",v=3}}
t[14724]={{tags="interact",text="Bubulo Acerbus cannot trade; cloth is handed in only through the quests he offers, so accept one of those quests first.",v=9}}
t[14726]={{tags="inside route",text="Find her inside the Tailor shop in The Drag, just south of the Valley of Honor gate.",v=12},{tags="access",text="The runecloth donation option only appears after you donate 60 mageweave, which itself requires the wool and silk donations first.",v=2}}
t[14727]={{tags="route",text="Find her in the Valley of Spirits at 38,88, right behind the mage trainers; ask a guard where they are.",v=41}}
t[14731]={{tags="route",text="Lard is the innkeeper of the Revantusk Village Inn, not the Aerie Peak Inn, so he is found in that village.",v=5}}
t[14736]={{tags="floor inside",text="She is on the second level of the Inn, in the hut next to the mailbox.",v=1}}
t[14741]={{tags="spawn",text="Huntsman Markhor is found at 64,49 and at 53,50 for the quest 'Avenging the Fallen'.",v=1}}
t[14748]={{tags="spawn access danger",text="Opening Lard's Picnic Basket at 84.5, 41.2 on the island off the coast triggers an ambush by three Vilebranch Kidnappers.",v=14}}
t[14753]={{tags="access",text="Buying from her requires Friendly reputation with the Sentinels; higher-tier items require Honored, Revered or Exalted standing.",v=41},{tags="access",text="Horde players cannot buy from her; the Horde has a comparable seller with the same requirements.",v=6}}
t[14754]={{tags="route",text="Kelm Hargunth is at Mor'shan Base Camp, north of the crossroads, at coordinates 46,8.",v=4}}
t[14829]={{tags="spawn access",text="He only appears while the Darkmoon Faire is in town, roughly every two months for a week; the Faire has been in Goldshire and in Thunderbluff.",v=2}}
t[14832]={{tags="access",text="Check your Darkmoon Faire reputation first: her cheaper quests disappear as it rises, even while Neutral. Coarse Weightstone stops at 500/3000 and Heavy Grinding Stone at 1100/3000.",v=16}}
t[14842]={{tags="spawn access",text="He only appears in Ironforge while the Darkmoon Faire is running, so expect him during the fair.",v=5},{tags="inside patrol",text="Look for him in Ironforge's Commons, just inside the main entrance, wandering between the bank and the Auction House.",v=4}}
t[14846]={{tags="spawn",text="Ghost mushrooms and dream foil respawn in her stock about every 20 minutes.",v=6},{tags="spawn",text="Her stock resets and restocks with new items after the quantities she has sold run out.",v=6},{tags="spawn access",text="Lhara only appears during Darkmoon Faire week, outside in Thunder Bluff (Mulgore) or Elwynn Forest, alternating months.",v=4}}
t[14847]={{tags="spawn access",text="He only appears in a tent when the Darkmoon Faire is set up in Goldshire or Mulgore, so he is not present otherwise.",v=5},{tags="patrol",text="He does not wander; he stays in his tent during the Faire.",v=5}}
t[14860]={{tags="patrol hidden",text="Flik is a level 4 orc child who runs around Goldshire and is not in a tent; he stops only occasionally, so he must be caught by right-clicking.",v=30},{tags="spawn access",text="Flik only appears while the Darkmoon Faire is in town, and he comes and goes with it.",v=30}}
t[14862]={{tags="access spawn",text="He only appears as part of a quest-triggered event; the quest starts from a note found in one of the hives.",v=19}}
t[14871]={{tags="interact access spawn",text="Place a Dark Iron Ale Mug next to Morja and wait for Jubjub to spawn before her quest can be taken.",v=3}}
t[14887]={{tags="spawn",text="Expect Ysondre to spawn at a random time and random location among Ashenvale, Duskwood, Feralas, and the Hinterlands.",v=40},{tags="spawn",text="In Duskwood, Ysondre appears in Twilight Grove.",v=3}}
t[14888]={{tags="spawn",text="Lethon appears at one of four portal locations: Ashenvale, Duskwood, Feralas, or the Hinterlands. His location is random and not guaranteed to be the same each time.",v=36},{tags="spawn",text="In Duskwood he spawns in the middle of the area, in Twilight Grove, with no dragon adds nearby.",v=20},{tags="spawn",text="In the Hinterlands he spawns at Seradane, north of the river from the slime cave.",v=20}}
t[14889]={{tags="spawn",text="Spawns randomly in one of four places: Hinterlands, Ashenvale, Feralas, or Duskwood, at a random time.",v=30},{tags="spawn route",text="In Feralas, it spawns on the south edge of Jademir Lake, on the stone steps by the swirling portal.",v=6},{tags="spawn",text="In Duskwood, it is most often seen in the Twilight Grove.",v=2}}
t[14890]={{tags="spawn",text="Taerar spawns at random times at one of the Emerald Dream portals in Ashenvale (northwest of Forest Song), Feralas (top part), the Hinterlands (Serenade area, top), or Duskwood (Twilight Grove); the location is not fixed.",v=40}}
t[14903]={{tags="floor inside",text="He is in a hut on stilts directly above the Zandalar vendor, so look up rather than at ground level.",v=7}}
t[14910]={{tags="route",text="He stands on a small island in the far northwest corner of Stranglethorn Vale, out in the ocean, so you need a way across the water to reach him.",v=4}}
t[14921]={{tags="floor inside",text="He is on the island northwest of Stranglethorn Vale, upstairs in one of the huts that has a second floor.",v=7},{tags="interact",text="Hold Shift when talking to him so an auto-RP addon does not complete the Essence Mango quest and cost a Zandalar Honor Token.",v=3}}
t[15011]={{tags="spawn access",text="He is only available during the Harvest Festival, which runs for a week in mid-to-late September each year.",v=2}}
t[15012]={{tags="spawn access",text="He only appears during the Harvest Festival event.",v=7}}
t[15021]={{tags="access",text="Offers quests only while your reputation is neutral or friendly; no quests are available once you reach honored.",v=1}}
t[15042]={{tags="route",text="From the start platform, swim right along the wall, climb out at the waterfall ledge, then cross the bridges to reach him.",v=24},{tags="floor inside route",text="Zanza stands at the top of a pyramid inside Zul'Gurub, directly behind the Venom Pit where the path splits.",v=23},{tags="access",text="Zanza only gives the quest and enchant turn-in after you reach friendly reputation with the Zandalar Tribe.",v=16}}
t[15077]={{tags="spawn route",text="He only appears during the fishing event. Leave the inn and turn toward the ocean; he stands next to a girl and a robot.",v=4}}
t[15079]={{tags="spawn",text="Fishbot 5000 appears only on Sundays from 2pm to 4pm server time.",v=65},{tags="inside",text="Fishbot 5000 is inside the inn in Booty Bay.",v=3}}
t[15126]={{tags="access",text="Only Horde players can buy from him; Alliance players must use the Alliance twin, Samuel Hawke.",v=1},{tags="access",text="Buying from him requires high enough Defilers' League reputation.",v=1}}
t[15176]={{tags="access",text="Vargus only appears after the Ahn'Qiraj gates are opened on your server.",v=1}}
t[15177]={{tags="route",text="Hop over the railing next to the building in Cenarian Hold to reach him.",v=1},{tags="danger",text="Level 70 elite guards stand near him in Cenarian Hold and kill him quickly.",v=1},{tags="spawn",text="He respawns about 10 minutes after being killed.",v=1}}
t[15180]={{tags="danger",text="Guards stand near him and will maul you if you attack him; killing him also costs 500 Cenarion Circle reputation.",v=8}}
t[15181]={{tags="spawn",text="He has been seen at 49,34 in the new camp.",v=9}}
t[15182]={{tags="floor",text="Find him atop the tower in Cenarion Hold.",v=3}}
t[15192]={{tags="spawn danger",text="He despawns when his health drops to 20%, so he cannot be killed and attacking him is pointless.",v=284},{tags="access",text="You must reach Neutral with the Brood of Nozdormu before he can be talked to; you start at Hated.",v=7},{tags="danger",text="He does not aggro unless he is attacked.",v=1}}
t[15194]={{tags="access",text="To make him give up his quest, start over at Geologist Larksbane and complete her quest chain beginning with The Twilight Mystery.",v=11},{tags="access",text="He will not accept texts until you finish a quest chain; the first quest is given by a female dwarf in Cenarion Hold.",v=8}}
t[15196]={{tags="patrol spawn",text="Deathclasp patrols the southern area near Bronzebeard's camp and spawns near the top of the trail above the camp.",v=22},{tags="route",text="Go up the trail right behind Bronzebeard Encampment, following the trail of body parts up a ramp; he is on the hill just east of camp.",v=14},{tags="danger",text="Two guards or scorpid adds stand around him on the hill.",v=14}}
t[15197]={{tags="spawn",text="Find her outside Undercity in front of the Wickerman Festival, only in the evening while the festival is running.",v=4},{tags="spawn",text="During Hallow's End she stands in the courtyard above Undercity instead.",v=1}}
t[15200]={{tags="patrol",text="She wanders around the spot at 26,36.",v=4},{tags="spawn",text="She respawns almost instantly after being killed.",v=2}}
t[15202]={{tags="inside route",text="The cave is in the top right of Silithus.",v=10},{tags="inside danger",text="Vyral is inside the cave with two level 60 guards nearby.",v=10},{tags="route",text="Drop down from the rock bridge to reach Vyral without fighting the mobs in the path.",v=10}}
t[15203]={{tags="access interact",text="He is not a fixed spawn; he appears only when summoned at a Greater Windstone in Silithus with the required Twilight materials. Without a Scepter of Beckoning the summon is random among the royals.",v=41}}
t[15204]={{tags="spawn access",text="High Marshal Whirlaxis does not stand at a fixed spot. He appears only when summoned at a Greater Windstone in Silithus, and any Greater Windstone can be used.",v=69},{tags="access interact",text="To summon him, use a full Twilight Cultist set, a Twilight Cultist Medallion of Station, a Twilight Ring of Lordship and a Scepter of Beckoning: Thunder on a Greater Windstone.",v=69},{tags="access",text="The Twilight Ring of Lordship needed for the summon requires revered reputation with Cenarion Hold.",v=69}}
t[15205]={{tags="access",text="He is summoned at a Greater Windstone in Silithus, using a full twilight cultist set, a cultist Medallion of Station, a Ring of Lordship, and the Stone Scepter of Beckoning.",v=54}}
t[15206]={{tags="access spawn",text="Summon it at a regular windstone in Silithus, not a lesser or greater one, wearing the full Twilight Cultist set and carrying the Medallion of Station.",v=39},{tags="access spawn",text="Carry a Signet of Beckoning: Fire to make the windstone summon Cynders; without it the summon picks a random duke.",v=39}}
t[15207]={{tags="access",text="To summon him at a Silithus windstone, you need a full Twilight Cultist set, a Medallion of Station, and a Signet of Beckoning: Water.",v=19}}
t[15208]={{tags="access",text="Summon him at a Silithus windstone using a full item set 492, a Twilight Cultist Medallion of Station, and a Signet of Beckoning: Stone.",v=11}}
t[15209]={{tags="access interact",text="Summon it by touching a lesser windstone in Silithus while wearing the full Twilight Cultist set and carrying Crest of Beckoning: Fire; it does not wander on its own.",v=7},{tags="access",text="Summoning requires Friendly reputation with Cenarion Circle.",v=7},{tags="spawn",text="Stay close to it during the fight, because it may despawn if it gets too far away.",v=1}}
t[15211]={{tags="access interact",text="Summon the Azure Templar at a lesser windstone in Silithus while wearing the full Twilight Cultist set and carrying Crest of Beckoning: Water.",v=21},{tags="danger",text="Many elemental adds wander around the windstones, so expect other mobs nearby when summoning.",v=1}}
t[15212]={{tags="access",text="To summon the Hoary Templar, wear the full Twilight Cultist set and click a lesser windstone in Silithus while holding a Crest of Beckoning: Thunder; otherwise the templar that appears is random.",v=15}}
t[15215]={{tags="danger inside",text="Mistress Natalia sits in a room with other mobs that she guards; clear the room's mobs first, since she fears and can pull them in.",v=8},{tags="spawn danger",text="A burrower respawns very quickly directly behind her, so it can be pulled into the fight.",v=2}}
t[15220]={{tags="access interact spawn",text="He only appears when summoned at a windstone in Silithus, using a full item-set 492 set, a Twilight Cultist Medallion of Station, and a Signet of Beckoning: Thunder.",v=12}}
t[15282]={{tags="hidden",text="Aurel Goldleaf is directly behind the mailbox in front of the Inn in Cenarion Hold.",v=7}}
t[15305]={{tags="access",text="Lord Skwol is summoned from a Greater Windstone in Silithus; only a 1/4 chance the summon yields him, so the summon materials are lost if he is not the result.",v=46},{tags="access",text="Lord Skwol is a random royal result of the Greater Windstone summon, requiring a Twilight Ring of Lordship along with the medallion and cultist set.",v=8}}
t[15307]={{tags="access interact",text="Summon it at a lesser windstone in Silithus while wearing the full Twilight Cultist set and using a Crest of Beckoning: Stone.",v=23}}
t[15308]={{tags="spawn",text="The northern prophet respawns about 28 minutes (plus or minus 3) after being killed.",v=32},{tags="spawn",text="The southern prophet respawns about 60 to 70 minutes after being killed.",v=32},{tags="patrol route",text="Expect the northern patrol to run between Base Camp and the NW camp, and the southern patrol from the SW camp into south Hive'Zora.",v=16}}
t[15309]={{tags="inside",text="She is inside the Orphanage in the Valley of Honor, in the building next to the fishing trainer.",v=2}}
t[15310]={{tags="inside",text="He is inside the Stormwind Orphanage.",v=1}}
t[15350]={{tags="spawn",text="The Horde Warbringer has despawned and no longer appears in the game; its Marks of Honor quests no longer exist.",v=3}}
t[15351]={{tags="route spawn",text="He is in Silverwing Grove in Ashenvale, at 62,83.",v=1}}
t[15353]={{tags="spawn",text="She is only available during the Hallow's End event, and she stands in Ironforge next to the bank.",v=5}}
t[15354]={{tags="spawn",text="She only appears in October during the Hallow's End celebrations.",v=3}}
t[15362]={{tags="access interact route",text="Turn the Nightmare Engulfed Object (a green dragon drop) to Remulos in Moonglade; he cleans it in the lake and Malfurion appears there.",v=20}}
t[15378]={{tags="inside route",text="She is in the last chamber before C'Thun, inside the Temple of Ahn'Qiraj.",v=10},{tags="access",text="She is only reachable after the Twin Emperors are killed and the trash mobs between them and C'Thun are cleared.",v=10},{tags="route",text="Go down the hallway past C'Thun's room; her doorway is about halfway along it.",v=10}}
t[15379]={{tags="inside",text="Caelestrasz is in the room after C'thun at the end of the Temple of Ahn'Qiraj raid.",v=6}}
t[15380]={{tags="route",text="After the Twin Emperors, clear the trash mobs past them to reach Arygos.",v=9},{tags="inside",text="Arygos is in the last chamber before C'Thun, inside the Temple of Ahn'Qiraj.",v=3}}
t[15440]={{tags="access spawn",text="Talk to Janela Stouthammer first; she brings Captain Blackanvil out, so he does not appear until then.",v=22},{tags="danger spawn",text="A giant wasp-like elite (Hive'Zora/Ashi Abomination) spawns and fights with him, so be ready to fight.",v=22},{tags="spawn access",text="He only appears for that fight and must stay alive during it, or you cannot talk to him to get papers signed.",v=1}}
t[15445]={{tags="spawn",text="Do not expect to find him in Ironforge; players reported he no longer appears there and may have despawned.",v=18}}
t[15449]={{tags="access",text="Hive'Zora Abomination appears at your faction's camp in Silithus only after you take unsigned field duty papers from Windcaller Kaldon in Cenarion Hold.",v=38},{tags="danger",text="The Abomination is an elite standing around the Alliance post at Hive'Zora in Silithus, near 33,51.",v=1}}
