t[15500]={{tags="inside hidden",text="Keyl Swiftclaw is inside the inn at Cenarion Hold, just behind and to the right of the innkeeper.",v=6}}
t[15502]={{tags="access",text="Equipment quests from Andorgos stay unavailable until you have turned in at least one Qiraji Lord's Insignia.",v=34},{tags="inside floor route",text="Andorgos is in a small side room in AQ40: past the Prophet Skeram platform, take the left stairs down and stay left into the room with three NPCs.",v=4}}
