t[15504]={{tags="inside",text="She is in a side room inside AQ40, just beyond where The Prophet Skeram was.",v=1},{tags="floor route",text="From Skeram's platform, take the two stairs up, then the left stairs down for the first steps, then go straight and slightly left into her room.",v=1}}
