t[15526]={{tags="access interact",text="After delivering the love letter to Narain in Steamwheedle Port, talk to Meridith again to get her new option.",v=6},{tags="route",text="Swim straight out from the crashed gyrocopter toward the distant islands; she waits on a shelf before the drop-off.",v=3}}
