t[15541]={{tags="spawn patrol",text="Her marauder group spawns at 52,11 and rides south from there.",v=20},{tags="patrol",text="Her riders pass the Horde camp at 51,68 on the way south.",v=20},{tags="patrol",text="Her group's route ends at four Elf warriors mounted on tigers; the exact location is not known.",v=20}}
t[15549]={{tags="inside route",text="He stands in the middle of the Ring of Law arena inside Blackrock Depths.",v=80},{tags="interact danger",text="Talking to him starts the arena fight once you unstealth in the circle, so leave before the gates close if you only want the coin.",v=80},{tags="danger patrol",text="Without the Shadowforge Key or stealth, the first two dwarfs as you enter will aggro; watch for patrols along the route.",v=80}}
t[15556]={{tags="route inside",text="From Rotgrip's pool, take the cave or tunnel on the side away from Princess, then follow the path up the ramp to him at the top.",v=21},{tags="route inside",text="In Maraudon (the orange instance), drop down at Zaetar's grave to reach him; he is deep inside the instance.",v=3}}
