t[15583]={{tags="floor",text="He sits on top of a rock at Slithering Scar, not underground, near 50,76.",v=23},{tags="danger",text="Many nasty insects, around 52 or more, surround him at Slithering Scar.",v=23}}
t[15584]={{tags="route",text="He is found right after you get off the lifts.",v=1}}
