t[15588]={{tags="route",text="Alternatively enter the camp on its northeast side to reach him.",v=12},{tags="danger",text="Camp guards may attack you when you approach him; grab the coin and leave without fighting back.",v=12},{tags="inside",text="He stands inside Camp Taurajo in the Barrens at 45,57, near the forge and anvil.",v=10}}
t[15593]={{tags="inside floor danger",text="Elder Starsong is inside the Temple of Atal'Hakkar, on the dragonkin floor to the northeast, between groups of dragonkin.",v=14},{tags="interact danger hidden",text="Stealth or invisibility is needed to reach her without aggro; she is in a debris-blocked niche and becomes visible and attacked once you click her.",v=14},{tags="route floor hidden",text="Reach her by going up the stairs on the left after entering, then turning left; she is in the small side alcove off the big central room.",v=6}}
