t[8507]={{tags="access",text="Talk to Janella at the camp to start the wasp battle; the Captain only appears once the fight begins.",v=10},{tags="route",text="The wasp battle takes place around 33,51.",v=10},{tags="danger",text="Mobs close to the battle area aggro when the huge wasp uses its fear, so watch for them.",v=10}}
t[8513]={{tags="spawn",text="Private Porter may no longer be in his spot after Ahn'Qiraj opened; several players could not find him there.",v=8}}
t[8517]={{tags="spawn",text="The Alliance supply NPC disappears once the realm's war effort collection ends and stops taking donations; she cannot be found then.",v=17}}
t[8519]={{tags="interact",text="If the quest did not complete, abandon it and click the red crystal on the ground again to restart the event.",v=14},{tags="access",text="Eranikus does not appear in the open world; he is summoned at the Moonglade temple after the earlier quest steps.",v=6}}
t[8522]={{tags="spawn",text="Keeper Moodshade, the bandage collector, appeared only during a special event and may be absent from Ironforge otherwise; a reply says he is back at 54,78.",v=4}}
t[8523]={{tags="spawn",text="Keeper Moodshade was only present for a special event and is no longer in the game, so he cannot be found.",v=7}}
t[8524]={{tags="route",text="He stands to the right of the entrance to Tinker Town in the Military Ward.",v=3}}
t[8534]={{tags="inside route",text="Enter the hive cave whose entrance is at 25,55; the scout is inside at about 23,62.",v=97},{tags="inside",text="She stands in the sideways X-shaped room in the southernmost cave of the system, against the south wall.",v=19},{tags="hidden inside",text="She is often stealthed and does not show on the minimap, so look along the square-shaped tunnels' walls.",v=11}}
t[8536]={{tags="access",text="Talk to Humm Wildman first to receive the Aurel Goldleaf quest; Aurel stands next to the inn in Cenarion Hold.",v=21},{tags="interact",text="Wear the full twilight garb and click a lesser windstone to summon a random elemental or templar.",v=14},{tags="access danger",text="Get Aurel's medallion first; without it the summoning stone's lightning bolt strikes you.",v=13}}
t[8537]={{tags="access interact",text="Summon the elite at the Twilight camp; it does not appear until you do this.",v=3}}
t[8538]={{tags="access interact",text="Each duke must be summoned with the matching Signet of Beckoning for its element type; the Scepter named in the comment is wrong, since Scepters are for Abyssal Lords.",v=5},{tags="access",text="The quest only drops as a followup to a tactical task, so you need to be on the tactical chain to receive it.",v=3},{tags="access spawn",text="The Field Duty quest givers appear only after the Ahn'Qiraj gates open event, after the final battle in front of the great wall.",v=1}}
