t[8548]={{tags="access",text="The Volunteer's Battlegear quests are given only after completing the Field Duty quest for the Cenarion Circle.",v=14},{tags="spawn",text="The Twilight Prophet spawns rarely and is most often seen late at night server time when few other players are around.",v=14},{tags="inside",text="The Combat badge bugs are inside the Zora, 'Ashi and Regal hives.",v=14}}
t[8551]={{tags="",text="The Captain is found at coordinates 37,69.",v=1}}
t[8553]={{tags="route danger",text="Mok'Rash is on the south end of the small island with the large statue in Booty Bay harbor.",v=39},{tags="danger",text="Apocryphan's Rest in the Badlands is where to farm buzzard wings; Kargath, a Horde haven, is just around the corner.",v=39}}
t[8554]={{tags="spawn interact",text="After the food and wine are placed in the rowboat, Negolash surfaces in the water a little north of it and heads toward the boat.",v=29},{tags="route",text="The rowboat is on the Bloodsail beach at a small bump out of the shoreline, around the corner and before the first tent.",v=29},{tags="danger spawn",text="Negolash is an elite giant that appears in the water by the rowboat.",v=29}}
t[8555]={{tags="access",text="Requires completing the quest A Pawn on the Eternal Board first; it is the previous step in the Gates of Ahn'Qiraj event chain.",v=4},{tags="interact inside",text="Talk to Vaelastrasz the Corrupt in Blackwing Lair, Shade of Eranikus in Sunken Temple, and Azuregos (his ghost) in Azshara to progress this quest.",v=2}}
t[8558]={{tags="access",text="This quest only appears in Silithus after the Gates of Ahn'Qiraj are open on your server.",v=3}}
t[8561]={{tags="access inside",text="Requires Friendly reputation with the Brood of Nozdormu, and the class quest must be accepted from Andorgos in a side room of AQ40 just beyond Prophet Skeram.",v=3}}
t[8572]={{tags="access",text="The quest needs Honored reputation with the Cenarion Circle before it can be completed, and a Friendly character could not see it.",v=5},{tags="access",text="The quest only appears in Cenarion Hold after the Ahn'Qiraj gates are opened on the server.",v=1}}
t[8573]={{tags="access",text="You need Combat, Logistics and Tactical badges from Field Duty assignments, which start at Cenarion Hold, plus Exalted Cenarion Circle reputation before this quest can be completed.",v=76},{tags="access",text="The Mark of Cenarius, required for this quest, comes from completing The Four Dukes, which is reached through Tactical Task Briefing V.",v=14}}
t[8574]={{tags="access",text="Complete the Field Duty quests repeatedly to unlock the Combat, Tactical and Logistics quests this quest needs.",v=140},{tags="access",text="The Mark of Remulos required for this quest only comes from a Followup Assignment on a Logistics quest, so keep doing those until you get it.",v=7},{tags="access",text="This quest only becomes active after the Ahn'Qiraj gates are opened on your server.",v=1}}
t[8575]={{tags="access",text="You must be Neutral with the Brood of Nozdormu before you can talk to Azuregos and receive the letter.",v=1}}
t[8577]={{tags="hidden",text="Look for the Inconspicuous Crate at 46,86 beside the Greymane Wall in Silverpine Forest, near the gate that does not open; Haggard Refugee is in the crate.",v=19}}
t[8578]={{tags="inside interact",text="The goggles can be found in Domo's chest inside Molten Core; open it to check for them.",v=2},{tags="access",text="This quest is part of the questline that follows Stewvul, Ex-B.F.F., so that quest must be completed first.",v=1}}
t[8584]={{tags="access",text="The Cenarion Hold quest-giver only offers this after the Gates of Ahn'Qiraj chain is started, following Translating the Ledger.",v=13}}
t[8585]={{tags="route inside",text="The only entrance to the island's center is a valley in the southeastern corner, around 35,88 on the map.",v=35},{tags="route inside danger",text="The center's entrance is under the word 'Dread' on the map; the interior holds level 60-61 elite dragons.",v=4}}
t[8586]={{tags="access",text="Kill Broodlord Lashlayer in Blackwing Lair first; this quest only becomes available later in the Ahn'Qiraj chain.",v=8},{tags="access",text="You do not need 300 Cooking to get this quest.",v=8},{tags="access",text="This quest is part of a long chain that starts with the quest Only One May Rise.",v=4}}
t[8592]={{tags="access inside route",text="Gain friendly reputation with the Brood of Nozdormu and accept the class quest from Andorgos first; she is in a side room just beyond The Prophet Skeram inside AQ40.",v=6},{tags="inside access",text="Emperor Vek'nilash, who drops the required Vek'nilash's Circlet, is killed inside The Temple of Ahn'Qiraj (AQ40).",v=6}}
t[8597]={{tags="danger",text="Chapter II is held by a Felguard Elite near the Tainted Scar by the Dark Portal in the Blasted Lands.",v=49},{tags="inside",text="Chapter V is in the Stormwind library.",v=49},{tags="danger",text="Chapter VI is held by Onyxia in her raid, so it requires defeating her.",v=49}}
