t[8659]={{tags="inside route",text="The quest giver stands just inside the temple, to the left, with three Alliance-type NPCs.",v=8},{tags="access",text="You need neutral reputation with the Brood of Nozdormo to receive the Striker's Garb quests.",v=1},{tags="access",text="Completing this quest requires 200 reputation with the Brood of Nozdormo.",v=1}}
t[8660]={{tags="access inside route",text="Requires Neutral reputation with the Brood of Nozdormu and the class quest from Kandrostrasz, who is in a side room just past Prophet Skeram inside AQ40.",v=1}}
t[8662]={{tags="access",text="Gain friendly reputation with The Brood of Nozdormu before this quest's class quest chain can be started.",v=5},{tags="inside",text="The required Vek'nilash's Circlet comes from Emperor Vek'nilash, who is inside the Temple of Ahn'Qiraj (AQ40).",v=5}}
t[8664]={{tags="access",text="Turn in the Qiraji Lord's Insignia first; this unlocks the new quests, including this one.",v=8},{tags="access inside route",text="Reach Neutral reputation with the Brood of Nozdormu and accept the class quest from Andorgos in a side room just past The Prophet Skeram in AQ40.",v=4},{tags="access",text="Kill Viscidus or Princess Huhuran to loot the Qiraji Bindings of Dominance token needed for this quest.",v=4}}
t[8665]={{tags="access",text="Needs Neutral reputation with The Brood of Nozdormu and the class quest from Kandrostrasz in AQ40 before this quest is available.",v=3}}
t[8666]={{tags="access",text="Complete the Mortal Champions turn-in (quest 8595) first, or the Genesis Vest quest and other 2.5 tier gear quests will not appear.",v=3}}
t[8668]={{tags="access inside route",text="Requires Friendly reputation with the Brood of Nozdormu and the class quest from Kandrostrasz, who is in a side room inside AQ40 just beyond The Prophet Skeram.",v=2},{tags="access",text="Requires completing at least one Mortal Champions turn-in before the tier 2.5 quests appear.",v=1}}
t[8669]={{tags="access",text="Requires neutral reputation with the Brood of Nozdormu before the quest can be obtained.",v=2},{tags="inside route",text="Find the quest giver inside AQ40, in a side room just past Prophet Skeram.",v=1}}
t[8670]={{tags="route",text="Go north on the road leading into Razor Hill; he stands on the right side, right behind the fence next to the inn.",v=9}}
t[8671]={{tags="route",text="Ragetotem is in the Valley of the Watchers at the far south of Tanaris, just outside the gates near the golems; coordinates 36,80.",v=17}}
t[8674]={{tags="floor",text="Winterhoof is on the roof of the bank in Booty Bay, next to the Horde flight point; go to the roof.",v=14}}
t[8675]={{tags="floor",text="Look on top of the tower at Sentinel Hill in Westfall; she is up there.",v=1}}
t[8676]={{tags="inside",text="Wildmane is inside Zul'Farrak, by the pool where Gaz'Rilla is found.",v=53}}
t[8677]={{tags="hidden",text="Darkhorn is among the red rocks in the Valley of Wisdom, just right of the building with Thrall in it; the coordinates are 41,33.",v=26}}
t[8678]={{tags="hidden",text="The Elder Rise lies west of the big tent, between two trees, at about 72,23.",v=18}}
t[8680]={{tags="hidden",text="He stands behind the bank in Ratchet, to the left of the building with Gazlowe in it.",v=1}}
t[8681]={{tags="route",text="He stands on a small rock just above the entrance of the Slithering Scar in southern Un'Goro Crater.",v=20}}
t[8682]={{tags="floor route danger",text="Ride the Lift up to the upper level where he stands; guards attack almost immediately after you arrive, so move quickly.",v=11}}
t[8685]={{tags="inside",text="Find the Elder inside the arena in Dire Maul's entrance area in Feralas, before the instance wings.",v=8},{tags="danger",text="Level 60 elite the Razza and level 58 rare Skan the Unbreakable are nearby the Elder's spot.",v=8}}
t[8686]={{tags="route",text="Reach him by going around the camp to a hole in the fence right behind him, opposite the inn.",v=1}}
t[8687]={{tags="inside",text="The Hive'Zora Tunnelers are inside the Zora caves and rarely venture out, so look for them there.",v=1}}
t[8690]={{tags="inside",text="The quest giver is inside the inn at Cenarion Hold in Silithus.",v=3},{tags="inside route",text="The quest requires going into the Gates of Ahn'Qiraj, an instance entered from inside the raid area.",v=3}}
t[8692]={{tags="inside",text="The quest's required items drop from inside the Ruins of Ahn'Qiraj (AQ20), not from a quest area.",v=2}}
t[8702]={{tags="access",text="Quest requires Honored reputation with the Cenarion Circle before it can be picked up and turned in.",v=4}}
t[8704]={{tags="inside",text="The entity is inside Ahn'Qiraj 20 (AQ20), the 20-player raid instance.",v=1}}
t[8705]={{tags="access",text="Obtaining the gavel requires reaching exalted reputation with Cenarion Circle first; the grind to get there is the hard part.",v=4}}
t[8707]={{tags="access",text="Requires Exalted reputation with the Cenarion Hold to get this quest; Friendly gives nothing.",v=6},{tags="inside",text="The Qiraji Ornate Hilt drops from Moam inside Ahn'Qiraj 20.",v=2}}
t[8708]={{tags="access",text="You must be Exalted with the faction to turn in this quest; the quest log's friendly/exalted line shows your current standing against the required Exalted.",v=4}}
t[8710]={{tags="access",text="Use Kris of Unspoken Names only after reaching Exalted with Cenarion Circle; the quest requires it and the AQ20 drops, so the weapon cannot be obtained otherwise.",v=4},{tags="access spawn",text="The three quest-giving NPCs open after the AQ event and are in and around the Inn at Cenarion Hold.",v=4}}
t[8712]={{tags="access",text="Completing the quest requires Exalted reputation with the Cenarion Circle.",v=4},{tags="access",text="The quest only becomes available after the Ahn'Qiraj gates are opened.",v=2}}
t[8713]={{tags="inside route",text="In the Sunken Temple (Atal'Hakkar), go to the top of the spiral staircase, turn left, follow the short hallway into the large round central area, then turn left; he is at the rear of the next alcove on the left.",v=87},{tags="danger",text="A pack of dragonkin stands at the top of the spiral staircase, and more mobs are at the end of the hallway before the central area.",v=87},{tags="inside hidden route",text="He is in a niche or dead end off the open circle inside the Sunken Temple, to the left.",v=1}}
t[8714]={{tags="floor inside route",text="Enter the Caer Darrow barracks, go right instead of left through the locked door, climb the stairs to the top; she is on the catwalk on the roof.",v=24}}
t[8716]={{tags="inside danger",text="Find him in the northeast corner inside the Zul'Gurub temple, near the wall before the instance gate; three mobs surround him.",v=2},{tags="route danger",text="Mount up on the platform by the gate, hop down on the side away from the mobs, and talk to him before they reach you.",v=1}}
t[8722]={{tags="patrol",text="She wanders around the Weeping Cave area, so check the cave entrance and nearby spots if she is not at the listed position.",v=1},{tags="inside route",text="Recent reports place her inside the Weeping Cave, a little way past the entrance; veer slightly right after entering.",v=1}}
t[8723]={{tags="inside route",text="Enter the Jaedenar compound, cross the bridge and turn north to find Nightwind.",v=17},{tags="inside",text="Nightwind stands at 37,53 inside the Jaedenar compound.",v=11}}
t[8727]={{tags="route inside",text="Enter Stratholme on the Scarlet side and go right past the room with the plague rats.",v=23},{tags="route inside",text="Use the service entrance (back door) into Stratholme, go through the first gate, and run along the left wall.",v=2},{tags="route inside",text="Go right at the fountain area and hug the wall; the light on the left side marks the Elder's spot.",v=2}}
t[8728]={{tags="access",text="This quest follows 'Scrying Goggles? No Problem!' and 'Return to Narain The Only Prescription' in the Gates of Ahn'Qiraj questline, so those come first.",v=1}}
t[8729]={{tags="access",text="The quest only becomes available after the Gates of Ahn'Qiraj event opens, and it is part of that event's questline.",v=3},{tags="access",text="The first step requires the head of Broodlord Lashlayer from Blackwing Lair before the quest can progress.",v=1}}
t[8730]={{tags="spawn",text="Nefarian must die within five hours of talking to Vaelastrasz, or he destroys the Scepter Shard and the quest fails.",v=25},{tags="interact inside",text="Talk to Vaelastrasz in Blackwing Lair before he is engaged to start the quest and its five-hour timer.",v=21},{tags="access",text="The quest requires prerequisites first: Broodlord's Head, Only One May Rise, neutral Brood of Nozdormu standing, and the Anachronos quest chain.",v=6}}
t[8731]={{tags="interact",text="Right-click the unsigned papers to prepare them before talking to Krug Skullsplit, or he will not sign them.",v=28},{tags="interact spawn danger",text="Talking to Krug Skullsplit by Hive'Royal spawns the Hunter-Killer bug; let the NPCs kill it, then talk to Krug again.",v=28},{tags="spawn",text="After the bug dies, Krug respawns with a question mark over his head and will sign the prepared papers.",v=28}}
t[8733]={{tags="route patrol",text="At the first stairs, stay left and wait for the patrol to go down before climbing three long flights to the balcony.",v=28},{tags="patrol danger route",text="Hazzas and Morphaz patrol the southern hallway near the corner to Eranikus's room; if they are on the left, wait for them to pass.",v=28},{tags="danger route",text="A trash pack blocks the southern hallway; pass by hugging the left wall, or jump onto the wall ledge on the right to avoid aggro.",v=28}}
t[8735]={{tags="danger",text="In Duskwood, the fragment requires defeating the Twilight Corruptor, a raid-level boss, rather than farming trash dragons.",v=9}}
t[8736]={{tags="access",text="Requires the Ahn'Qiraj opening chain: after the Nozdormu brood and Broodlord Lashlayer's head, and after The Nightmare's Corruption.",v=1}}
t[8737]={{tags="access interact",text="Equip the three Twilight cultist pieces (mantle, robe, cowl) looted from the camp mobs before using the stone.",v=28},{tags="interact",text="Right-click the lesser wind stone while wearing the three pieces to summon the deity; it is random and may summon an earthen one instead of an azure.",v=28}}
t[8738]={{tags="inside route",text="The cave entrance is at 54,87 in Hive'Regal; the scout is inside the cave at 53,97.",v=87},{tags="route",text="The correct cave is at 8 o'clock in Hive'Regal; the cave at 6 o'clock is the wrong one.",v=14},{tags="danger route",text="Bugs swarm the scout; approach Landrion from behind to avoid aggroing the bugs near him.",v=14}}
t[8739]={{tags="inside route",text="Enter the upper entrance of the northernmost cave at 44,16, not the lower one, then go right; left is a dead end.",v=73},{tags="inside",text="Scout Jalia stands just inside the large chamber, immediately left of the tunnel door.",v=73},{tags="hidden",text="The scout may be stealthed and blinks in place, so walk close to her to find her.",v=8}}
t[8740]={{tags="patrol spawn",text="Marauders arrive to attack Cenarion Outrider patrols at spots near 67,36, 38,78 and 23,44; wait there for them.",v=7},{tags="danger",text="Morna, a level 60 elite, travels with the group of nine Marauders.",v=7},{tags="patrol spawn",text="Wait on the road directly southwest of Staghelm Point near the Cenarion Outrider NPCs; the Marauders can take up to 10 minutes to arrive.",v=3}}
t[8743]={{tags="access",text="The quest is part of the Gates of Ahn'Qiraj event questline and requires The Might of Kalimdor first.",v=2},{tags="access interact",text="Bang the gong only once the gates are still closed; after they open, it does nothing and the reward is lost.",v=1},{tags="access spawn",text="The mount is only obtainable if you open the gates yourself and finish the quest line within 10 hours of the gates opening on your server.",v=1}}
t[8744]={{tags="spawn",text="The quest is only available during the Christmas period.",v=9},{tags="spawn inside route",text="Go to Iron Forge early in the morning, then to The Common, where presents are under the Christmas tree.",v=1}}
t[8745]={{tags="spawn access interact",text="The Scarab Gong is in southern Silithus; ring it, and the quest NPC (Jonathan the Revelator) appears next to it.",v=22}}
t[8746]={{tags="inside floor",text="In Tanaris, Metzen is inside the wooden stable in the middle of the Southshore camp, about 73,47.",v=63},{tags="danger",text="In Tanaris, four or more level 44-45 pirate kidnappers stand in front of Metzen's stable and attack together.",v=63},{tags="danger",text="In Searing Gorge, Metzen sits in a Dark Iron kidnapper camp at about 64,34, guarded by four to six level 45 mobs that attack together.",v=46}}
t[8753]={{tags="access",text="Rep-based ring choice: talk to Anachronos at the Caverns of Time and pick the ring matching your current reputation level before completing.",v=1}}
t[8757]={{tags="access",text="This is not a real quest: once you reach neutral reputation with the Brood, Anachronos gives you the ring for free.",v=6}}
t[8762]={{tags="danger",text="In Searing Gorge, Metzen is surrounded by level 45-47 guards that aggro together in groups of five or six.",v=40},{tags="route",text="In Searing Gorge, Metzen is at 68,34, at the road crossroads/T-junction near the tunnel from Loch Modan, northeast of Thorium Point.",v=34},{tags="inside route",text="In Tanaris, Metzen is inside the pirate camp in a small roofed stable south of the main campfire, in the first stall.",v=3}}
t[8763]={{tags="access",text="Complete the other Winter Veil holiday quests and reach 300 Cooking before the quest appears.",v=9},{tags="access",text="You need exactly 300 Cooking skill to use the holly preserver machine.",v=3},{tags="route",text="For the Horde, the machine is directly right of the quest giver outside the Auction House in Orgrimmar.",v=3}}
t[8764]={{tags="access",text="Requires exalted reputation, all the scarabs, and the warrior ring before this quest can be started.",v=2}}
t[8765]={{tags="access",text="Reach full Exalted with the Brood of Nozdormu to make this quest available again for switching your ring choice.",v=19}}
t[8767]={{tags="spawn access",text="The quest only becomes active later, closer to Christmas, so its objects cannot be clicked before then.",v=1}}
t[8769]={{tags="spawn",text="The gifts can still be picked up after Christmas as long as they remain visible.",v=1}}
t[8773]={{tags="patrol danger",text="Five or six elite Reavers roam around the outside of Hive'Zora; check the outer area rather than going inside.",v=23},{tags="spawn",text="Reavers respawn quickly after being killed, so the outside area refills while you travel back.",v=23}}
t[8775]={{tags="access",text="If the quest is already in your log, the briefing scroll will not work; abandon the quest and reread the scroll to accept it.",v=1}}
t[8777]={{tags="spawn inside",text="Burrowers spawn close to the hive entrances at 60,78.",v=10},{tags="spawn",text="Burrowers spawn outside the hive at 51,81, 54,71, 59,71 and 44,84.",v=10},{tags="inside spawn route",text="Use the tunnel with a spiral ramp at its front and two entrances; a burrower spawns at each entrance.",v=8}}
