t[8784]={{tags="access inside route",text="The Brood of Nozdormu dragon NPCs are inside AQ40, behind the first boss, and cannot be reached until that boss is killed.",v=17}}
t[8789]={{tags="inside",text="Arygos, the quest giver, is in the last chamber before C'Thun inside the Temple of Ahn'Qiraj.",v=9},{tags="access route",text="Beat the Twin Emperors first; the quest NPC's room is right next to C'Thun's room.",v=4},{tags="danger route",text="Pass the doorway into C'Thun's room and hug the left wall to avoid aggro; the quest NPC is one of three behind blue force fields.",v=4}}
t[8790]={{tags="inside",text="Merithra of the Dream, the quest giver, is in the last chamber before C'Thun inside the Temple of Ahn'Qiraj; one of three NPCs there.",v=71},{tags="access route",text="The gates stay closed until the Twin Emperors are killed, and all trash between them and C'Thun must be cleared to reach the quest giver.",v=2},{tags="danger",text="A series of large insect pulls, dangerous enough to wipe a raid, lies between the Twin Emperors and the quest giver.",v=2}}
t[8791]={{tags="inside",text="Ossirian the Unscarred, the boss whose head this quest needs, is inside Ruins of Ahn'Qiraj.",v=31},{tags="access",text="Speak to Zidormi at 78,24 to go back in time first; the quest turn-in is only reachable after this.",v=6}}
