t[8828]={{tags="spawn access",text="Presents are a random drop; hang around Orgrimmar or Ironforge until Father Winter calls out that it is time to open them.",v=5},{tags="spawn",text="Father Winter only appears around Christmas time, so you must wait for the holiday to find him.",v=1}}
t[8829]={{tags="access",text="This quest only appears from a Followup Assignment, randomly, after completing 15 Logistics badge quests.",v=8}}
t[8840]={{tags="spawn access",text="This quest's signets were only used during the Ahn'Qiraj War Effort world event, so it is only available while that event is running.",v=2}}
t[8855]={{tags="patrol",text="Warlord Gorchuk, an orc on a wolf, walks up and down the Valley of Spirit (Horde side).",v=1}}
t[8857]={{tags="access",text="The quest giver appears in Cenarion Hold only after a colossus is killed during the 10-hour AQ event.",v=6},{tags="spawn",text="The quest giver and any remaining colossi vanish when the 10-hour AQ event ends, so take the quest and turn it in during the event.",v=4}}
t[8858]={{tags="access spawn",text="Only available during the AQ war after the colossus is dead; it disappears when the war ends, so it cannot be done later.",v=3}}
t[8859]={{tags="access spawn",text="The quest only becomes available during the AQ war after the Colossus is dead.",v=1}}
t[8866]={{tags="inside",text="Bronzebeard the Elder is inside the Mystic Ward in Ironforge, at 29,17.",v=25}}
t[8867]={{tags="interact",text="Alliance players must fire the fireworks in Ironforge's Mystic Ward; firing them elsewhere does not count toward the quest.",v=20},{tags="interact",text="Horde players must fire the fireworks in Orgrimmar's Valley of Wisdom; firing them elsewhere does not count toward the quest.",v=20},{tags="access",text="Buy the small and cluster rockets from the Lunar Festival vendor found in the capital cities, not from the quest giver.",v=4}}
t[8868]={{tags="interact",text="After Omen dies, stand in the light on his corpse to receive Elune's Blessing. Faction does not matter.",v=355},{tags="interact",text="If quest credit does not appear, stay on the corpse, cancel the Elune's Blessing buff, and let it reapply; repeat until credit is granted.",v=355},{tags="access spawn",text="Reach Moonglade with a Lunar Festival invitation; Omen and this quest are only available during the Lunar Festival event.",v=95}}
t[8870]={{tags="inside",text="The elder at Blackchar Cave in Searing Gorge is inside the cave.",v=1},{tags="inside",text="The elder at Scholomance in the Western Plaguelands is inside the instance.",v=1}}
t[8871]={{tags="interact access",text="Buy fireworks from the vendor beside the quest giver, then set them off; the quest log names differ from the shop names, so buy singles or clusters.",v=1}}
t[8872]={{tags="interact",text="Open the Lunar Festival invitation while standing in the Greater Moonlight area where you launched the fireworks; it teleports you to Moonglade.",v=3},{tags="access",text="Dismissing your pet made the quest start working for one player; it failed until then.",v=3}}
t[8878]={{tags="spawn",text="This festive quest is only available during the Lunar Festival season.",v=6},{tags="access",text="The quest only appears to characters around level 30 to 35 and up; a level 23 tailor could not see it.",v=2}}
t[8883]={{tags="access route",text="The Lunar Festival only runs in the original capitals; Silvermoon players must take the transporter to Undercity to start it.",v=4},{tags="interact access",text="Stand in the light at the Mystic Ward in Ironforge, the Park in Stormwind, or the Darnassus ward, then use the invitation to be sent to Moonglade.",v=3}}
t[8893]={{tags="route spawn",text="Go into the mountain range in Feralas behind the ogres, south of Dire Maul, and check the nests there; sometimes one holds an egg.",v=3},{tags="spawn",text="A group of four nests lies around 58,76; check them for an egg.",v=3}}
t[8897]={{tags="access",text="You cannot accept this quest if you have already completed the Valentine's Day dress or suit quest; the quest is only available before that.",v=23}}
t[8898]={{tags="access",text="The quest can only be accepted if you have not already gotten the Valentine's dress or suit quest.",v=35},{tags="",text="Colara is at 54,65 in Stormwind.",v=6}}
t[8899]={{tags="access",text="Accept this quest only if you have not yet completed the V-Day Dress or Suit quest; otherwise it cannot be taken.",v=40},{tags="route",text="Turn it in to Colara in Stormwind, standing beside the fountain guy; she is not outside the bank.",v=40}}
t[8902]={{tags="spawn",text="Elenia only appears right beside the bank in Undercity during the Valentine's event window; outside it she is absent and cannot be found.",v=3}}
t[8903]={{tags="access",text="Buy perfume or cologne and Love Tokens from the innkeeper at the Stormwind inn in front of the bank.",v=59},{tags="access",text="Keep the Love Tokens in your inventory; they cannot be handed to other players.",v=16},{tags="spawn",text="Wait for a heart to appear above a guard's head before interacting; the heart only shows for a limited time.",v=16}}
t[8904]={{tags="access",text="Buy perfume or cologne and love tokens from the innkeeper or his goods before starting; they are required for this quest.",v=47},{tags="access interact",text="Use perfume on male NPCs or cologne on female NPCs, stand close, and wait about 5 seconds for hearts to appear over them.",v=47},{tags="interact",text="Give a love token to an NPC with a heart overhead to receive a package; keep doing this until you get the moldy card.",v=47}}
t[8905]={{tags="spawn",text="On the hillside with cubs near 51,11 or 55,11, the cubs respawn after you kill them, so wait for the respawn and kill again.",v=14}}
t[8906]={{tags="inside route",text="The quest giver is inside the High Seat entrance in Ironforge, on your left as you walk in.",v=6}}
t[8907]={{tags="access",text="The quest requires level 58 or higher to start.",v=1}}
t[8909]={{tags="spawn",text="Frost sabers, a mob this quest needs, are plentiful around 51,19.",v=8}}
t[8918]={{tags="route",text="The venom-dropping spiders and scorpions are on the left side just outside the south exit of Cenarion Hold.",v=2}}
t[8920]={{tags="",text="A Supernatural Device is the next quest in the series; it is not needed to finish this quest.",v=4}}
t[8921]={{tags="interact",text="Volcanic Ash lies in piles along the lava river in Burning Steppes; pick it up directly, no kills needed.",v=21},{tags="interact",text="Place the Distiller in front of Southwind Village's gate and pull a mob into its light.",v=8},{tags="danger spawn",text="Three swarmers appear when a mob dies at the Southwind Village Distiller spot.",v=8}}
t[8922]={{tags="access",text="Quest requires level 60 to start; comments say it is level 60 with a level 58 requirement, and the previous quest must be completed first.",v=21},{tags="inside route hidden",text="The Mux guy is in a hut in the northeast part of Gadgetzan, near the egg gal and the Master Engineer's hut.",v=2}}
t[8924]={{tags="spawn",text="The distiller despawns after about five minutes, or if you or party members wander too far from it or die, so stay close to it.",v=16},{tags="interact",text="Drop the Ectoplasmic Distiller on the ground and make sure each ghost is inside its blue glow when it dies, or no ectoplasm drops.",v=13},{tags="",text="In Southwind Village, Silithus, place the distiller near 62,53 to pull the nearby undead.",v=11}}
t[8925]={{tags="danger route",text="Bokk stands in the middle of a lava pool near 36,58, with imp adds around him; the elite drake may fly over the pool.",v=6},{tags="danger patrol",text="A level 54-57 elite Scalding drake patrols near the lava pool; watch its route before you pull Bokk.",v=3},{tags="spawn",text="Bokk respawns quickly, usually within a minute or two after being killed.",v=2}}
t[8928]={{tags="inside route",text="Vi'el the imp is inside a cave at 58,78, reached by a ramp up the hill to the right of the road south of Everlook.",v=12},{tags="route",text="Stay hard right against the mountain wall past the pillars and two dead trees to reach the cave ramp, avoiding the road.",v=7},{tags="danger",text="Two elite guards stand at the gorge entrance; slip along the right wall past them without aggroing.",v=7}}
t[8929]={{tags="interact access hidden",text="Right-click the Extra-Dimensional Ghost Revealer at the Stratholme summoning stone to make Anthion Harmon visible.",v=14},{tags="route",text="Anthion stands on the bridge in front of Stratholme's main entrance, about 15 feet in front of the meeting stone.",v=11},{tags="spawn",text="After you use the revealer, Anthion is visible for only about 10 minutes, so find him quickly.",v=1}}
t[8930]={{tags="hidden interact access",text="Stand in front of the meeting stone outside Stratholme's main entrance and use the Extra-Dimensional Ghost Revealer; he is hidden until revealed.",v=13},{tags="",text="He is at the main entrance meeting stone, reported around 30,17 (also 30,16 and 31,17).",v=8},{tags="route",text="He stands outside the main gate of West Stratholme, not inside the instance and not at the back entrance.",v=1}}
t[8931]={{tags="access",text="Access requires finishing the Ectoplasmic quest chain for the Tanaris NPC first; then the Beaststalker belt and gloves are turned in to upgrade.",v=4}}
t[8935]={{tags="access",text="Complete the Tanaris quests before this quest; they come first in the chain.",v=3},{tags="access",text="Only rogues can take this upgrade quest; druids have their own upgrade quests instead.",v=1}}
t[8937]={{tags="access",text="You must be level 58 or higher before this quest is offered.",v=5},{tags="access",text="You must be Honored with the Argent Dawn faction before this quest is offered.",v=3},{tags="access",text="After the bracers quest, the quest-giver sends you to Gadget for a long series of quests that lead to this one.",v=2}}
t[8945]={{tags="interact",text="Each player holding the quest must tag Baron Rivendare within the 45-minute timer; the kill itself can finish later.",v=54},{tags="patrol danger",text="Gargoyle patrols fly back and forth in the area past the gate after The Baron's Ultimatum; they have a long aggro range.",v=54},{tags="access",text="Baron's door does not open until the towers are destroyed.",v=3}}
t[8946]={{tags="access",text="You need the Extra-Dimensional Ghost Revealer to see Anthion and turn in this quest. If you lost it, Mux in a tent in Gadzettown gives you another.",v=13},{tags="hidden access",text="Anthion is a ghost standing outside the main Stratholme gate in front of the meeting stone. You can only see him with the Ghost Revealer.",v=5}}
t[8948]={{tags="access route",text="Enter Dire Maul North by using the Crescent Key, having someone else open the gate, or stripping, dying and resurrecting past it.",v=19},{tags="danger patrol",text="The ogre courtyard holds ogres and dogs; avoid ogre patrols and especially dogs, since dogs see through stealth.",v=19},{tags="route",text="Stealth straight across to the courtyard ramp, hop onto its left lip aiming mostly down, and drop only a short way down onto the ledge.",v=19}}
t[8949]={{tags="patrol danger inside",text="Patrol dogs wander around Dire Maul North, so watch for them while farming the ogres there.",v=4}}
t[8950]={{tags="spawn hidden",text="Ghosts respawn at fixed corners: one by the right hallway entrance and one in the bottom-right corner of the room beside it. Stand there to spawn one.",v=24},{tags="hidden inside route",text="Invisible ghosts ambush from the halls on either side of the middle ramp and only show when they are on you.",v=24},{tags="patrol route",text="Walking trees patrol the walkway; avoid them to reach the back hallway with the big tree.",v=24}}
t[8959]={{tags="access route",text="Anthion's ghost is at the Stratholme entrance and is spoken to while carrying the Extra-Dimensional Ghost Revealer.",v=2},{tags="access route spawn",text="Baron Rivendare can only be reached after the second gate from the Stratholme service entrance is opened; the 45-minute timer then starts.",v=2},{tags="danger spawn",text="Ghosts spawn close by and attack right after you receive the banner at the Dire Maul library.",v=2}}
t[8960]={{tags="access",text="Bodley stands in front of the Upper Blackrock Spire entrance; use the Extra-Dimensional Ghost Revealer to see him.",v=36},{tags="floor",text="Bodley is on the balcony outside the Blackrock Spire instance entrance.",v=3}}
t[8961]={{tags="spawn inside",text="Kill Mor Grayhoof, a spawned mob inside Blackrock Spire, for the druid objective.",v=16},{tags="inside",text="Kill Incendius inside Blackrock Depths and Emberseer inside Upper Blackrock Spire for the other objective pieces.",v=12},{tags="access",text="Summon the Duke of Cynders with a Signet of Beckoning; a Crest of Beckoning only works at lesser windstones.",v=1}}
t[8962]={{tags="inside",text="Kill the bugs in Hive'Regal in Silithus; the quest item drops from them, both inside and outside the tunnels.",v=19}}
t[8964]={{tags="floor",text="The Scarlet Praetorians you need to kill are in the upper courtyard near the castle in Tyr's Hand.",v=11}}
t[8965]={{tags="route",text="Ashes drop from the undead spirits at the top of the hill near the tower; the spirit standing on the steps works.",v=3},{tags="patrol",text="The cursed paladins and priests wander the island; find one alone, away from its pack.",v=3}}
t[8966]={{tags="route",text="In LBRS, drop down the giant stone ledges to the orc tents, then go away from the spiders toward the trolls to reach Voone's room.",v=8},{tags="access interact inside",text="After defeating War Master Voone in LBRS, use the brazier in his room to summon Mor Grayhoof.",v=1}}
t[8967]={{tags="danger interact",text="Clear the area around Alzzin in Dire Maul East first, then summon Isalien at the end boss.",v=7}}
t[8968]={{tags="access",text="You need the summon, which drops after killing the last boss of Live Stratholme, before the two bosses can be summoned.",v=7},{tags="inside",text="Summon Jarien and Sothos in the room where Balnazzar and Grand Crusader Dathrohan are fought, on the Living side of Stratholme.",v=1}}
t[8969]={{tags="interact inside",text="Use the brazier anywhere in the room to complete the objective; the room must be cleared first.",v=6},{tags="route inside",text="Enter the instance, jump right, and walk to the room where Kormok waits; he does not need to be summoned again after a wipe.",v=1}}
t[8970]={{tags="route danger",text="Swim east from the north beach of Theramore to reach the island; elite hydras are in the water on the way.",v=19},{tags="patrol danger",text="Elite hydras patrol the waters around the island.",v=19},{tags="spawn",text="Most baskets respawn at the tower on the hilltop; baskets also sit outside the northeast tower.",v=19}}
t[8979]={{tags="inside",text="Buy the cologne and perfume from the innkeeper at the inn in Undercity.",v=14},{tags="interact",text="Used bottles can be turned in for the quest, so an unused perfume or a partly charged cologne also works.",v=1}}
t[8983]={{tags="spawn access",text="The quest can only be completed during the Valentine's Day holiday, so the NPC may not be present at other times.",v=17}}
t[8984]={{tags="route",text="The winding path up the mountain starts near 75,24, east of Tarren Mill and behind the hill north-west of Durnholde Keep, and passes through a tunnel to Ravenholdt Manor.",v=36},{tags="route",text="Past Ravenholdt Manor, at the drop-off on the left, take a sharp left and keep following the path instead of dropping down the slope.",v=36},{tags="route",text="The Apothecary stands at the end of the path by a small pond and cauldron in Alterac Mountains, at about 89,75.",v=36}}
t[8988]={{tags="floor inside",text="The needed drop may come from the clerics in the tower at the top of the island; check the last cleric there.",v=1}}
t[8990]={{tags="access inside",text="After killing the final boss in Dire Maul East, she is summoned at that boss's spot inside the dungeon.",v=17}}
t[8991]={{tags="access interact inside",text="After killing Balnazzar, place the amulet piece in his room to summon Sothos and Jarien.",v=6},{tags="danger spawn",text="Skeletons spawn outside Balnazzar's room after he dies; kill them before going out there.",v=4},{tags="inside route",text="Balnazzar's room is on the Scarlet side of Stratholme.",v=1}}
t[8993]={{tags="interact",text="Buy love tokens and perfume or cologne from an innkeeper; wear the scent to see which NPCs accept tokens, switching scents as needed.",v=5},{tags="interact",text="Guards in Stormwind and Ironforge give the pledge of loyalty and their city's guard card when you talk to them.",v=5},{tags="interact",text="Bread and Dwarven homebrew come from NPCs not wearing heavy armor, such as the bread merchant and pie vendor.",v=5}}
t[8994]={{tags="inside route",text="Kill the Blackhand orcs in Upper Blackrock Spire (UBRS) to get the bracers; LBRS is not needed for this.",v=4}}
t[8995]={{tags="inside spawn",text="Summon Lord Valthalak from the center of the beast room; the fight begins there, with the entrance wall and its fire behind you.",v=7}}
t[9000]={{tags="",text="Give the Beaststalker Armor to the girl, then get the Beastmaster armor; the intermediate step is not clearly described in these comments.",v=1}}
t[9003]={{tags="inside",text="Officer Deliana is inside the room where Kimg of Ironforge is.",v=2}}
t[9011]={{tags="inside",text="Lord Vathalak, the quest's boss, is inside Upper Blackrock Spire (UBRS).",v=5},{tags="access",text="This is the final quest of the tier 0.5 quest line, so the earlier steps of that line must be done first.",v=5}}
t[9015]={{tags="interact spawn",text="Drop the Banner of Provocation in the middle of the arena when the sentencing yell plays, after killing the first wave of arena mobs.",v=44},{tags="danger spawn",text="Five elite gladiators, including Theldren, come out of the arena's door after the first wave and fight in a PvP-like way.",v=44},{tags="inside route",text="The arena is in Blackrock Depths, straight ahead of where you zone in.",v=4}}
t[9023]={{tags="inside",text="The quest giver is inside the Cenarion Hold inn, to the left of the innkeeper.",v=51},{tags="route",text="Venoxis is on the south side of Zul'Gurub, past the nook where Jek'lik is.",v=51},{tags="access",text="You need at least neutral reputation to enter Ahn'Qiraj 20 for the Kurinnaxx venom sac.",v=3}}
t[9024]={{tags="inside route",text="Morgan Pestle, the hand-in NPC, is inside Pestle's Apothecary on the west side of the street as you enter the Trade District from the gates.",v=3}}
t[9027]={{tags="spawn",text="The Finest Thread at 39,46 is a seasonal Valentine's NPC that has despawned after the event ended around Feb 15; he no longer appears there.",v=4}}
t[9028]={{tags="route inside hidden",text="The path up into the hills starts at 75,24 and zigzags up; the cave entrance is at 78,20 and leads through to Ravenholdt Manor.",v=205},{tags="route hidden",text="From the manor, go southeast to the rope circle at 83,20, take the path south up the hill, drop down the small ledge at 85,25, then turn left.",v=205},{tags="hidden route",text="Staffron Lerent stands at 87,14 on a clearing past a building up the hill; keep climbing right of the building to find him.",v=205}}
t[9033]={{tags="route",text="Most of the quest mobs lie along the route to the first boss area of each wing.",v=8},{tags="access",text="Requires an attunement quest first, such as the Naxxramas attunement; exalted reputation is not needed.",v=3}}
t[9042]={{tags="access",text="Dreadnaught Bracers requires a prerequisite quest that has you killing trash mobs in Naxxramas first.",v=3}}
t[9051]={{tags="spawn route",text="Wait near Krakle's tent at the smallest lake camp in Golakka Hot Springs; an elite Devilsaur appears after about 5-10 minutes.",v=29},{tags="spawn",text="The rare spawn Devilsaur King Mosh also counts for this quest.",v=27},{tags="patrol",text="Devilsaurs roam the area west of the volcano in central Un'Goro, where there are fewer mobs.",v=7}}
t[9052]={{tags="interact",text="Bloodpetal Sprouts are the entangling-root-looking plants in tar pit areas; pick them to get bloodcaps.",v=21},{tags="spawn",text="Wasps share spawn points with reavers and workers, so kill the other bugs to make wasps respawn.",v=20},{tags="hidden",text="Sprouts are hidden by grass around the ravasaur area; set ground clutter to lowest to see them.",v=9}}
t[9053]={{tags="interact",text="Activate the six serpent statues in this order: South, North, Southwest, Southeast, Northwest, Northeast. Each lights green when correct.",v=64},{tags="inside route",text="The statues are on the east side of Sunken Temple, among the serpents.",v=53},{tags="spawn floor",text="After the sixth statue, the troll boss spawns at the bottom, in the pool below the statues.",v=53}}
t[9085]={{tags="route",text="Find the necronic shard near the flying necropolis, in a zone marked by a skull on the continent map.",v=23},{tags="spawn",text="Kill non-elite undead near the shard until it is destroyed; the summoners and shadow only appear after that.",v=23},{tags="interact access",text="Use 8 necronic runes on one of the summoners that appear around the shard to evoke the shadow.",v=23}}
t[9089]={{tags="access",text="Complete the Echoes of War quest first, which requires killing trash mobs from every Naxxramas wing; no reputation level is needed.",v=3}}
t[9090]={{tags="access",text="Requires the prerequisite quest Echoes of War, which needs a raiding guild that is in Naxxramas.",v=1}}
t[9098]={{tags="access",text="Complete the Echoes of War quest first to unlock this quest.",v=5}}
t[9102]={{tags="access",text="Complete the quest Echoes of War first, which requires killing mobs in Naxxramas; this quest then becomes available.",v=1}}
t[9115]={{tags="access",text="Complete the quest Echoes of War first; this quest is only available after that.",v=1}}
t[9120]={{tags="access",text="Obtain the Phylactery of Kel'Thuzad first; it drops from Kel'Thuzad and starts this quest.",v=9}}
t[9121]={{tags="access",text="This attunement quest requires Honored reputation with the Argent Dawn before it can be taken.",v=53}}
t[9122]={{tags="route",text="Naxxramas is located in the EPL part of Plaguewood near the eastern gates, at 39,25.",v=24},{tags="access",text="You can pick up this quest at Friendly reputation with the Argent Dawn, but turning it in requires Honored.",v=14}}
t[9124]={{tags="route",text="Crypt spiders in Eastern Plaguelands at 15,28 drop the parts; this is the best-voted location.",v=56},{tags="inside route",text="The Terrorweb Tunnel entrance is on the northwest edge of Terrordale in Eastern Plaguelands; crypt spiders there drop parts.",v=13},{tags="danger patrol inside",text="A level 60 elite Nerubian Overseer patrols the Terrorweb Tunnel from one end to the other.",v=9}}
t[9125]={{tags="inside route",text="Farm the undead spider mobs in the Terrorweb Tunnel, which runs under the mountain on the west side of Terrordale in Eastern Plaguelands.",v=11},{tags="patrol",text="Roaming undead wander through the Terrorweb Tunnel, so watch for them while farming.",v=1}}
t[9126]={{tags="access",text="Bone Fragments drop only from skeleton-type undead, not from spectres, horrors or flayers.",v=31},{tags="spawn",text="Andoral in Western Plaguelands has many lower-level skeletons that respawn quickly, so it is a good place to collect Bone Fragments.",v=31},{tags="inside access",text="Rohan the Assassin is inside Light's Hope Chapel in Eastern Plaguelands and gives this quest only once you are Friendly with Argent Dawn.",v=29}}
t[9127]={{tags="access",text="Friendly reputation with the Argent Dawn is required before this quest can be picked up.",v=18},{tags="inside",text="Rohan the Assassin is inside Light's Hope Chapel, in the corner to the right as you walk in, wearing a big purple hat.",v=9},{tags="route",text="Bone fragments drop from undead in Felstone Field; the red ghouls there do not drop them.",v=1}}
t[9131]={{tags="access",text="You must be Friendly with the Argent Dawn before the quest giver will offer this quest.",v=4}}
t[9132]={{tags="access",text="You must be friendly with the Argent Dawn before the turn-in quests for these scraps become available.",v=45},{tags="inside",text="Korfax, who takes the scraps, is inside Light's Hope Chapel in Eastern Plaguelands.",v=45}}
t[9136]={{tags="access",text="The quest does not appear if your Argent Dawn reputation is still neutral; you must raise it above neutral first.",v=6}}
t[9137]={{tags="patrol",text="Treants wander around the forested patch north of Shatter Scar Vale in Felwood, where the quest mobs are.",v=1}}
t[9141]={{tags="access",text="The quest only appears after you reach at least Friendly with the Argent Dawn.",v=5}}
t[9153]={{tags="spawn route",text="Scourge invasion points move around; the Necropolis crystal pulses and sends glowing crystals toward the active spawn locations, so follow them.",v=31},{tags="spawn",text="Commander Helleran at Light's Hope Chapel may disappear after the invasion ends and cannot be found afterward.",v=19},{tags="route",text="Open the map, zoom out to the continent view, and look for skulls; each skull marks an active invasion attack.",v=9}}
t[9154]={{tags="spawn",text="The Keeper of the Rolls no longer appears here; this quest was tied to the Scourge invasion event, which has ended.",v=12}}
t[9165]={{tags="spawn",text="The caravan that the quest giver sends out only departs twice a day, so you must be at Light's Hope Chapel at those times to start the escort.",v=14}}
t[9178]={{tags="access",text="Accepting the writ may require a minimum reputation first; one level 55 player was refused with a requirements error.",v=5}}
t[9194]={{tags="access route",text="If the tailor lacks the Runecloth Robe pattern, it is taught by Darnall in Nighthaven, Moonglade.",v=52}}
t[9197]={{tags="access",text="You must be a Gnomish Engineer to get this quest; goblin engineers cannot, and the chicken is bind-on-pickup.",v=18}}
t[9198]={{tags="access",text="Turn in Argent Dawn honor tokens to get this quest; you receive a random one rather than choosing.",v=1}}
t[9205]={{tags="route",text="For fishing the Plated Armorfish, try a small pond in Silithus north-east of Hive'Regal, at the base of a spire that mobs do not path over.",v=1}}
t[9206]={{tags="access",text="Turn in one Argent Dawn token to d00d at Light's Hope Chapel to receive a random Craftsman's Writ; this writ is not chosen by the player.",v=5}}
t[9209]={{tags="access",text="Requires Honored reputation with the Zandalar tribe before this quest can be received.",v=1}}
t[9229]={{tags="access",text="Complete the quest Echoes of War first; only then does the Light's Hope Chapel NPC offer this quest.",v=44},{tags="access",text="Gain Revered reputation with the Argent Dawn before this quest becomes available.",v=13}}
t[9232]={{tags="access",text="Complete the quest Echoes of War before this quest becomes available.",v=16},{tags="access",text="Be Revered with the Argent Dawn faction to access this quest.",v=16}}
t[9233]={{tags="inside",text="Omarion, who gives this quest, is trapped in a cage in the first room of trash in the Deathknight Wing inside Naxxramas.",v=14}}
t[9234]={{tags="access",text="Requires completing Omarion's Handbook first; Craftsman Wilhelm at Light's Hope Chapel in the Eastern Plaguelands gives this quest.",v=3},{tags="access",text="This quest is only available to Paladins and Warriors.",v=3}}
t[9235]={{tags="access",text="Pick up the quest from Craftsman Wilhelm at Light's Hope Chapel only after completing Omarion's Handbook, which requires freeing the caged Master Craftsman Omarion in Naxxramas.",v=1}}
t[9236]={{tags="access inside",text="Wilhelm offers this pattern quest only after you complete Omarion's Handbook, which requires freeing the caged Omarion in the first trash room of the Deathknight Wing in Naxxramas.",v=3}}
t[9237]={{tags="access",text="Pick this up from Craftsman Wilhelm only after completing Omarion's Handbook, which requires freeing Master Craftsman Omarion in Naxxramas.",v=2}}
t[9238]={{tags="access",text="Craftsman Wilhelm offers this quest only after you complete Omarion's Handbook, which Master Craftsman Omarion gives; skill 300 and enough reputation are also required.",v=4},{tags="inside",text="Omarion is caged in the first room of trash in the Deathknight Wing inside Naxxramas.",v=4}}
t[9239]={{tags="access",text="Pick up this quest from Craftsman Wilhelm at Light's Hope Chapel after completing Omarion's Handbook from Master Craftsman Omarion, who is caged in Naxxramas; you need 300 skill and enough reputation.",v=1}}
t[9240]={{tags="access",text="Craftsman Wilhelm at Light's Hope Chapel only offers it after you finish Omarion's Handbook, which Master Craftsman Omarion gives from his cage in Naxxramas.",v=3}}
t[9241]={{tags="access inside",text="Polar Bracers is only offered by Craftsman Wilhelm at Light's Hope Chapel after you complete Omarion's Handbook, which Master Craftsman Omarion gives from his cage in the first trash room of Naxxramas' Deathknight Wing.",v=3}}
t[9242]={{tags="access inside",text="Polar Gloves is picked up from Craftsman Wilhelm at Light's Hope Chapel only after finishing Omarion's Handbook from Master Craftsman Omarion, who is caged in Naxxramas.",v=1}}
t[9243]={{tags="access",text="Polar Tunic is only offered by Craftsman Wilhelm at Light's Hope Chapel after you complete Omarion's Handbook, and needs 300 skill plus enough Argent Dawn reputation.",v=1}}
t[9244]={{tags="access",text="Requires the Omarion's Handbook quest first, picked up from Master Craftsman Omarion in Naxxramas, plus 300 in Tailoring, Leatherworking or Blacksmithing.",v=2}}
t[9247]={{tags="spawn",text="Wait for the next invasion event to find the Keeper of the Rolls, who only appears in Light's Hope Chapel during it.",v=9}}
t[9248]={{tags="access",text="Revered reputation is required before you can summon the boss, even though the quest text suggests honored is enough.",v=1}}
t[9249]={{tags="spawn route",text="The Darkmoon Faire turn-in is only up during its monthly event; in December it was located directly south of Goldshire.",v=1}}
t[9251]={{tags="access",text="Naxxramas must be beaten before Atiesh can be obtained, so the quest is locked until then.",v=41}}
t[9259]={{tags="route",text="The Bloodsail Traitor who takes the silk and red dye is on a hill behind Booty Bay, near the Bloodsail pirates.",v=4},{tags="access",text="You must be hated (below neutral) with Booty Bay before this quest can be taken.",v=3}}
t[9260]={{tags="interact route",text="Step inside one of the red circles to investigate it; three are just outside the Stormwind gates and one is down the road.",v=5}}
t[9261]={{tags="route hidden",text="Follow the road down from the Ironforge gate; the circles are off the road on the right side, over its edge, after the bend.",v=36},{tags="interact",text="Step onto each of the two circles to investigate it; Skeletal Troopers and Spectral Spirits stand around the circles.",v=36},{tags="spawn",text="Mobs at the camp respawn after being killed, so wait for them to repopulate to get more stones.",v=1}}
t[9262]={{tags="interact",text="Step onto the lightning circle at the Darnassus entrance to investigate it; the circle is at about 37,55.",v=10},{tags="danger",text="Other aggressive mobs near the quest area can join in while you work, so watch for extra enemies.",v=10}}
t[9263]={{tags="route",text="The objective mobs are around the pig farm just outside Orgrimmar, to the right of the gates.",v=15},{tags="interact",text="Stand inside the pinkish circle near the pig farm to complete the objective.",v=15}}
t[9264]={{tags="route",text="Go back down the hill from Lieutenant Lisande to reach the Spectral Spirits that drop the Dim Necrotic Stones.",v=1}}
t[9265]={{tags="spawn route",text="Kill the purple-glowing Skeletal Soldiers and vapor demons outside the Undercity near the zeppelin tower; they are ported in from the floating necropolis.",v=40},{tags="spawn",text="These mobs appear only every so often, announced by a lightning bolt sound, so wait a few minutes if none are visible.",v=40},{tags="interact",text="Stand in the center of the large glowing purple circle with swirling text in Tiristral Glades to investigate it.",v=40}}
t[9266]={{tags="route",text="Bronn Fitzwrench, who gives this quest, stands at 60,40 in Winterspring just outside Everlook along the main road near a signpost.",v=2}}
t[9267]={{tags="access",text="The quest is only offered while your reputation with Ratchet is below neutral.",v=3}}
t[9272]={{tags="access",text="Reach neutral with the Bloodsail Pirates, then talk to Fleet Master Firallon for the uniform; you need friendly standing to start the hat quest.",v=1}}
t[9292]={{tags="spawn access interact",text="The shard spawns from the Pallid Horror corpse during a Scourge Invasion event; kill the corpse and loot it to see the quest mark.",v=16},{tags="spawn inside danger",text="In Stormwind the shard drops from an elite in the Cathedral of Light, which is announced by yell; it spawns inside the cathedral.",v=3},{tags="access",text="Horde players cannot complete this quest.",v=1}}
t[9299]={{tags="spawn",text="The Keeper who collects these notes has disappeared from Light's Hope Chapel and Eastern Plaguelands, and the Scourge invasion event has ended, so the quest can no longer be turned in.",v=17}}
t[9301]={{tags="spawn access",text="The turn-in NPC appears only during the Scourge invasion and disappears after the Scourge are defeated 150 times on the server, so the quest may no longer be turnable.",v=10},{tags="hidden",text="The turn-in NPC is a vendor up on the hill at Light's Hope Chapel and shows no quest marker; look for him there.",v=5}}
t[9302]={{tags="spawn access",text="The quest letter drops from a level 55 elite flameshocker that shows up in Undercity.",v=1},{tags="access",text="Do not abandon this quest, because the letter will no longer grant it once it is gone.",v=1}}
t[9304]={{tags="spawn",text="The Keeper of the Rolls disappears once your realm has defeated the Scourge 150 times, so this quest can no longer be turned in there.",v=5}}
t[9310]={{tags="floor inside",text="The crystal NPC stands on the ground floor at 66,21 in Undercity, not underground; he appears once you enter the city.",v=21},{tags="spawn access",text="The crystal only appears after a Scourge Invasion event, spawning on the Pallid Horror body in Stormwind or Undercity.",v=5},{tags="access",text="Alliance players cannot complete this quest, even if the shard spawns in Undercity.",v=5}}
t[9318]={{tags="access spawn",text="This quest was only offered during the Scourge Invasion event from Commander Thomas Helleran and is no longer available.",v=3}}
t[9319]={{tags="spawn route danger",text="Dire Maul: the Flame is on the north side, past Guard Slip'kik, behind the ogre area (near the Eye of Kilrogg); the Eyes respawn about 15 min after being killed.",v=101},{tags="inside route",text="Stratholme: the Flame is in Crusader Square, on the Scarlet side, by Timmy.",v=101},{tags="floor route",text="Blackrock Spire: the Flame is on the lower part, near the Ogre Tribute pile.",v=101}}
t[9322]={{tags="route",text="The Un'Goro flame is near the entrance to the land, at 70,76.",v=305},{tags="hidden route",text="The Azshara flame is up on the ridge, not in the pit of the Ruins of Eldarath; do not jump down into the ruins.",v=305},{tags="route",text="The Silithus flame is near Valor's Rest; when entering Silithus from Un'Goro, look to your right.",v=305}}
t[9323]={{tags="route",text="The Searing Gorge fire is outside the Blackrock Mountain gates, by the stairs before the BRM entrance.",v=253},{tags="route",text="The Eastern Plaguelands fire is on the west side of Corrin's Crossing, next to the town, not in Western Plaguelands.",v=90},{tags="route",text="The Hinterlands fire is at the fork in the road south of Skulk Rock.",v=69}}
t[9324]={{tags="interact",text="Interact with the bonfire in the Valley of Wisdom to take the Flame of Orgrimmar and start the quest.",v=5}}
t[9325]={{tags="interact route",text="Interact with the bonfire on The Spirit Rise to receive the Flame of Thunder Bluff item, which starts the quest.",v=3}}
t[9326]={{tags="inside route interact",text="Find the flame, a bonfire inside Terenas' Throne Room through the Ruins of Lordaeron, and interact with it to take the item that starts the quest.",v=2}}
t[9331]={{tags="inside",text="The flame is inside the Hall of Explorers in Ironforge, on the west side of the hall.",v=17}}
t[9332]={{tags="interact",text="Pick up the quest by clicking the flame in the opposing faction's city.",v=5}}
t[9337]={{tags="access",text="The quest is only available while the Scourge Invasion event is active.",v=3},{tags="spawn inside",text="Kill the undead near the Scourge Shards under the Necropoli, such as Bone Witch, Ghoul Berserker, Lumbering Horror, Skeletal Shocktrooper, Spectral Soldier, Spirit of the Damned, Flameshocker.",v=3}}
t[9339]={{tags="access",text="This quest only appears at the festival master after you turn in the flames from Orgrimmar, Thunder Bluff, and the Undercity.",v=3}}
t[9341]={{tags="access",text="Requires completing the quest Under the Shadow before this quest can be taken.",v=16}}
t[9343]={{tags="access",text="Complete the quest Under the Shadow before this quest becomes available.",v=7}}
t[9362]={{tags="inside",text="Warlord Krellian stands in the center of the Temple of Zin-Malor, inside the naga temple.",v=69},{tags="danger",text="A lower-level guard stands near Krellian inside the temple.",v=69},{tags="spawn",text="Spitelash nagas for the second objective are found at the base of the mountains, near Sanath's teleport point.",v=69}}
t[9364]={{tags="spawn",text="Spitelash naga, the polymorph targets, are found throughout the Ruins of Eldarath around 36,53.",v=16},{tags="access spawn",text="The quest is obtained after killing the Warlord in the area; Spitelash are abundant near where he dies.",v=15}}
t[9365]={{tags="access",text="This quest now also requires completing Stealing Silvermoon's Flame first.",v=4},{tags="access interact",text="Silvermoon's Bonfire, where the flame is stolen, is in the Court of the Sun.",v=4}}
t[9367]={{tags="inside",text="The Ironforge bonfire is inside the Hall of Explorers.",v=70},{tags="route",text="The Darnassus bonfire is in Rut'theran Village, between the flight master and the portal into the city.",v=70},{tags="route",text="The Stormwind bonfire is next to the Stockades entrance, just to the left of it.",v=12}}
t[9368]={{tags="route",text="The Thunder Bluff flame is on Spirit Rise, on the southeast side, at 21,26.",v=65},{tags="route",text="The Orgrimmar flame is in the Valley of Wisdom, at 40,33.",v=65},{tags="route",text="The Undercity flame is right at the entrance, at 66,36.",v=65}}
t[9386]={{tags="inside",text="Scholomance: the bonfire is in the corner of the classroom and is easy to spot once inside the room.",v=18},{tags="inside",text="Scarlet Monastery: the bonfire is on the Scarlet side at Crusader Square.",v=12},{tags="floor route",text="Hall of Destruction: the bonfire is on the upper level, by the ramp.",v=12}}
t[9388]={{tags="",text="Light the bonfire at 64,71 in Ashenvale, by the bridge north of the battleground entrance.",v=13},{tags="",text="Light the bonfire at 41,90 in Darkshore, on the road just before crossing into Ashenvale.",v=13},{tags="",text="Light the bonfire at 59,72 in Stonetalon, at the crossroad before Windshear Crag.",v=13}}
t[9389]={{tags="route",text="Stand on the cliff overlooking the beach southwest of Moonbrook, near the lighthouse, to find the Westfall fire.",v=88},{tags="route",text="Take the ramp into the ruined guard tower east of the road between Southshore and Tarren Mill to find the Hillsbrad fire.",v=88},{tags="route",text="Stand on the east side of the road just south of the Thandol Span bridge to find the Wetlands fire.",v=88}}
t[9415]={{tags="route",text="Marshal Bluewall's camp is on the northeast edge of Hive'Zora. Head southwest from Cenarion Hold to reach it, not the Alliance symbol on Alla's map.",v=2}}
t[9416]={{tags="route",text="Turn the red glow in at the big red transporter icon on the map, not at Cenarion Hold or Bronzebeard Encampment.",v=60},{tags="access",text="Pick up the red glow at any geyser in Silithus; this quest's item is obtained there.",v=10},{tags="interact",text="Do not mount while carrying the red glow, because mounting makes you lose it.",v=10}}
t[9419]={{tags="interact",text="Step into the machine at 32,50 in the Hive'Zora camp to turn in the geyser.",v=53},{tags="spawn hidden",text="Geysers spawn at random places around Silithus, not at fixed points; look for small glowing dirt piles or smoking red rocks.",v=39},{tags="interact",text="Right-click the geyser to collect it; it cannot be carried while mounted or stealthed.",v=35}}
t[9422]={{tags="interact",text="Right-click a Silithyst Geyser to collect it; they look like glowing dirt piles that periodically spout into the air.",v=65},{tags="danger",text="Collecting a geyser flags you for PvP, so Alliance players can attack you.",v=65},{tags="interact route",text="Turn in the Silithyst by stepping into the gnomish machine at the Horde camp near Zora.",v=65}}
t[9664]={{tags="interact",text="Being stealthed stops the capture timer and gives no quest credit, so you must be visible.",v=104},{tags="inside interact",text="Stay inside the tower while PvP-flagged with /pvp; the capture progress bar only advances while you wait there.",v=31},{tags="access",text="After you capture a tower, a spectral griffon master appears nearby and can fly you to another tower.",v=31}}
t[9665]={{tags="inside interact",text="Stand inside the tower, or very close to it, and wait until the capture bar shows the tower as captured.",v=40},{tags="interact",text="Turn on PvP flagging before going to the tower; on a PvP-disabled server the capture does not work without it.",v=40},{tags="interact",text="Do not stealth or vanish while capturing; stealth stops the capture progress and no credit is given.",v=9}}
t[78124]={{tags="route floor",text="Go down the stairs at the Ruins of Mathystra in Darkshore, far to the north of the zone.",v=1}}
t[78142]={{tags="floor route",text="Take the portal at the top of the mage tower to reach the book turn-in location.",v=1},{tags="inside hidden",text="The red book is on the bottom shelf of a bookcase in the first hut on the left as you enter Moonbrook.",v=1}}
t[78145]={{tags="floor inside",text="The control room is at the top of the oil rig in The Sludge Fen.",v=1}}
t[78147]={{tags="inside",text="The Spellbook is in the last room of the Dawning Wood Catacombs, in the western building.",v=1}}
t[78148]={{tags="inside route",text="Enter the Mo'grosh Stronghold ogre cave in the far north-east of Loch Modan and keep to your left as you walk in.",v=1}}
t[78149]={{tags="inside hidden",text="Look on top of a small barrel inside a tent at Grimtotem Post, in the far south-east corner of Stonetalon Mountains.",v=1}}
t[78150]={{tags="inside hidden",text="Find the Rumi of Gnomeregan book on or behind the innkeeper's table inside the Sentinel Hill inn.",v=1},{tags="inside route",text="Find the Bewitchments and Glamours book on a bookshelf in the first house on the left when entering Moonbrook.",v=1},{tags="inside floor",text="Find Archmage Theocritus's Research Journal on a table partway up inside the Tower of Azora.",v=1}}
t[79092]={{tags="inside",text="The book can be picked up at the Tower of Azora in Elwynn Forest before accepting the quest.",v=1},{tags="floor route interact",text="Climb partway up the Tower of Azora in Elwynn Forest, then continue up to click the Eye of Azora.",v=1}}
t[79093]={{tags="inside",text="The book can be picked up inside the Thelsamar inn in Loch Modan, next to the trade goods vendor Drac Roughcut.",v=1}}
t[79095]={{tags="inside",text="The book sits on a shelf inside Brill's Apothecary building, next to Apothecary Johaan (Horde characters).",v=1}}
t[79947]={{tags="inside",text="The scroll is inside a hut on Darkcloud Pinnacle mesa in the Thousand Needles.",v=1}}
t[79951]={{tags="inside route",text="The objective is inside a crypt in the centre of the Badlands; approach via the path to the south, with a tall mesa to the north.",v=1}}
t[79952]={{tags="route",text="The Waterlogged Book lies discarded on the ground on the eastern side of the Witch Hill murloc camp in north-east Dustwallow Marsh.",v=1}}
t[79975]={{tags="route",text="To start the quest, jump up the destroyed wagon, then climb the wall between Hillsbrad and Arathi.",v=1}}
t[81947]={{tags="floor inside hidden",text="The uppermost walkway of the Temple in the Swamp of Sorrows is where the discarded item lies in plain view; go to the top walkway.",v=1}}
t[81949]={{tags="inside",text="The quest object is in a bookshelf inside the middle pirate building at Pirate Cove in Tanaris.",v=1}}
t[81952]={{tags="route",text="The objective is on a crate in Haldarr Encampment, in the far west of Azshara near Ashenvale.",v=1}}
t[81953]={{tags="inside",text="The quest is in Franclorn Forgewright's altar room, inside Blackrock Mountain, next to Lothos Riftwaker.",v=1}}
t[81955]={{tags="inside",text="The book lies on a table inside a tent near the centre of Searing Gorge.",v=1}}
t[84396]={{tags="route inside",text="The scroll is on the pavilion far below Lothos Riftwaker, a bit past Franclorn Forgewright's altar room, just near the opening into the cavern.",v=1}}
t[84402]={{tags="hidden inside route floor",text="The book is on a table in a nook near Blood of Heroes in Scholomance Castle, zone side; enter, go right, then up the stairs and up the ramp. Do not enter the instance.",v=1}}
t[86614]={{tags="hidden route",text="The quest starts from a wrecked wooden boat at the bottom of the lake, toward the southern end, underwater.",v=2}}
t[86757]={{tags="spawn",text="Grunts share spawns with shamans in the small area east of Fallen Sky Lake; clearing the shamans respawns more grunts.",v=1}}
t[86784]={{tags="hidden",text="The sticks blend into the ground texture near tree clusters; hover over the ground and look for the gear cursor.",v=1},{tags="spawn",text="Three sticks lie around the tree cluster here, and each respawns about 30 seconds after it is taken.",v=1}}
t[87491]={{tags="danger",text="Halfway out of the camp the escorted NPC suddenly attacks you, and it is fairly strong while escorted.",v=3}}
t[88756]={{tags="danger",text="Small kegs lie in the elite dwarf camps, so expect elites nearby.",v=1},{tags="hidden",text="The small kegs are hard to spot because they don't sparkle.",v=1},{tags="interact",text="Picking up a small keg takes a couple of seconds, so stay in place until it is collected.",v=1}}
t[88757]={{tags="floor",text="The waterskin is on the lower floor, quite close to the questgiver.",v=1},{tags="floor",text="The necklace and spellbook are on the upper floor.",v=1}}
t[91733]={{tags="route",text="The saw lies by the big rock and river plants, downstream from the bridge.",v=11},{tags="route",text="The axe lies on the island where the river splits.",v=11},{tags="hidden route",text="The toolbox is underwater in the big river between Elwynn Forest and Duskwood, at the boat.",v=11}}
t[91736]={{tags="route",text="The path to the Applejack Still starts at 28, 59 and requires some climbing to reach.",v=1}}
t[91861]={{tags="floor inside",text="The Blood Elf is caged in the basement of Fenris Isle Castle; he gives the quest to kill Gnolls for the key.",v=1}}
t[92401]={{tags="route",text="She kneels in the graveyard at The Sepulcher, outside Undercity. Leave Undercity and follow the left path down.",v=1}}
t[92415]={{tags="inside",text="The Blood-Stained Letter is found deep inside the Dungeon Ruins of Lordaeron in Undercity, at the graveyard, held by one of the bosses.",v=1}}
t[92434]={{tags="access",text="Complete all of Magus Wordeen Voidglare's other quests before this quest can be started.",v=4}}
t[92456]={{tags="hidden inside",text="The night elf herbalist is in a slightly hidden shop in the northwest part of the park.",v=3}}
t[92457]={{tags="spawn",text="Remnant counts vary between runs, so a single run may not have enough to complete the quest.",v=5},{tags="access inside",text="Pick up the breadcrumb quest An Alarming Request first, from Emissary Jacques inside the Southshore Town Hall; without it, the quest does not unlock.",v=1},{tags="hidden",text="Some Remnants lie off the main path, hidden in corners of the dungeon.",v=1}}
t[92458]={{tags="access",text="As Alliance, you must pick up the breadcrumb quest An Alarming Request first, or she only says Dalaran is closed.",v=3}}
t[92461]={{tags="route",text="Go northeast of the questgivers, near Thendal Village, to find Juvenile Vuldren; that area is less crowded than the questgiver spot on launch day.",v=3}}
t[92470]={{tags="inside",text="The quest takes place inside a cave, which is the old Dun Morogh cave model flipped over to the left.",v=1}}
t[92519]={{tags="interact",text="The box needed for this quest sits in front of a house in Aratchi Highlands.",v=1}}
t[92528]={{tags="floor inside hidden interact",text="Upstairs in the top-floor house, look for the sparkles on the floor and click the brown wardrobe to hide inside and overhear the conversation.",v=1}}
t[92544]={{tags="spawn danger",text="Malduko respawns instantly in his current state, so pulling him away matters.",v=1}}
t[92643]={{tags="inside",text="The Dead Cultist you need is inside the house at this spot.",v=1},{tags="danger",text="The area is swarming with level 9 mobs.",v=1}}
