t[92914]={{tags="danger route",text="The east pylon at 73,23 sits behind a group of mobs and is guarded by arcane elemental pylon protectors.",v=1},{tags="inside",text="The south pylon is inside the center of the main Shen'dralas building.",v=1}}
t[93128]={{tags="access",text="Complete the Nerlokh quest chain in the Valley of Bones first; Uthek gives it after you bring her the shard of Ongeku.",v=1}}
t[93176]={{tags="route",text="Find the Arbor Tarantula at the STV Logging Camp, around 45.5, 19.6.",v=3},{tags="route",text="Find the Hay Weevil at the Arathi Highlands Farms, around 32.4, 28.5.",v=3},{tags="route",text="Find the Flesh Picker at the Desolace Kodo Graveyard, around 53.3, 58.3.",v=3}}
t[93196]={{tags="access",text="Requires level 35 to be offered; the quest is unavailable below that level.",v=5},{tags="access",text="Requires honored Magram reputation to progress; the questline begins with Magram Alliance from Gurda Wildmane at Ghost Walker post.",v=1}}
t[93227]={{tags="access",text="This quest only unlocks after you complete the Carved Centaur Totems quest first.",v=1}}
t[93404]={{tags="interact",text="Talk to the tree NPC just east of the quest giver to continue this quest.",v=1}}
t[93450]={{tags="interact",text="Die while carrying the quest item, then release spirit to complete the quest step.",v=2},{tags="access",text="Activate all three pylons before you can talk to the quest NPC.",v=1},{tags="access route",text="The western pylon is at the eastern end of the Valley of Bones.",v=1}}
