t[93546]={{tags="hidden",text="The ore is scattered around the main temple and does not show on the minimap; look at the stone hillsides.",v=1}}
t[93552]={{tags="spawn",text="Windstones most commonly spawn along the mountain ridges and the village ridges along the stone walls.",v=3}}
t[93663]={{tags="interact",text="Right-click the Mangled Corpse at 30.0, 54.3 in the Swamp of Sorrows to loot the Courier's Shipment; it is picked up instantly.",v=1}}
