t[93737]={{tags="route",text="Enchanted Gyrozephyr lies at the bottom of Windsong Lake, above Falaath Village; you must swim down to reach it.",v=3},{tags="inside",text="Crystallized Lightning is along the cave walls as you run through the cave.",v=3},{tags="",text="Air Construct Core is on the left of the road above Windfield Orchard when walking toward the Shen'dar Highlands.",v=3}}
t[93746]={{tags="access spawn route",text="Change layer by getting a group invite from a player found via /who whisper, then start the encounter once the girl disappears.",v=1}}
t[93788]={{tags="spawn",text="Lumberjack mobs in the area are sparse and spread over a wide region; expect few spawns to find.",v=1}}
t[93797]={{tags="interact",text="Pick up the bough lying on the ground at these coordinates to complete the quest.",v=3}}
t[93949]={{tags="spawn",text="Look for the skyhoppers near places where people listen, such as the tower or the inn; they do not spawn at random.",v=1}}
t[94374]={{tags="route",text="Head up the snowy hill to its top at 26.4/68.0, then turn left at the small camp stone; the target is in the distance.",v=1}}
t[94449]={{tags="route",text="Follow the trail to the quest turn-in; it starts at 86.5, 47.2.",v=1}}
t[94465]={{tags="route",text="The trail starts at 31.4/58.2; follow the eyebrow cliff trail past the stone totems.",v=1}}
t[94483]={{tags="spawn",text="Priests needed for this quest spawn rarely, but there are two camps where they appear.",v=1}}
t[94485]={{tags="hidden",text="The moss needed for this quest hangs from the sides of trees in the area, so look up rather than at the floor.",v=1}}
t[94489]={{tags="interact",text="When healing the druids, stand close to each one before right-clicking and avoid spam-clicking, since rapid clicks can leave one druid unhealed.",v=6}}
t[94556]={{tags="patrol danger",text="Jom-jom may stop outside Bolder'ok and not move again; kill any mob that aggroed outside the cave to make him resume walking.",v=1},{tags="spawn danger",text="Packs of 3, 2, then 3 mobs spawn on the road outside the cave during the escort.",v=1}}
t[94638]={{tags="route",text="From Valanaar, take the path west instead of north to reach the upper mountainface where the quest spot is, not the foggy cave.",v=1},{tags="route inside",text="Cross the river by the wooden log bridge; Ur'Endra is inside the cave at the edge of the cliff.",v=1}}
t[94679]={{tags="inside",text="Find the target in a cave in Riverglades around 16.5, 72.7.",v=1},{tags="danger",text="The target is an elite with 2 Redridge Mystics standing beside it.",v=1}}
