t[94821]={{tags="route inside",text="For gnomes, the quest NPC is a priest trainer in the Mystic Ward of Ironforge, not in Stormwind as the quest text says.",v=1}}
t[94842]={{tags="route interact",text="Fresh manure is not at Wheeler's Grange; look for a house on the west side of the river near the murlocs and click the small piles there.",v=1}}
t[94873]={{tags="access",text="Quest is unlocked only after completing Carved Centaur Totems (quest 93225); you can reach friendly before collecting all 5 totems.",v=1}}
t[94897]={{tags="route",text="The Resaan's heirloom is on a corpse outside a ruined building in the northwest of the quest area.",v=2}}
t[94923]={{tags="route",text="The large clam to loot is on the river island west of Wheeler's Grange.",v=1}}
t[94974]={{tags="inside",text="The Blacksmith ogre that drops the Key Moulding is in the north-eastern part of the dungeon, in the kennel area with War Handler Ashka.",v=1}}
