t[95034]={{tags="interact",text="Right-click the NPC and click through her messages to complete The Debt.",v=1}}
t[95126]={{tags="floor inside access",text="Turn in the sword in the basement of Sepulcher; the NPC there opens the next quest, which is given by Lumina beside him.",v=1}}
t[95140]={{tags="patrol",text="Old Fire-Eye, a level 25 elite, walks around the 48.84 area.",v=1},{tags="interact",text="Old Fire-Eye has a deep purple shield aura; the first auto attack that lands with the Moonsilver Blade drops it.",v=1}}
t[95161]={{tags="inside",text="The Blood-Stained Letter lies deep inside the Dungeon Ruins of Lordaeron in the Undercity, at the graveyard near one of the bosses.",v=2}}
