t[95427]={{tags="inside route",text="The boss is at the far end of the cave used in the previous quest.",v=1},{tags="spawn",text="Cave respawns will have returned, so expect the mobs inside to be back up.",v=1}}
t[95534]={{tags="access",text="Casters in town drop the note that starts this quest.",v=10},{tags="interact",text="Hit both outside bellows with fire damage, such as a flamestrike, fire trap, or Rain of Fire, to summon the fire elemental.",v=10},{tags="spawn",text="The fire elemental spawns after the fire hit; stand where it lands, because running away makes it despawn.",v=3}}
t[95561]={{tags="spawn",text="Apples spawn around the base of the apple trees in Farholde keep.",v=1},{tags="interact",text="Rotten apples on the trees cannot be picked up; do not target them.",v=1}}
t[95646]={{tags="access",text="First Mate Fitzsimmons only offers this quest after you finish the Greenwarden quests: The Greenwarden, Tramping Paws, Fire Taboo, and Blisters on the Land.",v=18}}
t[95663]={{tags="route",text="Turn off near Thelgen Rock by the meeting stone and walk up the new path uphill to the hills above the Dragonmaw camp, where the Deathstalker Agent waits.",v=1}}
t[95682]={{tags="access",text="Complete the quest Dragonmaw Rumors first; Open the Maw is not available until it is finished.",v=4},{tags="access route",text="Get the prerequisite quest from the orc at the bottom of the stairs in Hammerfall before heading to the dungeon.",v=4}}
t[95770]={{tags="access",text="Complete The Vile Reef, then The Gurubashi Legends of Old, before this quest becomes available.",v=1}}
t[95772]={{tags="inside route",text="The quest NPC is in the stables, on the left side after crossing the bridge from the flight master.",v=1}}
t[95773]={{tags="access",text="Complete The Vile Reef and The Gurubashi Legends of Old first; the quest is not available until both are finished.",v=1}}
t[95775]={{tags="access",text="Complete The Vile Reef, The Gurubashi Legends of Old, and Locating the Lost City first; this quest is unavailable until then.",v=2}}
t[95776]={{tags="access",text="Requires delivering the quest Enemies in the Water first; it is part of a questchain that begins with The Vile Reef.",v=1},{tags="access",text="Requires completing the quest Locating the Lost City first.",v=1}}
t[95787]={{tags="access",text="Requires prerequisite quest 95786 first; it starts with Medicine Man and its breadcrumb comes after the Skullsplitter Fetish quest, sending you to Southshore.",v=1},{tags="route",text="The first objective item is after the first boss, down the left path.",v=1},{tags="hidden inside",text="The second objective item is in the pirate area, half inside a skull, so it is hidden.",v=1}}
t[95788]={{tags="access",text="Complete the quest Troll Witchery first; this quest becomes available after turning it in.",v=3}}
t[95955]={{tags="interact",text="You do not need to kill the crocolisk; hit it, disengage, and hit the same crocolisk again to get credit.",v=1}}
t[95992]={{tags="patrol",text="Ghostmaw patrols along the full river; one player found it at 54,70.",v=2}}
t[95998]={{tags="interact",text="Sit at the campfire for about a minute to receive the Boosted Rest buff.",v=1}}
t[96204]={{tags="interact access",text="Opening the cage starts the escort, which is a gauntlet, so the NPC must be kept alive while she walks out.",v=1},{tags="patrol route",text="She walks out of the keep through the courtyard to the castle entrance, then runs to the dock; she then returns to the Sepulcher on her own.",v=1}}
t[96241]={{tags="interact",text="Use the quest item on the dead tauren bodies on the ground around the quest area to extract toxin samples; some revive as active mobs, and you can still use the item on them.",v=6}}
t[96261]={{tags="access",text="Complete the quest Defending the Dead first; The Broodmother does not appear until it is done.",v=7}}
t[96391]={{tags="access",text="This quest is not given by an NPC; it starts from the Dark Iron Map dropped by the Dark Iron Spy in Dun Morogh.",v=4}}
t[96393]={{tags="access",text="This quest starts only after looting the Dark Iron Map, which drops from dark iron dwarves in southeast Dun Morogh; hand it to Earthseer Farsen.",v=6}}
t[96395]={{tags="inside",text="Start and finish this quest inside the dungeon.",v=4}}
t[96608]={{tags="interact",text="If the Boosted Rest buff does not trigger while sitting in the camp, relog and sit down again to get the objective to complete.",v=1}}
t[96630]={{tags="floor interact",text="The quest starts from a book on a table behind Tenaron Stormgrip at the top of Aldrassil in Shadowglen.",v=1}}
t[96771]={{tags="route",text="Going up the ramp to Nar'gurk, turn right to find the quest objective nearby.",v=1}}
