t[96781]={{tags="inside",text="He is inside a house in Strahnbrad in Alterac Valley, at 63,44.",v=4},{tags="danger",text="Other stealthed mobs are around him, so be careful when approaching.",v=4}}
t[96782]={{tags="inside",text="The shield lies inside the tower at 41.35, 40.16.",v=1},{tags="inside danger",text="The sword lies inside the tower at 38.5, 58, surrounded by elites.",v=1}}
t[96784]={{tags="route",text="Anastasia Miller stands on a ledge outside the castle; jump onto the house beside the ledge and parkour up to her.",v=1},{tags="access",text="The quest and its footlocker only appear once you are friendly with Ravenholdt.",v=1},{tags="access",text="Complete the quest A Way In first; it is required before this quest becomes available.",v=1}}
t[96785]={{tags="floor inside",text="Anastasia's Stash is on the second floor of a house near the keep; go upstairs to find it.",v=1}}
t[96786]={{tags="danger",text="A box in Arathi Highlands is guarded by two NPCs standing right at the spot.",v=3}}
t[96800]={{tags="inside",text="The quest item lies on a table on the right side of the last boss room in the Scarlet Monastery Library.",v=3}}
