t[97003]={{tags="inside",text="The cave entrance is at 58, 25 in The Barrens; go inside to reach the cavern.",v=3},{tags="danger",text="The cavern is filled with level 18 and higher elites.",v=3}}
t[97005]={{tags="inside route",text="The cave entrance is at 58, 25 in The Barrens.",v=3},{tags="danger inside",text="The cavern is filled with level 18 and higher elites.",v=3}}
t[97237]={{tags="inside",text="Cycles of Morality, a black book, is on the table in the north corner of the room.",v=1},{tags="inside",text="Trollbane Conquests, a green book, is on the first row of bookshelves on the entrance side.",v=1},{tags="inside",text="The Forsaken Ally, a red book, is on the second row of bookshelves on the entrance side.",v=1}}
t[97277]={{tags="route",text="Take the faint snowy trail up the mountain on the right side of the road left of Anvilmar's front door, past the first tree, then over the ridge to the camp.",v=1}}
t[97289]={{tags="floor inside route",text="Go to the next room off the same level where you picked up the quest; a hanging corpse there is the one to turn in.",v=1}}
t[97292]={{tags="floor route",text="The big pink worm is outside the room upstairs; exit the room to the right and he is huge, next to the path.",v=4},{tags="interact",text="Click the Hissing Serum in your inventory to use it; clicking the worm does not work.",v=2},{tags="access",text="You must first receive the Hissing Serum before you can administer it to the worm.",v=1}}
t[97329]={{tags="hidden inside",text="Zimmix is in a cage in a corner of one of the open rooms in Ruins of Zul'kunda.",v=1},{tags="access",text="This quest only becomes available after someone else first picks up the escort quest, so wait for that.",v=1}}
t[97485]={{tags="access",text="Nida, Nata, Mahu and Naal sell their quest components only while the quest is active; buy them there.",v=5},{tags="interact",text="Spread the Prepared Incense at the ceremonial site on the south-facing cliff of Hunter Rise, where the mat and incense burner are.",v=5}}
t[97617]={{tags="inside hidden",text="The helm is inside a crate in a tent in the digsite directly south of the questgiver.",v=1}}
t[97985]={{tags="spawn",text="Go to the spawn point at 57, 55, where the quest entity appears.",v=5}}
t[98027]={{tags="hidden",text="The quest item is a very small white object in the river at 63, 71.5; look for its large exclamation mark on the minimap.",v=1}}
t[98059]={{tags="spawn access",text="Magistrate Burnside must be alive and standing next to the table; if the Horde killed him, wait for him to respawn.",v=7},{tags="interact",text="As a gnome, stand on the chair next to the table to make the quest work; jump carefully onto the chair.",v=5}}
t[98070]={{tags="inside route",text="The cave entrance, where the mobs for this quest are found, is at 27.5, 49.5 in Thousand Needles.",v=1},{tags="spawn danger",text="Mob spawns inside the cave are very fast, and several can gather on you at once.",v=1}}
t[98071]={{tags="floor interact",text="Go down to the bottom floor, then use the quest item on the sack and loot it.",v=6},{tags="route",text="Stand at the fireplace and turn around; the sack is between the two staircases.",v=1},{tags="route",text="On entering, skip the middle staircase that goes up; go left, then down the stairs.",v=1}}
t[98155]={{tags="interact",text="Loot the pelts only from Pesterhide Snarlers, not Pesterhide Hyenas, even though the quest description mentions hyenas.",v=1}}
end)()
;(function() local t = C.q
t[98209]={{tags="route",text="From Menethil Harbor, take the boat docked to your right at the dock; talk to Don Pompa there to confirm its destination.",v=1}}
t[98216]={{tags="route",text="From Whelgar's cave exit, turn left and climb the hill past the tree, then leap off the ledge edge near Sarltooth onto the ledge where Goaz Warder stands.",v=1}}
t[98223]={{tags="access",text="The book that starts this quest, next to Chieftain Nek'rosh, can only be interacted with while you are on the quest Defeat Nek'rosh.",v=1}}
t[98230]={{tags="access",text="Complete Razormaw Needling and Trying Times first; both must be marked completed before this quest can continue.",v=3}}
t[98283]={{tags="inside route",text="The cave entrance is at 69.5, 34.7; go inside the cave there.",v=6}}
t[98291]={{tags="access",text="Complete Old Habits (picked up from the book next to Chieftain Nek'rosh), Razormaw Needling, Trying Times, and This Land Was Their Land before this quest can be continued.",v=1}}
t[98297]={{tags="access",text="Requires the prerequisite quest chain first, ending with Death to the Dragonmaw.",v=8},{tags="spawn",text="The spawn to kill appears at 76,7 or at 45,5.",v=4}}
t[98300]={{tags="access",text="Complete the Stopping the Cycle chain first: Old Habits, Razormaw Needling, Trying Times, This Land Was Their Land, Death to the Dragonmaw, and Stopping the Cycle.",v=2}}
t[98310]={{tags="interact",text="Use the Goaz Stone on each golem to wake it up before killing and looting it.",v=1},{tags="danger hidden",text="Ados is surrounded by elite orcs, and a stealthed elite orc rogue joins the pull; clear a path to him.",v=1}}
t[98319]={{tags="inside route",text="The Grizzled Den Cave entrance is at 42.5, 54.4. Cornelius is in the star-shaped room to the right after you enter.",v=10},{tags="inside danger",text="Cornelius lies in the middle of a frozen pond in the star-shaped room, surrounded by wendigos.",v=10},{tags="inside danger",text="Wendigos stand around the frozen pond in the Grizzled Den Cave at this spot.",v=5}}
t[98326]={{tags="inside",text="Go to the end of the Wendigo cave directly west of Kharanos; he is inside at the far end.",v=5}}
t[98372]={{tags="spawn",text="The torch spawn moves between several points, including near Raven Hill and the south edge of Duskwood; check the listed spots.",v=6},{tags="inside spawn",text="One torch spawn is inside Raven Hill Cemetery, so check inside the cemetery.",v=1}}
t[98417]={{tags="hidden",text="The quest scroll is small and wrapped in Entangling Roots, so it is hard to spot.",v=1}}
t[98418]={{tags="spawn",text="Xavian Betrayers spawn at an extremely low rate, sharing the camp with other mobs, so expect a very long farm to get the five needed.",v=5}}
t[98815]={{tags="access",text="Complete Young Crocolisk Skin from James Halloran in Menethil Harbor first; this quest unlocks after that.",v=12},{tags="inside",text="You can finish this quest inside the Excavation Site, though there is no portal icon.",v=12}}
t[98823]={{tags="route",text="The path up to the plateau starts at 39.7, 16.9.",v=27},{tags="access",text="If you hold this quest without the titan disk, abandon it and retake it from Bashana; the quest then gives the disk.",v=14},{tags="inside",text="Muln Earthfury, who takes the turn-in, is inside the large tent at 33.4, 22.6.",v=1}}
t[98824]={{tags="access inside",text="Kill the boss inside the excavation dungeon for the correct Titan Relic, then turn that relic in at the digsite to unlock the Ironforge quest; the Elite's relic at the digsite is the wrong one.",v=1}}
t[99127]={{tags="spawn hidden",text="The nets spawn in the shallow water along the lake shores and are hard to see.",v=1}}
t[99152]={{tags="inside route",text="The entrance to the underground catacomb is inside a burned house at 13,65; kill the skeletons and zombies there to get the items.",v=1}}
t[99153]={{tags="inside route",text="The entrance to the underground catacomb is inside a burned house; go there to descend.",v=1},{tags="inside hidden",text="The crystal lies in the ground in the left zone of the catacomb.",v=1}}
t[99162]={{tags="hidden route",text="Coldbeard's gun lies beside a fallen dwarf under a tree that has fallen across the frozen river, west of the quest giver.",v=1},{tags="route",text="Sunhammer's gun lies beside a cart on the small path up to Vagash's cave, southeast of the quest giver.",v=1},{tags="route",text="Stoneanvil's gun lies beside a cart in the open valley, almost straight south of the quest giver.",v=1}}
t[99411]={{tags="patrol",text="Kyle the Frenzied runs in a large counterclockwise circle around Bloodhoof Village; track him as he moves.",v=5},{tags="interact",text="Get close to Kyle and use Tender Strider Meat on him; he eats it and the quest completes.",v=5}}
end)()
;(function() local t = C.i
t[737]={{tags="interact danger route",text="Stand in front of the fountain and right-click the water; you do not need to enter the fountain, as entering it can get you stuck.",v=45},{tags="route danger",text="The naga spring can be reached by going around the cape with the naga, then taking the palm-marked path up the hill past the stone marker, not the bridge.",v=8},{tags="route",text="The water is at Cosmos location 28,62 in Stranglethorn Vale; click on the spring to get the item.",v=6}}
t[738]={{tags="hidden",text="The sack is hard to spot and sits beside a large bubbling cauldron in the camp next to Ongeka, at 62,23.",v=19}}
t[739]={{tags="hidden",text="Look for the camp with the huge raging bonfire; the sack is light green and almost flat on the ground, very hard to see.",v=22},{tags="danger",text="Mages, a warlock and sword-wielding enemies guard the camp where the sack sits.",v=22},{tags="spawn route",text="It is a static spawn point at the end of WaveStrider Beach nearer LostRigger Cove, in one of the camps.",v=7}}
t[740]={{tags="route",text="Enter Shadra'Alor through the main entrance, then take a left up the hill past a stone head half buried in the ground.",v=6},{tags="danger",text="Four trolls stand around the hut, and the sack lies in front of the hut, so it sits among them.",v=6},{tags="hidden",text="The sack is tucked away in the hills, just to the left of the hut's entrance.",v=1}}
t[743]={{tags="route",text="Reach the cliff by going west from the Badlands entrance to the first digsite with dwarves, then head north toward the Cauldron cliff.",v=24},{tags="hidden",text="The burning tree is hard to spot; it is bent over beside a rock on the cliff, so search around the rock.",v=24},{tags="interact",text="Right-click the big burning tree near 54,51 in Searing Gorge; it is the only tree that works.",v=24}}
t[841]={{tags="route inside",text="Stand right outside the left side of the farmhouse to get the watch out without going inside.",v=3}}
t[889]={{tags="floor inside",text="Look inside the town hall-looking building on the floor next to the stairs in the back.",v=25}}
t[910]={{tags="floor inside",text="Upstairs in the Goldshire inn, in the room with two single beds, the letter is in a chest between the beds.",v=8},{tags="danger route",text="Looking into the crate at the end of the canal, across the bridge from Mage to Park district, releases a level 25 spirit.",v=2}}
t[1206]={{tags="spawn",text="Moss Agate drops from Tin and Silver veins; mine those for it, not copper veins.",v=9},{tags="inside access interact",text="Use the Sparklematic 5200 in Gnomeregan to exchange grime-encrusted items for materials, including Moss Agate.",v=2},{tags="interact",text="Blueleaf tuber quest gembox in Ragefire Chasm (RFK) contains one of each gem.",v=2}}
t[1221]={{tags="access",text="The scale drops only while you carry the related quest.",v=1}}
t[1262]={{tags="access",text="Bring at least 5 Hops first; Grimbooze Thunderbrew will not give the keg without them. Harvest Watchers and other harvest mechanicals in Westfall drop Hops.",v=45},{tags="route",text="Reach him by the path between the hills south of Moonbrook, entering from the east entrance.",v=10}}
t[1274]={{tags="access",text="Carry at least 5 Hops to the Thunderbrew quest; the quest needs them.",v=14},{tags="route",text="Reach Grimbooze Thunderbrew by the hill path south of Moonbrook, entering at 52,72, or from behind the forge and silo at 44.62,74.16.",v=14}}
t[1349]={{tags="hidden",text="The crate lies outside the Ogre's Cave entrance on the right side, partly hidden behind a log, in the Vul'Gol Ogre Compound.",v=18}}
t[1381]={{tags="spawn",text="The Defias Messenger spawns in Moonbrook in front of the Blacksmith shop, and is often killed there before reaching the Gold Coast Quarry path.",v=19},{tags="spawn patrol route",text="Wait under a tree at the end of the road from Gold Coast Quarry toward Moonbrook; a new messenger spawns about every 3 minutes and walks toward you.",v=11}}
t[1467]={{tags="access",text="Spotted Sunfish can only be fished from Lake Everstill in Redridge if you have the quest Selling Fish.",v=22}}
t[1532]={{tags="access",text="Heads drop from Bloodscalp Headhunters only while you have the related quest active.",v=18}}
t[1875]={{tags="inside route",text="Found in the public area of the Deadmines; go all the way in to find the undead Foreman who drops it.",v=32}}
t[1894]={{tags="inside",text="The mobs that drop this card are outside the instance, in the south part of the cave.",v=1}}
t[1922]={{tags="route",text="Reach Sven faster by going east from Sentinel Hill and swimming across the river; he is in the northwest corner of Duskwood.",v=15}}
t[1941]={{tags="inside route",text="The Gallina Winery vendor is inside the winery on the canal side behind the inn; reach it through the tunnel to the rear of the Inn, near the Gilded Rose and the bank.",v=36}}
t[1942]={{tags="inside",text="Buy it from Hanns the bartender inside the Scarlet Raven Tavern in Darkshire; the tavern is at 74,45.",v=30}}
t[1946]={{tags="patrol inside",text="The Insane Ghoul that drops this item patrols around 80,70, and the spot is inside a building.",v=1}}
t[1956]={{tags="access",text="The faded pendant only appears after you accept the quest that turns the glowing shadowhide pendant into it.",v=4}}
t[1968]={{tags="patrol inside",text="The ogre patrols inside the cave; if he is not at 36,83, search around the cave, where he was found in the middle.",v=3}}
t[2005]={{tags="inside hidden",text="Find the first tablet in the north-west corner of the Bal'lal Ruins, by the water, at about 29,19 (or 29,20).",v=22}}
t[2006]={{tags="hidden route",text="The tablet to take lies outside the sunken city's perimeter wall, near the north-eastern corner; swim down on the outside of the wall.",v=30},{tags="inside danger",text="A second copy of the tablet lies inside the wall, guarded by elite murlocks near the glowing altar; skip it.",v=30}}
t[2007]={{tags="inside route",text="The tablet is inside the Zul'Kunda ruins in the far southwest corner room, the last building before the beach when running west along the southern edge from the main entrance.",v=9},{tags="danger",text="Several troll mystics camp the tablet's room, with about five or more other trolls nearby, so pull them one at a time or bring help.",v=4}}
t[2008]={{tags="floor",text="The tablet sits on the upper level of the ruins, on the southern edge of the pool above the waterfall, at 24,8.",v=8},{tags="danger route",text="An elite level 41 mob and his henchmen guard the west walls; approach from the northeast to avoid them.",v=3},{tags="danger",text="Two or three trolls stand right beside the tablet and guard it.",v=2}}
t[2310]={{tags="access floor",text="The pattern is taught by the trainer in Craftsmen's Terrace, on the floor above the tailor in Darnassus.",v=1}}
t[2382]={{tags="hidden route",text="Look for the grave behind Abercrombie's shed, northeast of Raven Hill Cemetery, where the heart can be found.",v=18}}
t[2458]={{tags="access",text="Obtaining the elixir requires a quest to find it, which only the Horde can receive.",v=9}}
t[2476]={{tags="access",text="The Chilled Basilisk Haunch only drops while the quest for it is active, so accept the quest first.",v=21},{tags="access",text="Keep the quest active (failed is fine) and do not abandon it until you have the haunch.",v=14},{tags="route",text="The Cold-eye Basilisks you need to kill can be found around this spot.",v=10}}
t[2592]={{tags="inside",text="The Thistlefur furbolgs that drop wool are inside a grotto west of Iris Lake in Ashenvale.",v=24},{tags="access spawn",text="Horde only: accept the Counter Attack quest west of XR; Kolkar Centaurs then attack, and asking the quest giver again makes them attack again.",v=5}}
t[2625]={{tags="route hidden",text="The statuette is in the third murloc camp north up the coast from Menethil, near the raised murloc platform, inside a half-buried barrel that is hard to see.",v=17}}
t[2629]={{tags="floor route",text="The captain stands on the upper deck of the second ship; reach him by walking up the wooden plank in the water at the back of the ship.",v=11},{tags="inside hidden route",text="The strongbox lies on the sea floor inside the hull: swim to the ship's north side, dive to the middle, and swim through the rectangular hole in the hull.",v=11},{tags="floor danger",text="Three guards stand with the captain on the upper deck of the ship.",v=10}}
t[2633]={{tags="access",text="You do not need the quest to get these to drop; they can be farmed without it.",v=2},{tags="inside spawn",text="Focus on the casters in the cave for drops; the cave's mobs respawn about 10 minutes after a clear.",v=2}}
t[2634]={{tags="inside",text="The box sits in the middle of three tents at 40,9 in the camp.",v=7},{tags="interact",text="Pile of boxes sits just in front of a house at 44,9; mouse over them to highlight, then right-click to extract.",v=1},{tags="danger",text="At 44,9, at least two defenders come out of the house doorway, and more if you linger.",v=1}}
t[2658]={{tags="spawn",text="Each fragment piece respawns at random spots around the excavation site, so the spots change.",v=28},{tags="route",text="From the hill southwest of the excavation site, start up the path at 32.2, 48.6, then turn left at the two trees.",v=21},{tags="spawn",text="Possible spawn spots: behind the big tree at the bottom of the ramp, at the small west tree by the pit, and at Sarlatan's spawn point.",v=3}}
t[2659]={{tags="hidden route",text="Hide behind the tree at the base of the ramp leading up to the quest giver.",v=18},{tags="spawn hidden",text="Its location changes between spawns; one spot is on the hill southeast of the digsite at 34.8, 52.6.",v=10},{tags="spawn",text="Look for the Large Jug at 34, 45, which holds the fragment.",v=1}}
t[2660]={{tags="hidden route",text="Golm Fragment lies on the ground behind the tree at the start of the ramp, hard to see; it is near 37,42 or 36,42.",v=19},{tags="hidden route",text="A Golm Fragment spawns up on the far right ledge at the back of the excavation, hard to see from the ground, at 32,51.",v=10},{tags="spawn",text="Golm Fragment spawn points at 34,47 and 33,46.",v=7}}
t[2661]={{tags="hidden route",text="Loose soil sits behind the big tree near the raptor eggs at the bottom of the ramp, at 37,42 or 36,42.",v=45},{tags="route spawn",text="It also spawns on the hill above Sarltooth at the back of the site; reach it by the hills on the right of the back wall.",v=33},{tags="spawn",text="It spawns at random among several spots and can reappear elsewhere after you pick it up.",v=33}}
t[2702]={{tags="spawn",text="Murlocs at the far south end of Wetlands drop the ingot, so farm them there.",v=4}}
t[2713]={{tags="spawn inside",text="After he is killed he respawns in his cave about 5 minutes later, not 30; if he is missing, check the cave again later.",v=12},{tags="inside patrol",text="Look for him in his cave at the base of the hills; he paces inside the cave.",v=12},{tags="danger",text="Ol' Sooty is an elite bear, so expect a tough fight at his spot.",v=1}}
t[2732]={{tags="inside route",text="Look inside the cave at Kurzen camp; its entrance is at 45.6, 8.3, and the page drops from Kurzen mobs inside.",v=1}}
t[2779]={{tags="interact inside",text="Pick the flower in the garden of Manor Mistmantle, north of Darkshire; it is not a drop.",v=18},{tags="danger",text="Ghouls are scattered around the garden area, so be careful when approaching it.",v=16},{tags="route",text="Go north out of Darkshire and take the eastern branch up the hill to the ghoul-filled shack and garden.",v=16}}
t[2784]={{tags="hidden",text="Look in the south-eastern Wetlands at the bottom of the waterfalls, where the root is tucked in between the falls.",v=33}}
t[2828]={{tags="floor inside",text="Nissa is in a farm building in the central square of the Mills, sometimes upstairs and sometimes downstairs in the house.",v=1}}
t[2830]={{tags="patrol route",text="Thurman wanders between three small windmills on the rocky coast; wait at the road bend to spot him from a distance.",v=20},{tags="route",text="Go to the northwest corner of Agamond Mills, west of the left windmill, then up the road to the three small coastal windmills.",v=20},{tags="patrol",text="Thurman has been found near these spots northwest of the mills.",v=19}}
t[2831]={{tags="route",text="Devlin Agamand is on the left side of the road, just up the hill before Agamand Mills, not far from the road.",v=8}}
t[2833]={{tags="hidden route",text="Find the pile of books on a table on the western side of the large island in Brightwater Lake, a little west of the Gunthar camp, not inside it.",v=18},{tags="interact",text="Open the pile of books on the table, then loot the book; it is not a normal drop.",v=3}}
t[2998]={{tags="inside route",text="The chest is inside the roofless, burned-out house just past the lighthouse, not in the farm itself. Approach from the south west.",v=10},{tags="route",text="You can loot the chest from the ledge at the western corner near the fireplace without entering the house.",v=10},{tags="danger",text="Defias Pillagers and Looters guard the chest; the Pillagers are linked and the Looters are more numerous.",v=10}}
t[3082]={{tags="inside route",text="Enter the crypt beside the second windmill and follow the hallways to the small hallway between the side rooms; Dargol's room entrance is on your left if you took the right room, or on your right if you took the left.",v=23},{tags="floor danger inside",text="Dargol's room is downstairs and guarded by four bodyguards plus Captain Dargol himself.",v=23}}
t[3155]={{tags="floor inside",text="Go to the house at 52,28 and check the upstairs room on the right side; the remedy is there.",v=12},{tags="hidden",text="The remedy is hidden under the body of the mob that dies protecting it; check under the corpse.",v=1}}
t[3254]={{tags="route",text="Moss Stalkers, which drop the Skittering Blood, are found by going to the far northwest of Sepulcher and passing The Dead Field.",v=1}}
t[3255]={{tags="inside floor route",text="Enter the inn-like building behind the central fountain at the back of the compound, then go up to the second floor.",v=8},{tags="danger floor",text="Apothecary Berard is in the second-floor room with elite mobs around him, and they are the last fight before the book.",v=8},{tags="interact",text="Loot Berard's Bookshelf in his second-floor room to get the journal.",v=8}}
t[3317]={{tags="access",text="Start the Rot Hide Ichor quest first; this item will not drop until you have begun it.",v=10}}
t[3340]={{tags="inside",text="Mine the ore in the cave with the spiders above Dun Algaz in the Wetlands.",v=16},{tags="spawn",text="The ore nodes in the Dun Algaz cave respawn very quickly.",v=16},{tags="inside",text="The ore is also found in the cave at Thelgen Rock in the Wetlands.",v=6}}
t[3348]={{tags="spawn",text="Giant Wetlands Crocolisk spawn only at a few points with a long respawn time; they are found around 25,21.",v=1}}
t[3357]={{tags="access",text="Gathering this herb requires Herbalism 150 first.",v=29}}
t[3390]={{tags="access route",text="The recipe for this elixir is bought from the goblin Bro'kin, standing on top of the northernmost wall in the ruins of Alterac.",v=1}}
t[3405]={{tags="floor inside",text="The talisman is in a wooden box on a balcony overlooking the tunnel inside the den, at the prize spot.",v=1},{tags="route",text="At the nexus of two bridges, take the path on the left and follow the minimap toward the talisman.",v=1},{tags="danger",text="A last group of three mobs stands near the talisman and must be fought.",v=1}}
t[3406]={{tags="route inside",text="Run down the barrow entrance tunnel and take the right-hand bridge to reach the spot.",v=16},{tags="danger inside",text="The black coffer holding the quill is at this spot, with two gnarls inside.",v=15}}
t[3407]={{tags="floor route",text="Find Oben Rageclaw, the trapped druid upstairs; the item lies right below him, down a hallway.",v=12},{tags="floor danger",text="The chest holding the item is on a lower level and is guarded by the named Greenpaw.",v=4}}
t[3408]={{tags="inside danger",text="Open the chest at 44,60; two gnars are inside with it.",v=10}}
t[3418]={{tags="access",text="You must first complete the satyr's quest (collecting spider webs, owl feathers and sabre fangs) before you can get Fel Cones.",v=16},{tags="spawn",text="Three Fel Cones spawn very close to Dolanaar, just northeast of the priest trainer's building; more are spread east and southeast of town.",v=16},{tags="spawn",text="Fel Cones are reported at these spots: 53,67, 58,55, 45,52, 59,61, 59,55, 55,65 and 55,69.",v=8}}
t[3421]={{tags="inside hidden",text="The herbalist supplier sells it inside the flower shop in the canal section east of the trade district, far south; it is hidden, so look beside the alchemy shop.",v=19}}
t[3477]={{tags="route",text="Farm the creepers and spiders at the bridge south of Tarren Mill, near the road just west of the bridge.",v=3}}
t[3498]={{tags="inside",text="She is found inside Durnhold Keep, which is part of the Caverns of Time.",v=21}}
t[3499]={{tags="inside interact",text="Use the key on Tog'thar's ball and chain on the ground beside him in the middle of Durnholde Keep, not on his avatar.",v=6}}
t[3502]={{tags="patrol",text="Two Mudsnout Shamans patrol around the field where the blossoms grow.",v=1}}
t[3508]={{tags="access",text="Mudsnout Mixture is a quest item for the Elixir of Agony chain, received from the apothecary during that quest; it is not shown in the quest log.",v=5}}
t[3510]={{tags="spawn",text="The mobs that drop this live near an allied town and also on the northern part of the coastline.",v=5}}
t[3517]={{tags="inside floor hidden spawn",text="Keg spawns randomly inside Dun Garok, usually against back walls on upper or lower floors; check the four rooms from ground level down to the fireplace room.",v=18},{tags="hidden",text="Keg is a small upright barrel standing on end, not the big reddish-orange kegs lying against walls.",v=18},{tags="spawn",text="Keg respawns about every 15-20 seconds, so keep checking rooms until it reappears.",v=18}}
t[3554]={{tags="floor danger",text="The Crown's boss sits on the second floor, guarded by two level 40 Warmongers standing right at the spot.",v=4}}
t[3618]={{tags="route",text="Gobbler usually stands on the first island right off the road near 18,40; if he is not there, check the island to the west near 16,37.",v=12},{tags="spawn",text="Gobbler respawns after being killed, so wait for him to return if he is not at his usual spot.",v=12},{tags="route",text="Gobbler can be found alone on a small slope surrounded by water near 16,38.",v=9}}
t[3619]={{tags="inside route",text="Enter the hole in the hull of the ship nearest the shore, on its east side; First Mate Snellig spawns just inside.",v=32},{tags="danger",text="One or two helper mobs are inside with Snellig and must be dealt with.",v=32}}
t[3622]={{tags="spawn access",text="Nightlash appears at any time, not only at night; killing some of the mobs at the Dead Field makes it spawn.",v=11}}
t[3623]={{tags="floor inside",text="Thule, the mob this item comes from, is upstairs in the main chamber of the castle.",v=9}}
t[3638]={{tags="route",text="Sarltooth sits on a rock shelf to the north east of the entrance; walk along the right side, then climb the wall up to the hill on the left.",v=12},{tags="spawn",text="Sarltooth respawns quickly after being killed.",v=12}}
t[3639]={{tags="spawn",text="He has no fixed spawn and rotates between spawn camps, which are marked on the map.",v=5},{tags="inside danger",text="He is in the second house on the right, where the elite dwarves are located.",v=3}}
t[3657]={{tags="spawn",text="Located next to Magistrate Burnside; it takes time to respawn after being used.",v=3}}
t[3659]={{tags="inside route",text="The Weathered Bookcase holding the book is inside the clock-tower building, not the large towered building. From the main gate, it is the building straight ahead.",v=32},{tags="route",text="Enter the Ruins from the plateau near Growless Cave, go left around the mountains, and drop over the wall. The clock-tower building is then ahead.",v=32},{tags="interact inside",text="Interact with the Weathered Bookcase inside the building to loot the book.",v=32}}
t[3668]={{tags="spawn",text="Syndicate assassins that carry this contract sometimes break into the inn in Southshore; they show up there regularly.",v=2},{tags="access spawn danger",text="During the Helcular's Revenge quest, touching the stone at the marked grave triggers an ambush of assassins, and each one carries a contract.",v=2}}
t[3688]={{tags="floor inside route",text="Kegan Darkmar is kept upstairs in the building behind the camp, reached through the back room.",v=5},{tags="danger",text="About seven guards are posted around Kegan Darkmar's building.",v=5}}
t[3691]={{tags="inside",text="The NPC is inside the little house with Alina at 20,86; he is not in the large building by camp.",v=4}}
t[3706]={{tags="access",text="The Worn Wooden Chest holding this item can only be looted by Alliance players.",v=4},{tags="inside route",text="The chest is inside a house in the far northwestern corner of the Alterac Mountains, directly next to Nagaz.",v=2}}
t[3708]={{tags="access",text="The rod only drops from yetis for players who have the Helcular's Revenge quest, so the quest must be active before killing them.",v=6}}
t[3713]={{tags="inside",text="Micha Yance, who sells Soothing Spices, is inside the Southshore building closest to the flight path.",v=28}}
t[3714]={{tags="danger",text="Guards stand nearby with a huge aggro range; be ready for them to pull when you approach.",v=4}}
t[3715]={{tags="patrol",text="Mobs near Dalaran that help the Elemental Slave patrol widely and are not chained to the Summoners.",v=1}}
t[3820]={{tags="spawn",text="Herb spawn points are predetermined, but the kelp does not always spawn at each one.",v=23},{tags="hidden",text="Stranglekelp grows underwater, so you must swim down to harvest it; it is not visible from the surface.",v=1},{tags="danger",text="Level 22-24 or higher mobs camp the areas where the kelp spawns in Wetlands.",v=1}}
t[3823]={{tags="access",text="Use the potion out of combat only; it cannot be used in combat, unlike Vanish.",v=32},{tags="danger",text="Invisibility can be detected by a Warlock with Detect Lesser Invisibility, so watch for Warlocks.",v=32}}
t[3839]={{tags="spawn",text="Stranglethorn Tigresses that drop the fang spawn around Bhag'thera, on the road; kill them near 37,33 or 35,34.",v=8}}
t[3851]={{tags="access",text="Horde players can buy the recipe from a vendor at Ghost Walker Post in Desolace, beside Kodo Graveyard.",v=15}}
t[3862]={{tags="access",text="The sinew only drops for players who have the quest; gorillas killed without it will not drop it.",v=75},{tags="spawn",text="The gorillas that drop it are found around 31,68, with other kill spots at 31,67, 32,68, 32,66 and 33,64.",v=8}}
t[3876]={{tags="spawn",text="Look for him north of the elite ogre entrance: by the log south of the mound, north of the mound, and by the trees south of the entrance.",v=8},{tags="spawn",text="Look by the fallen log north of the ogre mound, near the goblins in eastern northern STV.",v=4},{tags="spawn",text="Other reported spawn spots are at these coordinates, north of the Zul'Gurub area.",v=4}}
t[3877]={{tags="route",text="Find Tethis just north of Gurubashi Arena, around 28,43 or 28,42 by player reports.",v=5},{tags="danger",text="Tethis is surrounded by level 40 mobs, and basilisks and raptors are nearby; clearing guards can aggro him.",v=2}}
t[3879]={{tags="route spawn",text="Sin'Dall stands on top of a small hill at 32,17 in Stranglethorn Vale; the hill is reached by a ramp that starts at its southwest corner.",v=41},{tags="spawn patrol",text="Sin'Dall spawns near 31.5,15.5 below the hill, then walks up to the top; intercept her below the hill before she climbs.",v=9},{tags="spawn",text="After Sin'Dall is killed, she returns to the hill about 5 minutes later.",v=3}}
t[3880]={{tags="danger",text="Bangalash is at 38,34 on the hill southeast of the Mizjah ruins, a level 43 elite with three level 33 cats beside him.",v=23}}
t[3897]={{tags="spawn route",text="Kill pirate Pretty-Boy Duncan at the small pirate camp north and a little east of Booty Bay; he usually drops the eye on the first kill.",v=6},{tags="spawn route",text="Hunt Bloodsail raiders at the camp west of Booty Bay, north of Duncan's camp; the eye drops there.",v=2},{tags="inside spawn",text="Kill the Bloodsail mobs aboard the ship farthest to the right; it drops the eye most often there.",v=2}}
t[3900]={{tags="inside",text="An abandoned troll camp at 80,85 has a case of five bottles, with more bottles on the ground around it.",v=3},{tags="danger",text="Revantusk Village at 78,78 has hostile horde guards with a large aggro radius; stay clear of them.",v=3},{tags="hidden floor",text="The blue bottles lie on the ground along the coast and are dark blue and hard to see; four sit in a row around 78,75.",v=1}}
t[3901]={{tags="access",text="Bloodscalp Tusk is a quest item and can only be looted while you are on a quest that needs it (Cyclonian or Hunt for Yenniku).",v=15}}
t[3906]={{tags="inside route",text="The trophy pile sits inside a stone structure at 46,31, in the center of the Balia'mah Ruins.",v=7},{tags="danger patrol",text="About five trolls guard the pile, and a three-troll patrol circles it every few minutes; wait until they leave.",v=7}}
t[3908]={{tags="route",text="Found outside the north gate of Zul'mamwe, not inside the ruins; follow the wall east from the gate.",v=19},{tags="patrol danger",text="A patrol of three level 39-40 trolls passes through the north gate about once a minute.",v=19}}
t[3909]={{tags="inside patrol route",text="Ana'thek is inside a cave in the south-eastern Ruins of Zul'Mamwe; he patrols but always returns to his cave.",v=1}}
t[3917]={{tags="route",text="Strip miners are in the hills south of Ziata'jal Ruins, just east of Gurubashi Arena, between the road and the Zul'Mamwe ruins.",v=5}}
t[3918]={{tags="route",text="Hunt the Crystal Spine Basilisks on the cliff near Vile Reef, around 24,14.",v=1},{tags="route",text="Select inclines let you climb up and down the cliffs easily.",v=1},{tags="patrol danger",text="A couple of basilisks roam paths that cross other basilisks' spots, so you may face two at once.",v=1}}
t[3920]={{tags="spawn",text="The Charts randomly rotate between three spots: the one-tent camp (barrel or crates), the rowboat on the shore, and the large three-tent camp by its eastmost tent.",v=52},{tags="danger",text="A big mob at the main three-tent camp must be killed before the Charts can be reached.",v=1}}
t[3921]={{tags="spawn",text="Bloodsail Orders spawn randomly at one of several spots: on the crates or at the table by Crosby in the large camp, inside the small camp's tent doorway, or in the rowboat.",v=67},{tags="spawn interact",text="The rowboat near the camp is one of the spawn spots for the Orders; it is clickable on the ground.",v=1}}
t[3930]={{tags="inside",text="The key drops from ogres inside the Mosh'Ogg Ogre Mound cave; kill them in the cave, as the key is found there.",v=1}}
t[4034]={{tags="route danger hidden",text="The altar is deep underwater east of the island with water elementals, surrounded by elite murlocks; swim down to it without aggroing them.",v=5},{tags="interact",text="Wield the quest knife, then use it on the altar while standing on it; Gazban is summoned only after this.",v=5},{tags="interact",text="After Gazban is summoned, stay on the altar, since he evades if you leave its area.",v=3}}
t[4094]={{tags="hidden inside",text="Look behind a pillar or wall in the underwater ruins, on the north side of the glowing table.",v=12}}
t[4106]={{tags="route",text="Geologists to farm are found just south of the little Mining Company house: cross the bridge over the water and turn left immediately.",v=2}}
t[4234]={{tags="spawn",text="Heavy Leather drops from Elder Mistvale Gorillas in STV; several players are already there, so skin them yourself.",v=33}}
t[4278]={{tags="inside",text="Mine the kobold cave in the northeastern Arathi Highlands; the ore nodes are inside it.",v=83},{tags="access",text="Gathering this ore requires Mining skill.",v=83},{tags="spawn",text="The ore nodes inside the cave respawn very quickly, so you can keep mining them.",v=53}}
t[4371]={{tags="spawn",text="If a merchant such as Herble Baubbletump in Darkshire lacks this limited-stock item, wait 5 to 15 minutes for it to respawn in his inventory.",v=7}}
t[4381]={{tags="access inside",text="Horde players must get the schematic from Matrix Punchograph Machine B inside Gnomeregan, with a yellow punch card and Engineering 140.",v=27},{tags="access route",text="Horde can reach Gnomeregan by finishing Nogg's Rig Wars and Sovik's Speak with Scooty quests, then getting the teleporter rod from Scooty in Booty Bay.",v=27},{tags="interact",text="It cannot be used while you are polymorphed or incapacitated, so you cannot dispel yourself; use it on allies to remove their polymorph.",v=27}}
t[4389]={{tags="route interact",text="Fish in water to catch a Sealed Crate that can contain it; reported in Booty Bay and Desolace.",v=1}}
t[4392]={{tags="spawn interact",text="After placement it explodes about 10 seconds later, and a 3-minute cooldown applies between dummies (patch 1.10).",v=9},{tags="access",text="Using the item requires Engineering skill of 185; without it the dummy cannot be used.",v=1}}
t[4395]={{tags="interact",text="Deploy it by targeting the ground at your feet; the placement range is very small.",v=207},{tags="interact",text="After placing it, wait about 10 seconds for the beeping to stop before enemies walk over it; it draws nearby mobs while arming.",v=207},{tags="spawn",text="It explodes once when triggered and disappears; if never triggered, it vanishes after about one minute.",v=207}}
t[4405]={{tags="interact",text="Right-click the Crude Scope first, then left-click the rifle to apply it, like a sharpening stone.",v=8}}
t[4432]={{tags="hidden route",text="The corpse carrying the letter lies at the bottom of the river under Thandol Span, partly trapped under bridge rubble and half covered by a boulder.",v=22}}
t[4435]={{tags="inside route hidden",text="Mote of Myzrael drops best inside the kobold cave, entered from the gorge at 82,37 after following the tree at 80,40.",v=21}}
t[4440]={{tags="floor route",text="Syndicate Prowlers that drop the Sigil can be found above the ramp.",v=1},{tags="floor danger",text="Lord Falconcrest, a miniboss, stands on top of the tower; Sigil mobs are near him.",v=1},{tags="floor inside",text="After killing the two bosses in the castle, the Sigil dropped from an unnamed mob up on an upper level.",v=1}}
t[4441]={{tags="route",text="The quest giver stands on the broken bridge between Wetlands and Arathi Highlands, on a ledge you must jump up to reach.",v=10},{tags="inside floor",text="The Brewmeister who takes the item is in the Southshore inn, in the basement under the kitchen.",v=10}}
t[4450]={{tags="route inside",text="After entering Stormguard, head right to the entrance way; the Sigil Fragment area is there.",v=18},{tags="danger",text="Two Stormguard Defenders guard the entrance way where the Sigil Fragments are found.",v=18}}
t[4458]={{tags="patrol danger",text="Five Forsaken bodyguards wander around the Valorcall area and will attack if you start a fight near them.",v=9}}
t[4473]={{tags="access interact",text="The Eldritch Shackles require the Scroll of Myzrael from your inventory to summon her; use it there, not the shackles.",v=27},{tags="danger spawn",text="Myzrael is an elite that summons Prismatic Elementals about every 10 seconds; she is the spawn point to be cautious about.",v=1}}
t[4482]={{tags="patrol danger",text="The courier walks with four bodyguards along the road from Go'Shek Farm in Arathi Highlands to Tarren Mill in Hillsbrad; look for her on that road.",v=9},{tags="spawn",text="After the courier reaches Tarren Mill she respawns at Go'Shek Farm.",v=9}}
t[4484]={{tags="route",text="The Circle of East Binding stone is not the big pinkish shard; it sits a little northeast of it, up on a hill.",v=1}}
t[4487]={{tags="floor inside hidden",text="The chart lies on a round ledge against the mid-ship wall between the large back room and the hallway, on the second floor, below deck.",v=39},{tags="danger",text="Naga keep attacking through the floor and sticking you in place, so the chart is hard to reach while they are around.",v=6},{tags="floor inside hidden",text="The chart is a brown item on the bench around the main mast, one floor below deck; stand beside the mast and tilt the camera down.",v=2}}
t[4488]={{tags="floor inside hidden",text="The log is on the second floor, in the room with the mast coming through it, amongst some boxes.",v=12}}
t[4489]={{tags="floor inside",text="The log is in a pot on the second floor, in the front room of the building.",v=27},{tags="hidden inside",text="The log is inside a pot that is tough to see; exact spot is near 23.4, 85.1.",v=5}}
t[4490]={{tags="inside hidden",text="The log lies at the very bottom of the ship, at 20,85 on the map, blending into the bottom of the boat; look carefully.",v=9}}
t[4491]={{tags="route",text="Walk around Stromgarde on either side, then follow the ledge around the mountain to the spot near 30,80 on the Arathi map.",v=14}}
t[4492]={{tags="access",text="Equip the goggles so the gems show on the minimap; they are not visible otherwise.",v=18}}
t[4510]={{tags="hidden",text="She stands behind one house, not inside any building.",v=5}}
t[4520]={{tags="route",text="The elementals that drop the scroll fragments are up a trail right behind Theldurin.",v=4}}
t[4521]={{tags="inside",text="Find the granite inside the Yeti Cave in Hillsbrad Foothills.",v=27}}
t[4527]={{tags="route",text="Jump up at this spot to reach the high ground where the Ogre Shaman is; sneak up there to get the agate.",v=6}}
t[4530]={{tags="route floor",text="Climb the first ramp, then the second; the chest is across the way on a separate stone platform.",v=27},{tags="inside",text="Found in the ogre tower of Stromgarde Keep in Arathi, in one of three chests there.",v=6}}
t[4531]={{tags="floor inside",text="Found in a chest on the top floor of the tower.",v=5}}
t[4532]={{tags="floor",text="Find the chest on the third floor, just below the top floor.",v=3}}
t[4610]={{tags="inside",text="Look for the Carved Stone Urns sitting around the room in South Common Hall, inside Uldaman.",v=5}}
t[4611]={{tags="access route",text="Blue pearls come from giant clams in the deep water of Vile Reef, so you must swim underwater to reach them; bring underwater breathing.",v=55},{tags="route spawn",text="Clams in the Vile Reef trench almost always contain a blue pearl; swim the trench looking for clams.",v=1},{tags="hidden spawn",text="Giant clams sit among the rocks and blue coral in Vile Reef; check the rock sticking out of the water and the coral.",v=1}}
t[4627]={{tags="spawn",text="Rock Elementals are found near Kargath at about 12,34 and 14,35.",v=8},{tags="spawn",text="Kill the regular Rock Elementals, not the Lesser or Greater Rock Elementals, to get the Large Stone Slab.",v=2},{tags="spawn",text="Rock Elementals are also found in the southern Badlands at about 36,75.",v=1}}
t[4629]={{tags="",text="The crate sits in Camp Kosh next to the bubbling cauldron, not under a tent.",v=1}}
t[4630]={{tags="inside spawn",text="Scrap Metal drops mostly inside the ogre cave; it is rarer outside, so hunt the cave ogres.",v=14},{tags="patrol",text="Dustbelcher ogres are non-roaming at Camp Wurg; the roaming group wanders the Barrens.",v=3}}
t[4631]={{tags="inside route",text="The tablet is in the Sealed Hall outside the instance, southeast of the main entrance, around 53,61 (or 54.11, 58.13).",v=15},{tags="interact hidden",text="Look for the big Ancient Chest in the Sealed Hall, not a regular chest; it is not in either Common Hall.",v=14},{tags="route inside",text="Take the left cave at the instance entrance; the tablet lies at the bottom before the instance entrance.",v=7}}
t[4640]={{tags="patrol route",text="The boss ogre roves with his escort group between Camp Cagg and Camp Boff, travelling counter-clockwise along the path shown on the map.",v=10},{tags="spawn patrol",text="If the patrolling group is not at its spawn point, the boss respawns with the group, so follow them until he appears.",v=5},{tags="patrol danger",text="The boss travels with 5-6 big ogre escorts; he loops back to Camp Boff in the southeast Badlands, so wait there for him.",v=1}}
t[4641]={{tags="danger",text="Dagun flees at low health toward the nearby murloc camps, so kill him away from the camps or on the shoreline.",v=16},{tags="access route",text="Enchanted Sea Kelp must be obtained first; Mirefin Oracles on the southernmost murloc island drop it, and the island is around 64,27.",v=10},{tags="interact",text="Click the Enchanted Sea Kelp in your bag, not the altar, to use it on the Seaworn Altar on Mirefin island and summon Dagun.",v=10}}
t[4644]={{tags="inside floor",text="Mogh the Undying stands by the campfire on a small hill inside the Ruins of Zul'Mamwe, on the eastern side near the mountain.",v=8},{tags="danger",text="Mogh is surrounded by many Skullsplitter trolls and a healing minion, so the area around him is dangerous.",v=8}}
t[4646]={{tags="patrol",text="It has been seen coming toward the Center Fort in Alterac Ruins around this spot.",v=10},{tags="patrol route",text="Look for the two-headed ogre in a red loincloth wandering outside the castle entrance; it appears there and roams the area.",v=7},{tags="access spawn",text="Kill the first ogre at the castle entrance to make the Star of Xil'yeh ogre appear.",v=2}}
t[4648]={{tags="inside interact",text="Use the sigil on the NPC inside the Forlorn Cavern in Ironforge.",v=4}}
t[4703]={{tags="interact route",text="Break the tools by using the forges at the campsite northwest of Bloodhoof Village, at 34,46; right-click the tools on the forge.",v=25}}
t[4809]={{tags="interact",text="Click the Ambercorn once to open it; the nut is then taken into your inventory.",v=18}}
t[4819]={{tags="inside route",text="Find him inside the Venture Co. Mine, east of the ravaged caravan, on the right side of the path toward the back.",v=34},{tags="patrol",text="He stands still at that spot and does not roam, so look right where he stands.",v=34},{tags="spawn",text="The Supervisor is frequently bugged and may not spawn at all.",v=1}}
t[4852]={{tags="access",text="The NPC that supplies these bombs (via the Pearl Diving quest) is at 42,52 in the Badlands.",v=15},{tags="access",text="Making Flash Bombs requires the Engineering profession, so you must be an engineer to obtain them this way.",v=2}}
t[4854]={{tags="access spawn patrol",text="Ask Skorn Whitecloud in Bloodhoof Village to tell you a story; Ghost Howl then spawns in one of four locations and runs between them.",v=9}}
t[4859]={{tags="inside route floor",text="Once inside, keep to the right. The tunnels wrap around to the left and lead to the ledge where the orc is.",v=20},{tags="floor route",text="The medallion-dropping orc stands on a ledge on the north side of the cave. Go up from the back to come up behind him.",v=16},{tags="inside route",text="The cave entrance is at 44,57, north-northeast of The Den. Do not approach from the canyon north of Razor Hill.",v=6}}
t[4864]={{tags="route patrol",text="The skull is on a small hill behind Zalazane, the spot where he most often stops; it is not a drop.",v=19}}
t[4866]={{tags="spawn",text="Players found this head while walking around near this spot.",v=22}}
t[4883]={{tags="floor",text="The chest holding the item is on the roof of Tiragarde Keep.",v=20},{tags="access",text="Kill Benedict to get the key that opens the chest.",v=20}}
t[4886]={{tags="access",text="Finish the prerequisite quest Need for a Cure before this item becomes available.",v=9}}
t[4887]={{tags="spawn",text="Makrura are found mostly underwater rather than on the surface, around Darkspear and Echo Isles.",v=5}}
t[4891]={{tags="spawn",text="A level 9 Dreadmaw crocolisk at 33,45 dropped the amulet for one player.",v=7},{tags="spawn",text="Dreadmaw crocolisks in the river north of the bridge are the ones that can carry the amulet.",v=5},{tags="patrol",text="The croc carrying the amulet may swim back and forth up and down the river.",v=4}}
t[4893]={{tags="access",text="The Savannah Lion Tusk only drops from these mobs while you have the related quest active.",v=4}}
t[4903]={{tags="interact",text="Right-click the Eye of Burning Shadow in your bags to use it and start its quest.",v=7}}
t[4904]={{tags="interact",text="Turn the antidote in to the man standing between a cluster of tall rocks, just left of Orgrimmar's entrance.",v=1}}
t[4926]={{tags="route",text="Pick up the keg outside Kranal Fiss's house at Grom'dol Farm in the Barrens, just outside the tower entrance.",v=17},{tags="interact",text="Click the keg and accept the quest; nothing starts until you do.",v=2},{tags="spawn",text="The keg spawns just outside Camp Taurajo and respawns in about 2-3 minutes.",v=1}}
t[5006]={{tags="inside route",text="The dig site at Bael Modan is entered by going down into it, east of the road south of Camp Taurajo.",v=5},{tags="hidden inside",text="The prospector stands at the back of the dig site, behind a broken column in a ridge on the southeast side.",v=5}}
t[5017]={{tags="inside floor",text="Nitroglycerin is found in the castle above the digging site, so look on the upper floor.",v=4},{tags="route",text="An NPC standing outside the building also gives Nitroglycerin, so you can get it without going inside.",v=2}}
t[5023]={{tags="access spawn",text="Kill the nearby NPCs first; doing so makes the quest NPC spawn, so you can use Verog's Head.",v=9}}
t[5025]={{tags="patrol danger",text="Hezrul patrols the waters around the oasis, accompanied by two bloodchargers.",v=13},{tags="spawn inside",text="Hezrul appears at the entrance of the cavern.",v=1},{tags="danger",text="Two helper mobs join the fight as soon as Hezrul is attacked, even if he seems alone.",v=1}}
t[5026]={{tags="access",text="Fire Tar is a quest item and only drops for players who have the related quest.",v=2}}
t[5040]={{tags="inside route",text="The Shadow Hunter Cave is inside, located at 68,74.",v=44},{tags="route",text="Reach the cave by going south of the bottom tip of the Witherbark village lake, or south west past the two snake statues onto the boxed path that curves right.",v=16},{tags="inside route",text="Headhunters are near the entrance and Shadow Hunters are further in; at the cave's first fork, take the left path to find Shadow Hunters.",v=16}}
t[5051]={{tags="",text="Dig rats are found in the Bal'dur excavation site.",v=17}}
t[5061]={{tags="route",text="The entrance to the Raptor grounds is at 57,52; go deep into the back of the green area.",v=14},{tags="hidden",text="The silver box is a small black box in the back, next to the last raptor nest, at 58,54.",v=14},{tags="danger",text="Three level 17-18 raptors guard the silver box, so pull them one at a time or bring help.",v=6}}
t[5065]={{tags="hidden patrol",text="Stealthed harpies roam the Witchwing Slayer area and can appear unexpectedly as adds.",v=11},{tags="patrol danger",text="A random elite patrols the area where the Witchwing Slayer is, so avoid running into her while soloing.",v=11}}
t[5067]={{tags="route",text="Reach her by going over the Dry hills to avoid fighting through the area; the location is 38,11.",v=1}}
t[5072]={{tags="inside route",text="Lok is inside the tent up the hill in the south-eastern part of the camp; kill the guards on the way up the hill.",v=18},{tags="route",text="Go to the end of the ravine; Lok is on top of the hill at 40,81.",v=1}}
t[5073]={{tags="patrol route",text="Nak roams near the cliffs south of the Razormane area, around 43,80 to 44,83; look for him there.",v=7},{tags="patrol",text="Nak wanders south of Blackthorn Ridge, east of Bael'Modan across the road, further in near the mountains.",v=5}}
t[5074]={{tags="patrol",text="The mob that carries Kuz's Skull patrols around the area rather than staying at one spot.",v=5}}
t[5075]={{tags="inside hidden",text="Mangletooth, who gives buffs for Blood Shards, is inside a locked crate at 44,59 in Camp Taurajo in the Barrens.",v=143},{tags="access",text="Mangletooth gives no buffs until you complete the quest Tribes At War for him.",v=143}}
t[5076]={{tags="interact",text="The boots are inside a crate at this spot; open the crate to get them.",v=10},{tags="floor",text="The boots are in a crate on the lower level of the pirate camp closest to Northwatch Hold, not the upper level.",v=1},{tags="hidden",text="The crate is on the far side of the tent from the tree, a bit further along than the Telescopic Lens.",v=1}}
t[5096]={{tags="access",text="The claws drop only while you are on the related quest.",v=3},{tags="patrol",text="A large group of the mobs that drop the claws is around this spot; one of them wanders among the other groups.",v=3}}
t[5097]={{tags="route",text="Hunt the Enforcers and Overseers at Boulderlode Mine, not Sludge Fen; the mine is in the northeast corner of the map.",v=16},{tags="route patrol",text="Enforcers and Overseers outside the mine also drop the emerald, so you do not have to enter the cave.",v=1}}
t[5099]={{tags="access",text="Only Horde players can start this quest; Alliance players get a 'not available to your race' message.",v=9},{tags="access",text="The quest requires character level 10 to start.",v=1}}
t[5101]={{tags="access interact",text="Kill a nearby Zhevra to get the quest item, then use it from your bag while standing next to the dead tree.",v=20},{tags="hidden",text="The dead tree is around 60,30 and is not labeled on the map; look for it there.",v=20},{tags="danger",text="Using the item at the tree summons a level 19 raptor that attacks nearby players.",v=20}}
t[5164]={{tags="route",text="Go behind Camp Turayo to find the thunderhawk that the wings come from.",v=13}}
t[5165]={{tags="interact",text="Click the Angry Scytheclaw nests in the Barrens around 52,45; destroying them may abandon the quest.",v=6}}
t[5234]={{tags="inside hidden floor",text="The fossil lies on the floor of a cave at 39,52 in the Wetlands, so look down inside the cave rather than for a visible object.",v=28},{tags="route access",text="Climb the hill, cross the wooden bridge and take the ramp up to the cave; the entrance is near 34,41, keeping left of the excavation site past a big tree, with a waypoint at 33,40.",v=28},{tags="access",text="The fossil appears in the cave only after you have obtained the Stone of Elu from a raptor.",v=9}}
t[5334]={{tags="spawn inside patrol",text="Magglish spawns at the base of the cliff at the far end of the first chamber in the cave outside the instance.",v=17},{tags="spawn inside",text="Magglish also spawns at the dead end down the first left fork heading inward in the cave outside the instance.",v=17},{tags="spawn inside route",text="Mad Magglish is found in the first enclave to the right: enter the cavern, turn right down the main passage, and go a short distance right, roughly opposite the left passage to the instance entrance.",v=17}}
t[5338]={{tags="interact",text="Do not destroy the Seal manually. Take it to the ancient flame in the Bashal'Aran quest and right-click the flame to incinerate it.",v=2}}
t[5339]={{tags="spawn",text="Serpentbloom spawns at fixed spots along the path to the instance and inside it; it does not respawn in random places when you enter.",v=10}}
t[5359]={{tags="inside hidden route",text="Click the Pitted Island Chest's surroundings: it sits on the sea floor, north of Ghamoo-Ra's island, in the northern alcove, under water among seaweed.",v=52},{tags="danger",text="Three to four elite Naga (about level 23) guard the chest; they stand right beside it.",v=11},{tags="hidden route",text="The manuscript is in a dark squarish lockbox half buried underwater, right of the large turtle island, hidden among weeds.",v=6}}
t[5382]={{tags="hidden",text="Anaya is neutral and hard to see; look for her near these coordinates.",v=26}}
t[5386]={{tags="spawn",text="Hunt the Moonstalkers at 60,10 in the south end of the zone, where many of them spawn together.",v=9},{tags="spawn",text="Good Moonstalker numbers are found around 43,81.",v=7},{tags="route",text="Head all the way down Darkshore, then turn left to find the Matriarchs and baby children.",v=4}}
t[5387]={{tags="access",text="The cloak can only be used in Darkshore; using it anywhere else fails with a requires-Darkshore message.",v=88}}
t[5413]={{tags="spawn",text="Moonstalkers spawn in the Darkshore area around 38,62; killing the nearby bears forces them to spawn.",v=16},{tags="spawn",text="Moonstalkers cannot respawn while too many bears are around; kill the bears to bring them back.",v=5}}
t[5437]={{tags="interact",text="Loot the grayish-brown plant bundle sacks scattered throughout Bathran's Haunt to gather the hair.",v=9}}
t[5440]={{tags="route",text="The quest bottles are on tables in a small camp with a white tent, directly south of Splintertree Post.",v=6},{tags="interact",text="Only the light green bottles on the tables work; hover over the items until the cursor changes to click them.",v=6},{tags="danger",text="Forsaken intruders and stealthed rogues are at the camp; clear them before grabbing a bottle.",v=2}}
t[5461]={{tags="danger",text="Two elite demons, Prince Raze and Geltharis, stand at the spot with a satyr beside each; Geltharis is the one to kill.",v=6}}
t[5462]={{tags="hidden route access interact",text="After the earlier quest steps, follow the winding path up at 54,50 to the top, where the Hidden Shrine is; right-click it to get the rod.",v=66}}
t[5463]={{tags="patrol route",text="Glowing Gem comes from Saltspittle creatures; it is a random drop, so look for the Saltspittle Muckdweller or warriors northwest of the quest area.",v=3},{tags="patrol danger",text="The Saltspittle patrol mobs walk around the area and can be dangerous; watch for them.",v=2}}
t[5475]={{tags="danger hidden",text="The chest is in a small alcove at 54,35 in northern Ashenvale, guarded by two standing treants.",v=2}}
t[5494]={{tags="hidden route",text="Stardust Ruins: the Handfuls of Stardust sit in the sparkling bushes on the island in the middle; the bushes are plentiful.",v=4},{tags="spawn",text="Bushes on the island respawn in about 5 to 7 minutes; leave and return to refill them when grouped.",v=4}}
t[5519]={{tags="interact hidden",text="The rusty chest is not in the loot window. It appears on the ground under the slime corpse, so look back at the corpse after looting.",v=52},{tags="patrol",text="Rotting Slimes roam the east side of the road leading to the Barrens, near the Horde Scouts.",v=8},{tags="spawn",text="Kill Rotting Slimes in the area around 70,74; they can drop the rusty chest that contains the Iron Pommel.",v=5}}
t[5520]={{tags="floor inside",text="Open the chest on the second floor of the Sentinel's Bunkhouse building in Darnassus Tradesman's Terrace.",v=47},{tags="route",text="Reach the building by the bridge from the armor merchant, across from the shield vendor.",v=20}}
t[5533]={{tags="route",text="Red pillars on the map mark the area; follow the path leading up the hill to reach the boss.",v=7},{tags="danger",text="Ilkrud summons Voidwalkers with his last breath when he dies.",v=4},{tags="spawn",text="Felhounds and felguards respawn quickly after being killed.",v=2}}
t[5535]={{tags="inside route",text="Search the Scarlet Monastery library near Arcanist Doan's room; the book sits on a shelf along the wall just before the last right turn.",v=23},{tags="spawn",text="After it is picked up, the book takes about 30 to 35 seconds to respawn.",v=3}}
t[5536]={{tags="inside route",text="The book is in the Scarlet Monastery library, in the far northeast room, on the north wall between the benches.",v=13},{tags="danger",text="About three Scarlet mages stand on each side of the far northeast library room, next to the book.",v=13},{tags="patrol",text="A Scarlet Diviner patrols that part of the room; wait for him to leave before taking the book.",v=13}}
t[5537]={{tags="route",text="Approach from Ashenvale by following the road south, then take the ridge most of the way up the mountain and bear right toward the low-level mobs.",v=5},{tags="route",text="Dreadmist Peak has no direct path; circle the mountain anticlockwise from the north side to find the path up the south face.",v=4}}
t[5544]={{tags="patrol route",text="Dal patrols around Thistlefur Village, not inside the cave, and walks out under the village gate.",v=28},{tags="patrol",text="Dal is near the building to the right of the path that leads to the cave, outside the cave area.",v=9}}
t[5582]={{tags="spawn",text="Kill only the regular Sap Beasts (level 22-24), not the Corrosive Sap Beasts further south, since only the regular ones drop the Sap.",v=25},{tags="spawn route",text="Kill the Sap Beasts right along the dirt path heading northeast toward Stonetalon Peak, where they are reported to drop reliably.",v=2},{tags="spawn",text="Sap Beasts at this spot are reported to drop the Sap often.",v=2}}
t[5584]={{tags="route",text="Pass the gate in Stonetalon Peak; the tiger that drops the whisker stands by the big tree on your left.",v=9}}
t[5594]={{tags="route inside",text="There is no road; follow the torches to Jin'Zil's cave at 74,97.",v=6}}
t[5634]={{tags="interact",text="Free Action does not stop Daze, Scatter Shot, Fear, Blind, or Mind Control, and Meaxxna's Webspray is also an exception.",v=90},{tags="interact",text="Drink it before the stun or slow lands; it does not remove effects already on you.",v=74}}
t[5686]={{tags="danger",text="Two centaur guards stand at the top of the tree near Ordanus.",v=7},{tags="danger",text="Trees attack you as you approach and climb the tree to Ordanus.",v=7},{tags="floor route",text="Ordanus is at the top of a tree in Ashenvale; climb the tree to reach his final room.",v=5}}
t[5687]={{tags="route",text="Find the Gatekeeper's Key in a lamp just outside the Den, on the left of the entrance ramp.",v=3}}
t[5690]={{tags="floor interact",text="On the first platform after Rynthariel the Keymaster, look for the usable firepot.",v=1}}
t[5694]={{tags="interact route",text="Stand near a wagon with red rockets at Windshear Crag in Stonetalon Mountains (not the blue-rocket carts by the lumber mill) and use the item there, then use the detonator to blow up the wagon.",v=6},{tags="spawn",text="After the red wagon is blown up, mobs of the surrounding level (about level 19-21) spawn nearby.",v=6}}
t[5734]={{tags="danger",text="Foreman Rigger is a dangerous mob around the operators; avoid him unless you are strong enough to fight him.",v=1}}
t[5735]={{tags="hidden route",text="The recipient of the envelope is just off the flight path from Stonetalon Mountains and is hard to see.",v=6}}
t[5736]={{tags="route",text="Take the path that starts on the east side of the lake near 68.7,41.2 and climb north and west up the mountain.",v=15},{tags="route",text="Stand at the lake's edge with the water wheel straight ahead, turn right, and swim toward the U-shaped mountain path.",v=12},{tags="access route floor",text="After killing the guard by the water wheel, go behind the wheel and up one or two more levels to find Gerenzo.",v=8}}
t[5770]={{tags="route",text="Defias Enchanters at the Yorgen Farmstead in Duskwood drop it. The farmstead is on the right where the road turns south to Stranglethorn Vale.",v=31},{tags="inside",text="Defias Enchanters at Addle's Stead in Darkshire drop it. The Defias are inside the barn, so check there after clearing the ones outside.",v=10},{tags="inside patrol",text="Dark Strand Voidcallers in the Tower of Althalaxx in Darkshore drop it. Their patrol moves through the tower interior.",v=10}}
t[5793]={{tags="danger route",text="Razorflank is alone in a hut once the guards are cleared; go down through the pigs' path to the hut behind it.",v=1}}
t[5796]={{tags="danger route",text="Kill the elite murlocs underwater in the Vile Reef; they are the ones that drop the fin.",v=5},{tags="access",text="Bring an underwater breathing potion to reach the murlocs that drop the fin.",v=4}}
t[5798]={{tags="hidden",text="Rocket Car Parts lie on the ground and do not show on the minimap, so you must look for them visually.",v=3}}
t[5810]={{tags="interact inside spawn",text="Use the Fresh Carcass on the Flame of Uzel in a small cave; Frostmaw appears after a while.",v=3}}
t[5811]={{tags="access interact",text="Get a Fresh Carcass from mountain lions near Tarren Mill, then carry it to the cave and click the Flame of Uzel with it.",v=11},{tags="spawn",text="Frostmaw appears a few seconds after the carcass is used on the Flame of Uzel, so wait nearby.",v=11},{tags="route inside",text="Head north on the road near Tarren Mill past the ogres, then take the road turning left to reach the cave.",v=8}}
t[5824]={{tags="inside floor",text="The Tablet of Will is a large object in the room with Galgann Firehammer, placed against the wall next to him inside the instance.",v=21},{tags="danger",text="Elite guards stand in the room with Galgann Firehammer, so reaching the Tablet of Will will likely aggro them.",v=21},{tags="route",text="Enter through the back entrance, follow the tunnel north, and the room with the Tablet is on the left.",v=1}}
t[5834]={{tags="hidden",text="The snuff lies at about 44.5, 66 in the Stonemaul Ruins, on a stone-looking floor where it blends in.",v=18}}
t[5835]={{tags="inside",text="Find it in front of the cave entrance at the mouth of the Den of Flame, not the Stonemaul Ruins.",v=17}}
t[5836]={{tags="inside",text="The strongbox is inside the Den of Flame cave, at the very back.",v=37},{tags="route",text="Enter the cave through the entrance where the Grog for this quest is found.",v=33},{tags="inside",text="The strongbox is at 36,69 inside the cave, not 37,91.",v=6}}
t[5837]={{tags="patrol",text="Steelsnap wanders in northwest Thousand Needles, northeast of Highperch, close to the entrance to Feralas.",v=5},{tags="danger",text="Steelsnap is guarded by two level 28-29 bodyguard hyenas that attack when you engage him.",v=5},{tags="patrol danger",text="Steelsnap patrols in a loop around the camp near the Camp E'thok entrance, at about 13,20.",v=2}}
t[5842]={{tags="spawn patrol",text="Spawn points are close together around 63,49 near a wrecked hut; mobs in between can be killed while waiting for respawn.",v=19},{tags="spawn patrol interact",text="The digger that mines at 63,49 can be killed right after mining; follow it and wait for it to start digging.",v=4},{tags="spawn interact",text="Digger mobs mine the rock on the hill at 54,49 and then dig; killing the digger after it mines there drops the ore.",v=3}}
t[5843]={{tags="inside spawn danger",text="Grenka sits in a cave with a box at the end; destroying one box (not two) spawns harpy waves. Grenka comes in the 3rd or 4th wave, so you must clear the cave first.",v=12},{tags="spawn danger",text="Cave mobs respawn quickly during the fight, so clearing the area around the crates keeps them from coming back.",v=12},{tags="access spawn",text="You cannot stealth in and kill Grenka; she is not present until the cave is cleared and a box is opened.",v=4}}
t[5848]={{tags="spawn",text="Vultures spawn at the nest at 87,66, where six of them appear.",v=26}}
t[5849]={{tags="danger",text="Animals in the area chase you even if you flee into an NPC's home.",v=27},{tags="danger route",text="Camp guards at Freewind Post are dangerous; go around the mountains to avoid them.",v=27}}
t[5851]={{tags="floor inside",text="Cozzle, the only source of the key, sits in a small shack or control room at the top of the operations center tower, near the lake.",v=25},{tags="spawn",text="Cozzle's key drop is random, so it may take a respawn or two of Cozzle before the key drops.",v=1}}
t[5852]={{tags="floor inside hidden",text="Cozzle is at the top of the tower near the water on the east side of camp; he is inside the small mini house up there.",v=28},{tags="inside route",text="The blueprint chest is in the small hut south of the tower, next to the sawmill, by the door.",v=28},{tags="interact access",text="Cozzle's footlocker can be lockpicked at level 170 lockpicking skill if you want to open it that way.",v=3}}
t[5860]={{tags="inside route",text="Inside the Dor'Danil Barrow Den, take the downward path from the first large room instead of the bridges, then go left into the next tunnel and keep left.",v=112},{tags="floor route",text="The book sits on a small rock podium on the central platform of the next large room, reached by a bridge and a walkway to the lower level.",v=112},{tags="inside",text="The book is located inside the Dor'Danil Barrow Den.",v=10}}
t[5861]={{tags="inside route",text="Find the book inside the Scarlet Monastery Library, in a room on the left side of the hall just past the courtyard; it lies open on a table.",v=36},{tags="danger",text="Kill the two or three mobs in the room first, then the book is on the table in the first room.",v=36},{tags="route",text="Do not take the horizontal hall just before the last hall leading to Doan; that is too far past the book.",v=15}}
t[5862]={{tags="inside",text="The crate is inside the zeppelin wreckage at 54,56.",v=6},{tags="route",text="Shortcut: swim across the bay from Theramore to the slightly sandy shore at 55,50, then run up the hill to the wreckage.",v=5},{tags="danger",text="Lurkers are in the bay on the swim shortcut.",v=5}}
t[5867]={{tags="access",text="The Etched Phial only drops after you have accepted the quest The Sacred Flame; it will not drop without that quest.",v=110}}
t[5868]={{tags="interact",text="Fill the phial at the moonwell near 60,72 in Ashenvale.",v=34},{tags="",text="Kill Laughing Sisters around Raynewood Retreat, near 60,55, to get the phial.",v=34},{tags="route",text="The moonwell is south of the river bridge; follow the river's western bank south until the map shows its blue dot.",v=4}}
t[5869]={{tags="inside",text="The flame is inside the Splithoof Hold dungeon; enter the cave to reach it.",v=6},{tags="access interact",text="Douse the flame with a phial first, or it cannot be clicked again; get the phial from Rau Cliffrunner.",v=1}}
t[5877]={{tags="access",text="Only drops once you are partway through the \"The Swarm Grows\" quest chain; finish the earlier part first.",v=52},{tags="access interact",text="Accept the first quest at 68,64 before using the carapace, or using it will fail.",v=16},{tags="access",text="This quest is Horde only; Alliance characters cannot start it.",v=9}}
t[5882]={{tags="interact",text="Open the sunken barrel just north of the northern dock to find the document inside.",v=12}}
t[5883]={{tags="route",text="Search for the mudrock turtles south of Theramore, swimming along the shorelines around the 61,61 area.",v=9}}
t[5938]={{tags="danger",text="Other creatures in the area are stalking; watch out for them while you work the crawlers.",v=5},{tags="danger",text="Watch for an occasional crocolisk wandering among the crawlers.",v=1}}
t[5942]={{tags="hidden danger",text="Some Muckdwellers lurk underground and attack from hiding; they are hard to see and hard to target.",v=8}}
t[5945]={{tags="route",text="Look outside near Tabetha's hut, behind the house, around 46,61 to 47,53, where he usually is.",v=7},{tags="patrol",text="He patrols a short path along the river near the hut, so he may move from his usual spot.",v=7},{tags="route",text="Reach the hut from Stonemaul Ruins by crossing the lake and heading north; it has an incomplete bridge with candles.",v=3}}
t[5947]={{tags="inside interact",text="The Defias Docket is inside a Defias Strongbox in the farmhouse in Addle's Stead, not the barn.",v=14},{tags="route",text="Enter the farmhouse from its main entrance south of the east-west Duskwood road, near the Raven Hill entrance to the north.",v=14},{tags="danger hidden",text="Stealthed Defias hide in the plowed field and outside the house near the strongbox.",v=14}}
t[5948]={{tags="route hidden",text="Stand facing away from the Stormwind griffon master, walk off the wall into the water, then swim toward the gate to reach Jorgen fishing on the shore beside a small boat.",v=20},{tags="route",text="From the south end of the main bridge, turn left at the ramp to find Jorgen fishing.",v=15}}
t[6040]={{tags="access",text="Hank the Hammer in Stormwind gives the recipe free through the Origins of Smithing quest at level 40 and 210 Blacksmithing, after completing Supplying the Front from Tormus Deepforge in Ironforge.",v=13},{tags="access",text="Alliance players can train the recipe from the Artisan trainer in Ironforge at around 185 Blacksmithing.",v=5},{tags="access",text="Horde players can train the recipe from the Artisan trainer in Orgrimmar.",v=3}}
t[6041]={{tags="interact",text="Placing the chain on the offhand weapon makes the main hand immune to disarm, so the offhand is a valid spot for it.",v=27},{tags="interact",text="The chain replaces any enchant already on the weapon and cannot be combined with other enchants or kits.",v=20},{tags="access interact",text="A Blacksmith with 190 skill can apply the chain to a weapon through the trade window, and a non-Blacksmith must have one do it.",v=13}}
t[6049]={{tags="floor inside spawn",text="Jaeda the witch doctor sells it upstairs in the inn at Stonetalon Mountains, but she has only one in stock.",v=6}}
t[6065]={{tags="access",text="The essay only drops for players who have the quest, so you must accept it first.",v=16},{tags="inside danger",text="The Mire Lord in the cave in Misty Valley has also dropped the essay.",v=7},{tags="route",text="Swampwalkers in the northwest corner below the two lakes near Misty Valley are a good place to farm.",v=3}}
t[6066]={{tags="inside",text="Look inside the big tent at 74,48; he has been found there.",v=9},{tags="inside",text="He is also inside the tent with the ramp at 73,26, which is hard to miss.",v=2},{tags="spawn",text="He spawns in several spots: the large tent, the large platform, and the platform under the big canopy.",v=2}}
t[6072]={{tags="spawn inside access",text="Khan Jehn spawns inside the large flagged tent after a guard just outside it spawns; wait about two minutes, then bring the guard inside near him.",v=1},{tags="patrol danger",text="Patrolling dogs near the tent can kill low-level players quickly; watch for them while waiting for Khan Jehn to spawn.",v=1}}
t[6079]={{tags="access",text="The charm only drops after you have the related quest; without it, the mobs will not drop it.",v=15},{tags="route",text="Go to Kolkar Village, not Magram Village, and kill the Kolkar there; the Kolkar at about 71,46 is the correct spot.",v=13}}
t[6080]={{tags="spawn",text="Large clusters of Shadow Panthers gather at these spots; go to 70,10 or 84,20.",v=32},{tags="danger",text="Watch for Somnus, an elite dragon, in the NE Swamp of Sorrows where the panthers are.",v=11},{tags="hidden",text="Only a few panthers are in the far northwestern corner of the Swamp of Sorrows, and they are invisible.",v=2}}
t[6083]={{tags="route",text="Go to Bolgan's Hole in the southeast of Gelkis Village: enter the canyon, climb the slope, and cross the suspension bridges. Broken Tears drop from Tears of Theradras there.",v=12}}
t[6169]={{tags="spawn",text="Unprepared Sawtooth Flank drops are far better from Sawtooth Crocolisks northeast of Stonard than from the other spots; the drop is specific to location.",v=1}}
t[6172]={{tags="spawn",text="Lost Supplies come from Scattered Crate objects, which have 16 spawn points in the Swamp of Sorrows area; the crate is the source to find.",v=5}}
t[6175]={{tags="hidden",text="Artifacts lie hidden underwater in the lake, including near broken walls and statues; check beneath the surface and submerge for the deep ones.",v=9}}
t[6184]={{tags="spawn route",text="Monstrous Crawlers spawn in the deep water off the coast, not on the beach where Silt Crawlers are; kill the Monstrous ones out in the water.",v=3}}
t[6196]={{tags="access",text="Hunters cannot use maces, so starting the quest from the cudgel gives a proficiency error; relogging reportedly fixes it.",v=3}}
t[6245]={{tags="spawn",text="Only Tidehunters and Sea Witches drop the satchel; other island mobs do not, and respawns can change into other types.",v=14},{tags="route",text="Go to the big island of Ranazjar; its middle, near 29,8, has the Tidehunters and Sea Witches that drop the satchel.",v=13},{tags="spawn",text="Sea Witches also spawn in the water off the island, around 30,12 and 32,18.",v=1}}
t[6248]={{tags="interact",text="Loot the venom before the scorpashi stings you; once it bites you, the venom can no longer be looted from it.",v=15},{tags="spawn",text="Near Kormek's Hut at 63,35, usually one or two of the venom-dropping scorpids are spawned.",v=1}}
t[6249]={{tags="patrol spawn",text="Some Aged Kodo Hide carriers walk in a group of three to the Kodo Graveyard and disappear there, apparently dying in the graveyard.",v=6}}
t[6252]={{tags="inside route",text="The Doomwarder Captains are inside a building across the river; enter at 52,82 to reach them.",v=5}}
t[6259]={{tags="spawn",text="Low-level Groddocs spawn 2-3 at a time along the eastern ridge of High Wilderness, including one south of the Gordunni camp by a large tree; clearing bears speeds respawns.",v=2},{tags="spawn",text="Groddoc spawns are concentrated in the valley directly south of the Dire Maul entrance, at about 59,54.",v=1}}
t[6265]={{tags="interact",text="Soul Shards are obtained only by channeling Drain Soul on a mob and having it die before the channel completes; the mob must give XP.",v=42},{tags="access",text="Summoned demon shard refunds during flight paths are inconsistent; the refund does not occur after logging out with a demon summoned.",v=13}}
t[6283]={{tags="inside",text="Look on the circular room where the Big Worg Familiar is defeated; it is on the 8 o'clock shelf, bottom right corner.",v=41}}
t[6285]={{tags="access inside",text="Kill the captain first; the item is in a chest inside the eastern tower.",v=12}}
t[6435]={{tags="inside",text="The mobs needed for this quest are inside Thunder Axe Fortress in Desolace.",v=26},{tags="access",text="Complete the Alliance Relations quest before this one becomes available.",v=7}}
t[6442]={{tags="spawn",text="Oracles have been found near 27,7 and 40,17.",v=10},{tags="spawn",text="Oracles share spawn points with the Slitherblade Razortail, Slitherblade Tidehunter and other naga in the area; kill those if no Oracle appears.",v=7},{tags="spawn",text="Oracles spawn on Ranazjar Isle, in the water near it and on the small island before it; only three can be alive at once.",v=1}}
t[6450]={{tags="access",text="You must have First Aid skill 150 before you can learn the Silk Bandage recipe from a trainer.",v=79}}
t[6451]={{tags="inside route",text="Deneb Walker, the Alliance trainer who sells the manual, is in Stromgarde Keep in the Arathi Highlands. Enter the front gate, go under the bridge and take the first right, pass the two defenders, turn right at the first tree, cross a bridge, and go under the ivy. He is by a well on the right.",v=106},{tags="hidden danger patrol",text="Deneb Walker is hard to find, and elites wander the area around Stromgarde Keep.",v=1}}
t[6464]={{tags="route",text="Devouring Ectoplasm drops this item outside the instance, so you do not need to enter the instance.",v=5},{tags="interact danger",text="Devouring Ectoplasm can spawn a Cloned Ectoplasm that must be killed before you can loot the original; it won't attack from far away.",v=5}}
t[6534]={{tags="hidden",text="The chest sits behind a broken wagon, next to its back left wheel, northwest of the mountain slope in the Barrens.",v=25},{tags="danger",text="The chest is surrounded by many Razormane mobs, level 10-12, so expect them standing right at the spot.",v=3}}
t[6652]={{tags="floor route",text="The cave lies on the upper cliff level above the ravine, not in the ravine or Skull Cave. Reach it by the ramp or path just northeast of Razor Hill.",v=73},{tags="inside hidden",text="Dustwind Cave is on the top level; the Burning Blade Cultists that drop the pouch are inside it, while the thugs and neophytes wait outside.",v=26}}
t[6653]={{tags="access route",text="If the torch is lost, talk to Kranal Fiss, northeast of the Crossroads toward Duratar, to get the quest again.",v=1}}
t[6654]={{tags="access route",text="Go back to where the Flame Eternal was killed and get the quest from the Brazier there; the torch is not available until you do.",v=3}}
t[6655]={{tags="access",text="Drink a Sapta first; after that the Glowing Ember pops up for you to use or pick up.",v=20}}
t[6684]={{tags="access interact",text="Use it only during its quest, and only in a small part of Razorfen Kraul; it has five charges.",v=4}}
t[6712]={{tags="interact",text="The Practice Lock is one-time use: once picked, it cannot be picked again, so discard or sell it afterward.",v=57},{tags="access",text="Only a Rogue with Lockpicking skill can pick the Practice Lock open.",v=57}}
t[6718]={{tags="route",text="Fish for it in Cliffspring River in Northern Darkshore, right next to the fallen log bridge to the furbolg camp, at 53,32.",v=8},{tags="route",text="It can also be fished from the beach in the same area, along the shoreline between 51,23 and 51,21.",v=5}}
t[6767]={{tags="inside route",text="Go to the smaller building beside the sister's building, on the left when facing her door; the brother is inside.",v=10},{tags="route",text="He is in Thunderaxe Fortress in northwest Desolace, not Stormwind.",v=10},{tags="danger inside",text="Mages stand around the room where he is, with another mage in the center of the circle.",v=10}}
t[6785]={{tags="danger",text="Guards stand watching the spot where the book is; kill them before looting it.",v=3}}
t[6800]={{tags="floor inside",text="The Umbral Ore is in a lockbox or chest in the basement of the house, to the right of Captain Beld.",v=7},{tags="route inside floor",text="Enter the Ironband Compound house at the southeast corner of Dun Morogh, near 77,62, and fight to the lower floor.",v=5}}
t[6805]={{tags="route",text="Go southeast of the marked mountains and follow the path leading up into the hills to find the mob.",v=2}}
t[6841]={{tags="route",text="The Razorfen Kraul entrance is about 40-50 yards from the Great Lift; at the border just before the lift, turn right.",v=29},{tags="danger",text="Mobs around the Razorfen Kraul entrance are elites, not regular-level creatures.",v=29},{tags="inside route",text="Inside the instance, take the left path at the first fork and follow the large vine-root bridge around past the big cauldron; Roogug stands on the right.",v=16}}
t[6847]={{tags="inside floor route",text="Go inside the small house built into the mountainside and kill the Dark Iron Dwarf at the bottom of the stairs.",v=11},{tags="route",text="Dark Iron Spies south of the quest giver also drop it.",v=9}}
t[6851]={{tags="interact inside access",text="Right-click the cooking cauldron in Bath'rah the Windwatcher's hut in Alterac to make the Essence once you hold the required charms.",v=69},{tags="access",text="Before using the cauldron, collect 8 each of Burning, Thundering, and Cresting Charms; the charms are not quest items.",v=69}}
t[6895]={{tags="route",text="Hug the left wall of the courtyard; the stables are at the far end, and the place by the entrance only looks like a stable.",v=12},{tags="danger inside",text="A guard stands in front of the stable entrance and another is inside the stable.",v=12},{tags="access interact route",text="Free the prisoner in the cell by jumping down and talking to him; he opens the gate to the courtyard with the stables.",v=6}}
t[6912]={{tags="interact",text="Attack the Heartswood tree while standing right in front of it, until the cursor shows the cog icon; it opens by attacking, not by a normal click.",v=21},{tags="danger",text="About eight caster mobs with pets and guards stand around the tree; clear them before trying to open it.",v=21},{tags="route",text="The Heartswood tree is in the Ruins of Ordil'Aran, north-east of Maestra's Post in Ashenvale.",v=4}}
t[6915]={{tags="route",text="The fragments come from mobs in the area on the path to the right of the Butcher in Shadowfang Keep.",v=11},{tags="route",text="The fragment mobs are up the ramp to the left of the Fel Steed Stable, close to the Shadowfang Keep entrance.",v=3}}
t[6930]={{tags="access",text="The rod drops only while you have the quest, and only from caster orcs: Bonewarders and Shadowwarders.",v=14},{tags="route",text="A back entrance to the encampment is reached through the graveyard at 47,43.",v=9},{tags="route inside",text="Angerfang Encampment's main entrance is at 42,43 in Wetlands; the Bonewarders are found inside around 50,48.",v=6}}
t[6931]={{tags="hidden route",text="Lies on the ground at the water's edge in the murloc camp near 27,72, just left of the chest at the hut; it is not in the chest.",v=30},{tags="route",text="The fourth murloc camp east along the shore from Azurelode Mine, west of the Southshore pier, holds the book.",v=8},{tags="danger",text="The murloc hut holding the book has 5-7 static murlocs plus 2-4 roaming murlocs.",v=8}}
t[6989]={{tags="access",text="The drop only appears for players who have the related quest, so accept the quest before hunting.",v=25},{tags="route",text="The mobs that drop this are the named Hatefury creatures in northeastern Desolace around Sargeron, near 72,22 or 71,17.",v=8},{tags="route",text="Enter Desolace from Stonetalon Mountains and turn left; the area is south of Nigel's Point.",v=5}}
t[6990]={{tags="spawn",text="Infernals are concentrated in the southern central part of Desolace; the spot at 48,75 is where to find them.",v=6},{tags="access",text="Only players who have the warlock quest reliably get this stone; it drops from Infernals when you have the quest.",v=5}}
t[6992]={{tags="access",text="Take the quest from Bailor Stonehand in Thelsamar before trying to use the shipment.",v=18},{tags="danger",text="Elite level 18-20 ogres stand right next to it.",v=7},{tags="route",text="Hug the north wall, then run across the cave and drop down on the far side to reach it without fighting ogres.",v=7}}
t[6993]={{tags="access inside",text="Talk to Baylor Stonehand in Thelsamar first, in the second building on the left; the crate stays unusable until you do.",v=36},{tags="hidden route",text="The crate sits under a tree beside a dead wagon, near the middle cave of Mo'grosh Stronghold; turn around from the cave hole to find it.",v=17},{tags="access interact",text="Pick up the quest from the tailor's house before going for the ore; otherwise the crate will not be clickable.",v=15}}
t[6994]={{tags="inside route danger",text="Look for Whitestone Oak Lumber in the room right after the Ogre, where goblins chop wood; a door there must be opened manually.",v=17},{tags="spawn",text="The wood drops from the first goblin killed, so you need not kill the elite goblin boss at the machine.",v=4},{tags="danger",text="The elite robot chopper near the goblins is tough; it guards the wood-chopping room.",v=1}}
t[6995]={{tags="route",text="The Tide Priestesses that drop the gem are found outside the instance portal, just past the water.",v=6}}
t[6997]={{tags="hidden",text="The quest chest is a small brown Damaged Chest on the ground, not the nearby Solid Chest.",v=19},{tags="inside route",text="Enter Splithoof Hold, the cave at the Galak centaur camp on the north wall of Thousand Needles, reached via the Great Lift.",v=17},{tags="spawn",text="Centaurs in the cave respawn quickly, so the chest may need several passes before it is reachable.",v=17}}
t[7006]={{tags="access",text="Look in your bag: the tome is a reward from a previous quest, not a world pickup.",v=17}}
t[7048]={{tags="access inside",text="The recipe is bought from the Artisan Tailor in the tailor shop on the east edge of Stormwind's Mage District.",v=1}}
t[7067]={{tags="spawn route",text="In south Badlands, you can alternate between two camps of Rock Elementals and never wait for them to respawn.",v=5},{tags="inside patrol",text="Inside Maraudon, the Rock Elementals walk patrols, so you can get a drop from nearly every patrol.",v=4}}
t[7070]={{tags="spawn route",text="Elemental Water is only from Lesser Water Elementals on the island in Stranglethorn Vale, around coords 20,22; the Feralas sea elementals gave no drops.",v=49}}
t[7077]={{tags="spawn",text="Heart of Fire is best farmed from fire elementals in the center of Un'Goro Crater.",v=40}}
t[7078]={{tags="route spawn",text="From the northeast side of Fire Plume Ridge, go up the ramp and across the bridge; the fire elemental spawn sits on the hill to your right.",v=1}}
t[7080]={{tags="interact",text="Fish up the Patch of Elemental Water pools in Azshara's Bay of Storms to get the essence.",v=50},{tags="danger patrol",text="Elite giants around mid-50 patrol the Bay of Storms near the pools; avoid them at low level.",v=50},{tags="access",text="Landing pool catches reliably needs about 420 fishing skill; lower skill rarely succeeds.",v=50}}
t[7081]={{tags="patrol spawn",text="Gusting Vortex Elementals and Land Ragers roam a wide area of Tanaris along predictable paths; look around Broken Pillar, Eastmoon Ruins and The Gaping Chasm.",v=26},{tags="spawn",text="Earth elementals share the same respawn rate, so kill them too.",v=16},{tags="spawn",text="Respawns take about 8-10 minutes, and each spawn is randomly either a Land Rager or a Gusting Vortex.",v=7}}
t[7083]={{tags="route",text="Thundris Windweaver is in the north building near the bay on the north side of Auberdine, Darkshore.",v=136},{tags="inside route",text="Enter Blackfathom Deep by jumping into the pool by the shore, diving under the water, and surfacing on the other side; look for whirling lights.",v=136},{tags="inside",text="The corrupted gem drops from naga oracles and priestesses in the pools outside the instance, so you don't need to enter it.",v=136}}
t[7127]={{tags="danger",text="Hillsbrad Fields at 27,59 is dangerous without help; go with a companion, as solo players get killed quickly.",v=8}}
t[7131]={{tags="interact",text="You must test the shinbone to get the sturdy shinbone.",v=1}}
t[7208]={{tags="interact",text="Move Tazan's Key from the keyring to the backpack before using it to unlock the satchel.",v=2}}
t[7226]={{tags="inside route",text="Go to the hut on the hill northeast of the Gnomeregan entrance, the one on the right with the lift, and look inside.",v=22},{tags="floor",text="The item is on the main floor, to the right of the lift.",v=22},{tags="hidden",text="The item is partly hidden behind a chair, so look closely.",v=22}}
t[7227]={{tags="route",text="Snapdragons grow in the fenced garden just south of the main barn at Balnir Farmstead, east of Brill.",v=12}}
t[7228]={{tags="spawn route",text="The Orgrimmar ice cream vendor is a special spawn located between the bank and the inn, at 52,69.",v=24},{tags="route",text="The Stormwind ice cream vendor stands in the Trade District outside the bank, between the bank and the inn, right of the large tree near the mailbox.",v=24},{tags="spawn",text="During this event the Stormwind ice cream vendor sells it, in the Trade District next to the inn and bank.",v=1}}
t[7231]={{tags="spawn",text="Astor is stationed south of The Sepulcher and stays put; players report he is hard to find on the road there.",v=15}}
t[7249]={{tags="inside access",text="Look for the gems in piles of boxes inside the mine north of Loch Modan town, not in chests. They can only be taken while the quest is active.",v=15},{tags="inside",text="The gem box spots inside the mine are at these coordinates.",v=1}}
t[7266]={{tags="floor inside",text="Look on the bookshelf at the top of the tower; the treatise sticks out from the shelf.",v=5}}
t[7267]={{tags="spawn route",text="Carrion Recluses in the middle of Raven Hill Cemetery drop the silk; killing them near the fountain is the reliable spot.",v=5},{tags="inside",text="Killing the big green spiders inside the graveyard fence is where the silk drops; they are among the undead.",v=3},{tags="danger patrol",text="An elite Skeleton roams the Raven Hill Cemetery graveyard and attacks players questing there.",v=1}}
t[7268]={{tags="route",text="Follow the river from Splintertree Post to the waterfall, swimming across the lake to reach it.",v=13},{tags="access interact route",text="Fill the flask under the big waterfall at Xavian's Falls, not the first falls at the river's end; the wrong falls refuses the fill.",v=7}}
t[7272]={{tags="interact",text="Stand by the center stone of the Circle of Outer Binding, right-click the totem sticks, then click the bolt that appears above the stone and loot it before leaving.",v=61},{tags="access",text="Requires ten Witherbark Totem Sticks, collected from Witherbark Trolls, before the bramble can be obtained.",v=61},{tags="danger",text="Air elementals are in the Circle of Outer Binding; kill them to clear the circle before using the stone.",v=18}}
t[7273]={{tags="interact danger",text="Use the totems at the Stone of Outer Binding at 52,51, which is ringed by level 38-39 Thundering Exile and Lightning elementals.",v=8}}
t[7274]={{tags="inside hidden route danger",text="Look on the left-side shelf as you enter the Athenaeum; the thick book sticks out just before Doan. Forced right turn, two Scarlet hostiles nearby.",v=16},{tags="inside route",text="The book is at coordinates 84,34 in the Scarlet Monastery.",v=4}}
t[7291]={{tags="spawn",text="Burning Blade Summoners spawn all over Mannoroc Coven, so they are not confined to one spot.",v=3},{tags="patrol",text="Burning Blade Summoners wander around a lot rather than staying in one spot.",v=2},{tags="access",text="The Infernal Orb drops only while you have the quest; kill Burning Blade Summoners in Mannoroc Coven that are on your quest.",v=1}}
t[7506]={{tags="interact danger",text="Mechanical bosses such as Fel Reavers are immune to the Gnomish Universal Remote and cannot be controlled with it.",v=64},{tags="interact",text="A Hunter or Warlock must dismiss an active pet before using the remote, because the remote needs the pet bar.",v=56},{tags="access",text="The schematic is taught by an Engineering expert in Ironforge.",v=6}}
t[7666]={{tags="access inside",text="Horde players can take the necklace to Droffers and Sons Salvage inside the Drag in Orgrimmar to start a quest chain back into Uldaman; do not discard it.",v=111}}
t[7669]={{tags="inside hidden",text="Find the ruby inside Uldaman with Galgann Firehammer and his dwarfs, in the cache near Firebeard (location #3).",v=15},{tags="spawn danger",text="Clear the area before opening the cache; the first loot spawns a wave of about four dwarves that can attract the boss.",v=3}}
t[7670]={{tags="danger",text="Grimlok is a level 45 elite who stands with guards, so expect elite and guard danger at his spot.",v=12}}
t[7671]={{tags="inside",text="Find the topaz in a tall tan urn to the right of the big door at the end of Dig Two, the room on the left inside the entrance.",v=32},{tags="route inside",text="From the instance entrance, turn left, then keep left past the hole in the wall to reach Dig Two.",v=32}}
t[7675]={{tags="interact",text="Pickpocket the Dockmaster to get the schedule; you must be in stealth to do it.",v=13},{tags="route",text="Approach by cutting to the right of the building on entry and circling behind the Dockmaster.",v=4},{tags="danger spawn",text="Three bodyguards stand near the Dockmaster and attack if you are seen; wait for them to despawn before trying again.",v=3}}
t[7737]={{tags="interact danger",text="Pickpocket him instead of attacking, since attacking spawns four minions. If he knows you are there, wait until he is busy fighting someone else, then stealth up and pickpocket him.",v=11},{tags="spawn route",text="He spawns in the branch sticking out from the edge of the Oracle Glade, reached down the wall to the east, at this spot.",v=6}}
t[7811]={{tags="access",text="This item is given to you automatically when you accept a quest, so you do not need to find it in the world.",v=3}}
t[7812]={{tags="access interact",text="Drink the Water Sapta right by the tall rock; the Manifestations then appear, and you must have the quest's item to see the elemental.",v=8},{tags="access",text="You must be on the quest for the bracers to drop; the drop does not happen if you have not picked up the quest.",v=4}}
t[7848]={{tags="access",text="The shard only drops from kills after you have the related quest; without the quest, kills give nothing.",v=1}}
t[7908]={{tags="floor access",text="The journal is in a chest at the top, so a key must first be pickpocketed from the guy outside; the commenter reports only one player per group could loot it.",v=1}}
t[7922]={{tags="access",text="Learn the recipe from Brikk Keencraft, Booty Bay Master Blacksmith, at 28,75; it requires 218 smithing skill.",v=40}}
t[7923]={{tags="interact spawn",text="Only the drone carrying the key has a sparkling glow; if he has no glow, kill him and wait for him to respawn.",v=22},{tags="spawn interact",text="The drone respawns on the tower entrance steps; pickpocket him right after he spawns, before he attacks.",v=9},{tags="patrol interact",text="Pickpocket the Malformed Defias Drone who walks around the outside of the tower to get the key.",v=3}}
t[7928]={{tags="access",text="Alliance players must talk to the Goblin Blacksmith in Booty Bay to unlock the Mithril Order chain that leads to the shoulders.",v=5},{tags="access",text="Complete Galvan the Ancient's quests to learn how to make the shoulders.",v=4}}
t[7929]={{tags="access",text="Learn the plans by completing the quest \"The Old Ways\" in Ogrimmar first.",v=16}}
t[7930]={{tags="access",text="Brikk Keencraft, a goblin in Booty Bay, teaches the recipe once you reach 230 Blacksmithing, even without armor specialization.",v=18}}
t[7931]={{tags="access",text="Learn the Mithril Coif recipe from Brikk Keencraft in Booty Bay once you reach 230 Blacksmithing; first get Artisan training from him at 200 skill.",v=10}}
t[7935]={{tags="access",text="The breastplate recipe is learned from the quest The Mithril Kid in Gadgetzan; you must complete it before you can craft this item.",v=17}}
t[7936]={{tags="access",text="Trenton Lighthammer in Gadtzan teaches the plans after completing the mithril order quest chain, so the quest must be done first.",v=27},{tags="access",text="The plans come from the quest The World At Your Feet in Gadgetzan; the recipe is learned there.",v=8}}
t[7937]={{tags="access route",text="The chain starts with Galvan the Ancient, whose small camp is north of the Mosh'Ogg Ogre Mound in Stranglethorn Vale; you must complete his quests first.",v=37},{tags="access",text="The recipe is learned from the quest A Good Head On Your Shoulders in Gadgetzan, given by Trenton Lighthammer after the Armorsmith quest chain.",v=12},{tags="access",text="Hank the Hammer in the Stormwind Dwarven District, by the forge, starts the chain and needs about 205-210 Blacksmithing.",v=2}}
t[7941]={{tags="access",text="Learn the recipe from your Artisan Blacksmithing trainer, Saru Steelfury in Orgrimmar or Bengus Deepforge in Ironforge, once you have 210 Blacksmithing.",v=10},{tags="floor inside access",text="Brikk Keencraft, on the top floor of the Booty Bay smithy, also teaches it, but only after you have Artisan Blacksmithing.",v=10}}
t[7943]={{tags="",text="Wicked Mithril Blade's plan is bind on pickup, so it cannot be handed to another player.",v=7}}
t[7945]={{tags="access",text="The Big Black Mace pattern is taught only by the Master Blacksmith in Booty Bay and requires Blacksmithing 230 plus Artisan training first.",v=35},{tags="inside route",text="Brikk Keencraft, the Master Blacksmith, is inside the building by the forge; enter Booty Bay through the tunnel and take the immediate left at the top.",v=3}}
t[7968]={{tags="inside",text="Open the lockbox in the ship at 65,46; the Jewel of Southsea Buccaneers is inside the ship.",v=15},{tags="access",text="Get the cracker from the sputtering robot or the box next to the quest giver before opening the chest.",v=15},{tags="spawn interact",text="Opening the chest makes Polly appear behind you; feed him the cracker to make him attackable.",v=15}}
t[7969]={{tags="access interact",text="Mithril Spurs must be made and attached to boots by a blacksmith; the player cannot use them otherwise.",v=3},{tags="interact",text="Attaching Mithril Spurs to boots replaces any existing boot enchantment, armor kit, or spurs already on them.",v=1}}
t[8026]={{tags="inside hidden route",text="It is not inside the instance but in the small room just left of the instance's front door; the small chest sits behind a pillar.",v=26}}
t[8027]={{tags="inside route",text="The treasure lies outside the instance, not inside it; do not look for it within the dungeon.",v=8}}
t[8048]={{tags="inside",text="It is inside the southeastern-most building of Starbreeze Village.",v=5}}
t[8050]={{tags="interact",text="Ferocitas the Dream Eater, level 8, is at 69,53 NE of Starbreeze Village. Right-click the Gnarlpine Necklace he drops to get the jewel from inside it.",v=18}}
t[8053]={{tags="route inside",text="Horde: go east from Kargath to Dustwind Gulch, then southeast to the troggs-covered hill. The back cave entrance on that hill leads down a tunnel to the instance.",v=24},{tags="route",text="Alliance: follow the path south from Loch Modan past the Uldaman front entrance until it becomes desert, then head east and southeast to Dustwind Gulch.",v=24},{tags="danger",text="The Obsidian Sentinel is at 61,46 against the hill, and lower-40s elites guard it.",v=15}}
t[8072]={{tags="spawn interact",text="Stand behind Silixiz's respawn point and pickpocket him right as he respawns, before he fully appears.",v=9},{tags="danger spawn",text="Two wandering guards appear near Silixiz's respawn, slightly before or after he respawns.",v=9},{tags="interact",text="Pickpocket Silixiz to get the key; looting his corpse does not work.",v=5}}
t[8073]={{tags="inside spawn route",text="The lockpicking boxes are inside the hold of a boat on the beach south of Ratchet and respawn within seconds.",v=3},{tags="access interact",text="Opening the tin needs high Lockpicking skill, so train on the lockpicking boxes in the boat first.",v=2}}
t[8150]={{tags="spawn",text="Farm Rumbling Exiles at the Circle of Inner Binding in Arathi, around 41,80; the salt drops from them.",v=19}}
t[8153]={{tags="access",text="Wildvine does not appear on its own; it can show up when you gather Purple Lotus.",v=384}}
t[8187]={{tags="spawn",text="Jangdor Swiftstrider at Camp Mojache in Feralas sells the Turtle Scale Gloves pattern; he is also the Wild Leather quest giver.",v=8},{tags="spawn",text="Jangdor's pattern stock respawns about every 30 minutes, so check again if he is sold out.",v=6}}
t[8189]={{tags="route inside",text="Alliance players can learn the pattern from the artisan leatherworking trainer in Darnassus, inside the city.",v=4},{tags="route",text="Horde players can learn the pattern from the artisan leatherworking trainer in Ferales.",v=4}}
t[8191]={{tags="inside floor",text="Find Drakk Stonehand, the Alliance Master Leatherworking Trainer, inside the main Wildhammer Keep in Aerie Peak; he is left inside and down one flight of stairs.",v=21},{tags="access",text="Reach Leatherworking 215 and level 35 before apprenticing to the trainer to learn this recipe.",v=21},{tags="hidden access",text="If the recipe is not in the trainer's available list, check his red unavailable list, since it appears there when your skill is too low.",v=21}}
t[8192]={{tags="access",text="Shoulders are available from the leather supply vendor Nioma in The Hinterlands.",v=7},{tags="spawn",text="Vendor stock for these shoulders respawns on a roughly 30-minute timer.",v=3},{tags="route",text="The leather supply lady Nioma is near Aire's Peak, at the Keep by the master leatherworker.",v=2}}
t[8193]={{tags="access",text="For Horde, get the pattern from Hahrana Ironhide, the Master Leatherworker in Camp Mojache, Feralas.",v=12},{tags="access",text="For Alliance, the pattern is available in Aerie Peak.",v=9}}
t[8197]={{tags="inside route",text="Horde players learn the pattern at Camp Mojache in Feralas: enter the building across from the inn and turn left inside to find the trainer.",v=6},{tags="inside",text="Alliance players learn the pattern from the Master Leatherworking Trainer Drakk Stonehand inside Wildhammer Keep in the Hinterlands.",v=4}}
t[8198]={{tags="access",text="Learn the recipe from the artisan (leatherworking) trainer in Aerie Peak; it may already be in your recipe book.",v=14}}
t[8200]={{tags="inside",text="The Rock Elemental that drops it sits inside a cave in Badlands at 14,35.",v=1}}
t[8210]={{tags="access",text="Obtaining the shoulders requires a quest first; the Alliance quest is given in Feralas, and the Horde quest is in the tent in Camp Mojache.",v=8}}
t[8211]={{tags="access",text="The Wild Leather Vest pattern is learned from Pratt McGrubben in Feralas, through a quest where you turn in leather items to him.",v=7}}
t[8214]={{tags="",text="Random enchantment: the stats are random when crafted, so you cannot choose what you make.",v=3},{tags="access",text="Tribal Leatherworking quest needs this helm, obtained from the Feathermoon Stronghold leatherworking supplier in Feralas after reaching 225 skill.",v=3}}
t[8393]={{tags="spawn",text="Scorpoks share a respawn timer with Starving Snickerfang, so killing the hyenas also affects when scorpoks respawn.",v=5},{tags="spawn",text="There are only about four scorpok spawn points, so they are scarce.",v=2},{tags="spawn",text="Scorpids were found in the area between these two points.",v=1}}
t[8394]={{tags="spawn",text="Basilisks only respawn after all mobs in the area are killed; kill the other mobs to get them back.",v=16},{tags="spawn",text="Basilisks share spawn with Ashmane Boars; if basilisks are not appearing, kill the boars.",v=3}}
t[8428]={{tags="route",text="Thistleshrub Dew Collectors, the only mob that drops this, are found southwest of Tanaris near the road to un'Goro, around 27,68 and 29,65.",v=16}}
t[8431]={{tags="inside route",text="Enter The Finest Thread shop by the canal bridge on Cathedral Square's side toward The Parks in Stormwind; it is not the other thread shop.",v=14},{tags="floor",text="The spool lies on the floor beside the counter, on its left side, not on the counter itself.",v=11},{tags="interact",text="Click the small pink spools in front of the counter to gather the thread from them.",v=11}}
t[8443]={{tags="",text="Look for white sand clumps across Tanaris; they are concentrated around Eastmoon Ruins in the middle of the southern third of the zone.",v=3}}
t[8463]={{tags="",text="The Fallen of the Horde stands at the entrance of The Desolated Lands near Stonard; it is not Bengor or the Ghost of the Murloc.",v=2}}
t[8523]={{tags="access inside route",text="Alessandro Luca sells it for 10 silver at friendly reputation in the Undercity, in the Apothecarium's outer circle; coords about 58.6, 54.6.",v=8},{tags="access",text="The Horde version of the apothecary quest gives a voucher for the kit, so no purchase is needed; the kit is kept in the Undercity's tab.",v=1}}
t[8526]={{tags="spawn",text="Respawn time is reported as effectively zero, so you can keep picking the same spot.",v=47},{tags="hidden route",text="Look underwater in Valorwind Lake in The Hinterlands, around 40,59 or 41,60; the mushrooms grow on the lake floor.",v=23}}
t[8545]={{tags="access",text="Horde players learn it from Doctor Gregory Victor in Hammerfall, Arathi Highlands, at 73,36, once First Aid is 240.",v=174},{tags="access",text="Alliance players learn it from Doctor Gustaf VanHowzen on Theramore Island, Dustwallow Marsh, at 67,48, once First Aid is 240.",v=174},{tags="access",text="The Triage quest from that same doctor must be completed before he will teach this bandage recipe.",v=174}}
t[8548]={{tags="access",text="Kill the trolls, then talk to the goblin so he opens the door to Sergeant Bly, who is the rod's source.",v=11}}
t[8585]={{tags="floor danger",text="Find the small lake at 39, 29; after filling the widget there, two bugs attack.",v=20}}
t[8593]={{tags="inside route",text="Underground tunnels are entered through the spiraling hole at 55,70 in the Gaping Chasm, on the north side.",v=149},{tags="inside",text="The gear lies underground in the northwest tip of the star-shaped room, near the top-left corner by the cavern entrance.",v=15},{tags="danger patrol",text="A single guard bug stands by the gear, and a patrolling wasp passes through; wait for the wasp to leave, then engage.",v=15}}
t[8623]={{tags="route hidden",text="The beacon lies in the northern mountains east of the Gaping Chasm in Tanaris, around 60,65 and 60,64.",v=37},{tags="route hidden",text="From the Chasm's northeast edge, follow the mountain edge to the white-sand vale, then take the brown path south; the beacon is just past the first rise.",v=10},{tags="patrol danger",text="Once activated, the beacon walks to the east-coast port near Steamwheedle, where three assassins attack it.",v=10}}
t[8663]={{tags="access",text="The Mithril Insignia is given by your faction's questgiver (Ox for Horde, Hank for Alliance) when he sends you to Booty Bay; this is a quest-access note, not a location.",v=3}}
t[8683]={{tags="inside hidden",text="Take the apples from the bowl on the table inside the small house just outside the Stormwind gate, at 33,57 in Elwynn Forest.",v=26}}
t[8704]={{tags="route",text="The robots carrying the beacon sit on a small rock in the water at 49,38; reaching them requires a route over the water.",v=23},{tags="access",text="You must be level 46 or higher to loot the beacon; lower-level characters cannot pick it up.",v=7}}
t[8705]={{tags="inside interact",text="Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale, at 53,55.",v=28},{tags="inside access",text="Once the escort starts the beacon leaves your pack. If the escort fails, delete the failed quest and re-enter the cave; the robot offers it again.",v=14},{tags="danger route",text="Three apes spawn near the bridge when the chicken warns of danger, and they can fail the escort quickly.",v=3}}
t[8707]={{tags="inside route",text="Once inside Zul'farrak, keep taking left turns to reach the boss.",v=7},{tags="access",text="The summoning mallet is a random drop in Hinterlands, not Zul'Farrak.",v=7},{tags="access",text="Gahz'rilla only drops this scale if the Gahz'rilla quest is in your quest log.",v=6}}
t[8724]={{tags="route",text="The tablet lies on a small island off the coast to the east, in the Overlook Cliffs.",v=8}}
t[8836]={{tags="spawn",text="Herb nodes respawn quickly around the corrupted lake in Felwood, so circling that area keeps the spawns coming.",v=3}}
t[8846]={{tags="access",text="Herbalism skill of 250 is required to pick Gromsblood.",v=70},{tags="spawn",text="Gromsblood spawns at these Blasted Lands points.",v=21},{tags="spawn",text="Southern Desolace has 15 Gromsblood spawn points, with up to 3 active at once; picked spots respawn in 15 to 20 minutes.",v=7}}
end)()
;(function() local t = C.i
t[8932]={{tags="inside interact",text="Buy it from the chef inside Theramore Isle Inn at 66,45; it is on the second page of the vendor list.",v=30}}
t[9153]={{tags="inside hidden",text="Inside Thermaplugg's room, look behind the third pillar from the right; the blueprints are on the ledge in a small, dark chest.",v=47}}
t[9238]={{tags="inside",text="Look inside Zul'Farrak, about halfway through, where there are roughly 50 scarabs.",v=7}}
t[9244]={{tags="floor inside",text="The shipment is on the upper floor of the larger two-story building in the walled pirate camp, on the right after entering the gated area.",v=33},{tags="route",text="Reach the walled pirate camp by swimming around its walls or through the small cave tunnel south of the port.",v=33},{tags="danger",text="Pirates guard the building: three on the first floor and a group of four at the stairs leading up to the second floor.",v=1}}
t[9246]={{tags="inside",text="Inside the camp, by the logs and fireplace.",v=5}}
t[9248]={{tags="inside hidden",text="Lord Shalzaru is inside the cave in the northwest corner of Isle of Dread, on a small piece of land surrounded by a lake.",v=9},{tags="route",text="Reach Isle of Dread by running southwest of Feathermoon and swimming across the sea, then fight toward the cave.",v=9},{tags="danger",text="Two level 43-44 sorceress guards stand on the land with Lord Shalzaru.",v=9}}
t[9250]={{tags="access",text="If you have already completed the quest this schedule starts, the item will not let you use it again.",v=6}}
t[9266]={{tags="spawn hidden",text="The plans sit on a wooden box in the small camp at 71,55; a larger bonfire camp just south at 72,56 also holds them, and some reports mention multiple spawn points.",v=45},{tags="access",text="Some players had to read the paper scroll and accept its quests before taking the plans back to camp.",v=11},{tags="interact",text="Click the object named Woodpaw Battle Map on the box to receive the plans.",v=8}}
t[9275]={{tags="spawn interact",text="Loot the Inconspicuous Landmark to make Cuergo's Treasure appear; five mobs then spawn, and one of them carries the key.",v=10}}
t[9277]={{tags="inside route",text="Techbot is inside the instance's back workshop area: pass the room before the back door, take the left wing (not the stairs on the right), and he is right there.",v=17}}
t[9306]={{tags="access interact",text="Right-click a Stave of Trojas in your inventory to create the Stave of Equinex.",v=8}}
t[9308]={{tags="inside route",text="Use the Sparklematic machines in the sparkle area of The Clean Room in Gnomeregan, a few steps left after entering.",v=9},{tags="danger",text="Expect about 28-30 guards and a level 29 medic in The Clean Room.",v=9},{tags="interact",text="Use the Sparklematic 5200 machine to clean each object, which turns it into a random item.",v=5}}
t[9316]={{tags="access",text="Each punch card machine needs the previous tier card (white, yellow, blue, red) in order; the prismatic card comes only from machine D with the red card.",v=45},{tags="floor inside route",text="Machine D is on the bottom floor of the Engineering Labs, in the archway toward Thermaplugg; use the elevator from the top floor.",v=20},{tags="floor route",text="Machine C is on the upper platform at the top of the Launch Bay, reached by the spider-machine mini-boss area.",v=20}}
t[9321]={{tags="",text="The Venom Bottle is on a table in Hiri'watha in the Hinterlands, at 31,57.",v=5},{tags="interact",text="Use the bottle on the table at 31,57 to start the Venom Bottles quest.",v=1}}
t[9322]={{tags="spawn",text="Turn in the looted sac quickly; it disappears about 30 minutes after you loot it.",v=51},{tags="access",text="The sac only drops while you have the quest active; killing spiders without the quest gives no drop.",v=5}}
t[9326]={{tags="inside route access",text="Clean the Grime-Encrusted Object in a Sparklematic machine in the Gnomeregan Clean Zone, reached down the stairs from the entrance, after accepting the cleaning quest.",v=24},{tags="inside route",text="The ring drops only from Dark Iron Agents in the last hallway leading to the final boss; other dungeon mobs do not drop it.",v=5}}
t[9328]={{tags="interact",text="Use the Super Snapper FX on the elite turtle in the Hinterlands; it reports an invalid target for anything else.",v=16}}
t[9330]={{tags="interact spawn",text="The snapshot still works if Gammerita is dead, and she respawns afterward.",v=20},{tags="patrol route",text="Gammerita walks the southeast beach of the Hinterlands near Revantusk village; go to about 80,59.",v=18},{tags="danger",text="Gammerita is a level 48 elite; stay alert on the beach around her.",v=4}}
t[9362]={{tags="inside",text="Dark Iron Dwarves just outside the final chamber of Gnomeregan drop the Grime-encrusted Ring that becomes this item.",v=19},{tags="interact access",text="Right-clicking the ring starts a quest to place it in Sparklematic 5200, after the 'Return the ring' quest.",v=19},{tags="inside access",text="Alliance: Talvash del Kissel in the Mystic Ward of Ironforge turns the ring in once you bring a silver bar, moss agate and 30 silver.",v=16}}
t[9364]={{tags="interact inside",text="Use the phial on a living Corrosive Lurker, a green slime in the Hall of Grears inside Gnomeregan.",v=6}}
t[9370]={{tags="hidden",text="The scroll lies behind a log next to a bonfire at this spot.",v=3},{tags="spawn",text="The scroll spawns in several places: near training dummies, next to a cauldron, and next to paintings.",v=2},{tags="inside hidden",text="At the cave entrance, the scroll is hidden behind a cauldron.",v=1}}
t[9371]={{tags="access",text="You must have the Gordunni quest to be able to loot the orb from the Mage-Lords.",v=2}}
t[9463]={{tags="access",text="Accept the quest to receive a shovel and reveal faint blue glows near the Dirt Mound markers; no activation is needed.",v=13},{tags="interact",text="Stand on the blue glow ring and use the shovel manually; there is no interaction cursor.",v=13},{tags="hidden inside",text="Blue glows are small and easy to miss; search for clusters outside the Gordunni caves, since they are impossible to see inside.",v=7}}
t[9472]={{tags="floor",text="The cage holding Sharpbeak sits at the top of a mountain, open to the sky.",v=2}}
t[9528]={{tags="access interact hidden",text="Right-click the Horn of Hatetalon near a Hatetalon stone: a stone with a hole in its middle, sparkles, and a faint flicker, found near the blue flame.",v=11},{tags="route",text="The Hatetalon stones lie north of the harpy area, with no other harpies nearby.",v=11},{tags="spawn",text="Edana takes about 30 seconds to appear after the horn is used at the stones.",v=11}}
t[9530]={{tags="spawn route access",text="Use the horn at 40,8 on the northern edge of the ruins, near the torch-lit path to the menhir with dancing lights; Edana appears after about 30 seconds.",v=35},{tags="interact",text="Do not use the horn while Edana's corpse is still present, or the horn is wasted and nothing is summoned.",v=32},{tags="spawn route",text="Edana appears in a swirl between two tall fang-like standing stones about 10 feet north of the purple-flame pillar circle, north of the ruins.",v=13}}
t[9590]={{tags="patrol",text="Wandering Forest Walkers roam their area, so they are hard to locate and may need a long search.",v=7},{tags="spawn",text="Walkers have been found in the High Wilderness of Feralas, west of Camp Mojache, and between Camp Mojache and Gordunni Outpost.",v=2},{tags="spawn",text="Walkers have been found at 76,40 and 73,57, and another near 57,47 just outside Dire Maul.",v=1}}
t[9593]={{tags="hidden",text="Treants are hard to see in Ferelas; look carefully for them.",v=18},{tags="patrol",text="Wandering Forest Walkers roam the zone rather than staying in one spot; check the map for their travel areas.",v=11},{tags="patrol",text="Use the Wandering Forest Walker, not the Cursed Sycamore. One wanders just outside Camp Mojache.",v=8}}
t[9594]={{tags="interact access route",text="Kill an Owlbeast in Hinterlands (around 36,51), loot its corpse first, then re-target the dead Owlbeast and use the Wildkin Muisek Vessel on it.",v=20}}
t[9978]={{tags="spawn danger",text="Gahz'ridian is found scattered throughout the desert; Southmoon and Eastmoon ruins hold many close together, guarded by 46-48 ogres.",v=9}}
t[10023]={{tags="access",text="The gloves must be crafted; the pattern is taught by Josephine Lister in the Magic Quarter of Undercity and crafting requires 230 Tailoring.",v=10}}
t[10025]={{tags="access",text="The pattern requires completing the Shadoweaver tailoring quest chain, which starts with Nilith Lokrav in Searing Gorge.",v=1},{tags="patrol",text="Shadow Silk Poachers wander Searing Gorge; one group was found around 56,26.",v=1}}
t[10036]={{tags="access",text="Craft it with Tailoring skill 250 using the Tuxedo Jacket, Pants and Shirt patterns.",v=57},{tags="floor inside route",text="The recipe is sold by an NPC on the upper stairs at the Tailor Guild in Ironforge.",v=1}}
t[10338]={{tags="route",text="The dead tree is in the Barrens near Thorn Hill, north-west of Ratchet; it is huge and easy to spot.",v=24}}
t[10441]={{tags="spawn access interact inside",text="After the sleeper awakens in Wailing Caverns, the Glowing Shard lies on the ground among the corpses; click it to start the quest.",v=163}}
t[10450]={{tags="",text="Feathers are no longer needed for any quest since patch 1.7 and can only be vendored.",v=39}}
t[10454]={{tags="inside interact",text="Click the Essence Font in the corner of the Shade of Eranikus room, in the Sunken Temple, to receive the trinket.",v=6},{tags="access interact danger",text="If you skipped the font, re-enter the lair and click it while Eranikus is in ghost form, sneaking past the mobs.",v=6}}
t[10455]={{tags="inside route",text="Take the trinket to the elf in a cave in the far southwest corner of the Swamp of Sorrows, below the footprint-shaped lake, to continue its quest.",v=7}}
t[10458]={{tags="inside spawn",text="The Prayer drops from mobs in or around the cave at 23,36, so hunt inside it.",v=2},{tags="access",text="The Prayer only drops after you have accepted the quest, so accept it before killing mobs.",v=2}}
t[10459]={{tags="inside",text="Chief Sharptusk is inside one of the huts in Bramble Blade Ravine, at 64,77 in Mulgore.",v=1},{tags="danger",text="Guards stand around the hut where he is.",v=1}}
t[10501]={{tags="access",text="Only Engineers can equip these goggles, and they require Engineering skill 220 to wear.",v=2}}
t[10504]={{tags="access",text="Wearing the Green Lens requires Engineering skill 245.",v=8}}
t[10507]={{tags="access",text="The recipe is taught only by Artisan or Master Engineers, such as Buzzek Bracketswing in Tanaris, requiring 225 engineering skill.",v=4}}
t[10509]={{tags="spawn",text="A bunch of the elementals that drop this can be found in the pit around 58,44.",v=6},{tags="spawn",text="Go to the lava areas in the Cauldron near 39,47 to find the elementals.",v=1},{tags="danger patrol",text="Three walking humanoids (two slavers and a taskmaster) wander the Cauldron area where the elementals are.",v=1}}
t[10538]={{tags="interact",text="Tablets lie scattered throughout the ruins as clickable objects; click them to pick one up.",v=2}}
t[10539]={{tags="hidden",text="Reported finds are at 41,64, 41,62, 40,63, 40.5,64.0, 43,64 and 40,62 among the ruins.",v=8},{tags="hidden",text="The tablet lies on the ground in corners of the ruins, tucked behind buildings, rocks or fallen pillars, and is easy to miss.",v=6},{tags="route",text="One find lies south east of the main ruins, sitting along the path well away from the ruins.",v=1}}
t[10548]={{tags="interact",text="Put the scope in the trade window's modify box so an engineer can install it on your weapon.",v=5}}
t[10551]={{tags="spawn",text="Geologists at the Grimesilt dig site camp respawn quickly, so the camp can be farmed repeatedly.",v=2},{tags="inside route",text="Slave Workers and Dark Iron Slavers are in a cave in the middle chasm area; drop down to reach it.",v=2}}
t[10552]={{tags="route danger",text="Approach over the hill southwest of the Thorium Point path exit to avoid the level 49 fire mobs and 50s on the right.",v=4},{tags="inside",text="The elite mobs inside the cavern can all drop the Symbol, so any of them will do.",v=2},{tags="inside route",text="The Symbol mobs are in the cave below, not the camp above with the lava pit; the cave spot is near 22,36.",v=1}}
t[10556]={{tags="route",text="The chest sits right outside the entrance of Liv Rizzlefix's goblin house in Ratchet, on the right side as you enter, and is not near the shack or wooden tower.",v=75},{tags="route",text="From the docks in Ratchet, go left to the small goblin house with a green roof that overlooks the ocean.",v=22}}
t[10562]={{tags="interact",text="Stand completely still to use this bomb; moving cancels its 1-second cast.",v=3}}
t[10563]={{tags="route",text="The rubbing is picked up on the island at 78,91.",v=24},{tags="route",text="Go to 36,53 in the Ruins of Eldarath on Cosmos to find the rune.",v=18}}
t[10566]={{tags="inside",text="The rubbing lies at 42,64 in the south east section of the Ruins of Eldarath on Cosmos; the spot is inside the ruins even though it looks off on the map.",v=7}}
t[10575]={{tags="inside route access",text="Get the molt from the dragon in a cave in the northeast of Burning Steppes; follow the east wall to reach it.",v=119},{tags="access spawn interact",text="In Searing Gorge, finish the quests from the two NPCs near the drop point to get the chest containing the molt; the box appears next to the slain guy after the dragon spawns.",v=40},{tags="access",text="Finishing the trinkets portion of the Set Them Ablaze quest line gives a bag that contains the molt.",v=20}}
t[10589]={{tags="inside route",text="Talk to Itharius, an elf in the cave in the southwest of Swamp of Sorrows, to get the Oathstone.",v=29},{tags="access",text="You must already have the Chained Essence before Itharius will give you the Oathstone.",v=29}}
t[10592]={{tags="access",text="The potion is made from a recipe that is trained by the Artisan trainer at Expert level in Darnassus, so you need that recipe first.",v=1}}
t[10621]={{tags="patrol",text="The LvL 25 elite mobs that drop this scroll patrol the southern Barrens on mounts and sometimes follow the road.",v=16}}
t[10646]={{tags="access",text="Crafting or using the Goblin Sapper Charge requires 205 Engineering skill.",v=4},{tags="access",text="You must learn the recipe from the Goblin engineering trainer in Gadgetzan before you can craft this charge.",v=2}}
t[10691]={{tags="route",text="Four vials lie at the water's edge, not in the water, at 47,60; 47,51; 48,48; and 47,46.",v=47},{tags="route",text="The four pools are separate from the sea and surrounded by sand or rock; number them south to north and start at the southernmost.",v=18}}
t[10699]={{tags="interact",text="Use the bramble on Vale Screecher or Rogue Vale Screecher corpses.",v=1}}
t[10717]={{tags="spawn route",text="The compass is a random quest item found in one of several equipment containers spread around the area, with the best place to look up on the hill.",v=22}}
