t[10789]={{tags="inside route",text="In Ratchet (the Barrens), go behind the bank building to find the building where Tinkerwiz sells the manual.",v=12},{tags="route",text="Alliance players can instead find Springspindle Fizzlegear, the Artisan Engineer, in Tinker Town in Ironforge.",v=5}}
t[10819]={{tags="spawn",text="Feathers are ground objects, not mob drops. Look for them lying on the ground across the Hinterlands, especially around the 34,46 area.",v=15},{tags="hidden",text="Set ground clutter to minimum in graphics settings, since high clutter hides the feathers under weeds.",v=6},{tags="interact",text="Hover over the feather on the ground until the cursor changes to a wheel, then click it to loot.",v=2}}
t[10839]={{tags="interact",text="Loot the human statues in southern Azshara to get this note; it can drop even without the Azsharite quest.",v=5}}
t[10958]={{tags="hidden interact",text="The necklace is hidden in a Glinting Mud pile in the lake, usually just before the bridge near 37-38,54; open the mud pile to recover it.",v=7},{tags="hidden interact route",text="The mud pile is hard to see on the lake bottom; swim down and move the cursor around until the open-able mud pile is highlighted.",v=4},{tags="hidden route",text="Look for it at the end of a submerged log or beside rocks in the water south and west of the dock, around 24,54 or 21,53.",v=3}}
t[10999]={{tags="patrol",text="He patrols between a chair and the spot where the golem and dwarves were killed, so he moves along that path.",v=6},{tags="danger",text="He is guarded by many guards; a golem and two dwarves stand near him as well.",v=6},{tags="route",text="He is on the far side of the bridge from Incendius.",v=6}}
t[11018]={{tags="hidden",text="Look for the Un'Goro Soil in piles on the ground, it is hard to spot; turn Ground Clutter to 1 in graphics settings to see it from a distance.",v=54}}
t[11040]={{tags="access",text="Morrowgrain is not gathered from nodes; it comes only from opening Evergreen Herb Casings grown with the Evergreen Pouch from the Morrowgrain Research quest.",v=153},{tags="spawn",text="A new Evergreen Herb Casing can be grown once every 10 minutes.",v=153}}
t[11102]={{tags="access",text="Only Alliance characters can get this; it is the final quest in the sprite darter chain.",v=4}}
t[11112]={{tags="route",text="Find the research equipment at a small camp at 39,66: go to the bottom-right corner of the chubby L-shaped lake and walk a little straight south.",v=31}}
t[11114]={{tags="floor route",text="Pick up the bones lying on the ground around the dead half-eaten dinosaur in the southwest of Un'Goro Crater.",v=16},{tags="danger",text="Elite dinosaurs stand near the bones at 31,78; their aggro radius is small, so approach carefully.",v=16}}
t[11116]={{tags="",text="Each player can turn it in only once; before turning it in it keeps dropping, and it cannot be turned in again.",v=11},{tags="",text="Once the quest is done the item no longer drops; the low drop rate people see is because they already completed it.",v=5}}
t[11119]={{tags="interact route",text="Find the grapes in the field behind the Abbey and open them like chests; the item does not drop from the Thugs.",v=4}}
t[11127]={{tags="route",text="Look around the back of the abandoned houses for them.",v=15}}
