t[11149]={{tags="inside",text="The cave where the boss is found lies at 62,4.",v=21},{tags="inside",text="The boss stands inside the cave, at the back of the room.",v=9}}
t[11169]={{tags="interact",text="Use the book to summon Aquementas again after the quest is finished.",v=45}}
t[11172]={{tags="",text="Hunt Angerclaw Grizzly bears in the Ironwood area, north of southern Feralas.",v=9},{tags="",text="Felpaw Wolves just behind the Emerald Sanctuary also drop the claws.",v=7},{tags="spawn",text="Angerclaw Maulers spawn in groups of about 10 to 12 around 38,44.",v=2}}
t[11173]={{tags="access",text="Only drops from Irontree Stompers in Irontree Woods, northern Felwood, while you have the quest; without it the drop is very rare.",v=55}}
t[11179]={{tags="inside hidden",text="Look inside the cave where Blazerunner is; the item sits in a small box on a rocky shelf.",v=3}}
t[11184]={{tags="access inside",text="Turn in seven of each crystal color at the cave by the Un'Goro camp to get the book needed before the pylons will give Blue Power Crystals.",v=52}}
t[11185]={{tags="access inside",text="First turn in seven each of red, blue, yellow and green crystals at the cave's end by the Un'Goro camp to get the book, then bring 10 each of two colors to a crystal pylon.",v=40}}
t[11186]={{tags="route",text="Red crystal nodes are in western Un'Goro near the crater rim by Golakka Hot Springs.",v=7},{tags="hidden route",text="Red crystals can be found in a stump; some are in hard-to-reach side channels up in the mountains where pterodaxes fly.",v=1}}
t[11188]={{tags="hidden route",text="Yellow crystals are hidden in the hills around the edge of Un'Goro Crater, back along the paths there.",v=1}}
t[11227]={{tags="danger",text="Krom'zar is an elite with about 10 adds around him, so expect heavy resistance where the banner piece is obtained.",v=6}}
t[11242]={{tags="danger access",text="A gnoll stands in front of the building's door; buy Bait from Gregan Brewspewer at 44,25 and drop it near the gnoll to draw it away.",v=40},{tags="route hidden",text="Reach the room by jumping onto the ledge at the back of the building through the crack in the broken corner.",v=33},{tags="route",text="Mages can blink through the back wall of the building to get inside without bait.",v=10}}
